'(',
'    select process,',
'        case when remdq(json_serialize(status)) = ''running'' then 1 else 0 end running,',
'        case when remdq(json_serialize(status)) = ''abended'' then 1 else 0 end abended,',
'        case when remdq(json_serialize(status)) = ''stopped'' then 1 else 0 end stopped',
'    from',
'    (',
'        select distinct a.process,a.res.response.status status from extractdetail a where user_id = ''&APP_USER.'' and session_id = ''&APP_SESSION.''',
'    )',
')',
'union all',
