wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(10032273536798099)
,p_plug_name=>'GoldenGate Documents'
,p_static_id=>'ogg-docs-region'
,p_region_template_options=>'#DEFAULT#'
,p_escape_on_http_output=>'Y'
,p_plug_template=>wwv_flow_imp.id(141233967273679007010)
,p_plug_display_sequence=>80
,p_plug_new_grid=>true
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<style>',
'#ogg-docs-toggle{',
'  display:flex;align-items:center;gap:10px;',
'  cursor:pointer;',
'  padding:10px 14px;',
'  background:#161b22;',
'  border:1px solid #30363d;',
'  border-radius:8px;',
'  width:fit-content;',
'  transition:border-color .2s,background .2s;',
'  user-select:none;',
'}',
'#ogg-docs-toggle:hover{border-color:#e94560;background:#1c2128;}',
'#ogg-docs-toggle-label{',
'  font-size:13px;font-weight:700;color:#8b949e;',
'  text-transform:uppercase;letter-spacing:1.2px;',
'}',
'#ogg-docs-arrow{',
'  font-size:11px;color:#e94560;',
'  transition:transform .25s;',
'  display:inline-block;',
'}',
