'        select remdq(json_serialize(process)) process',
'        from ',
'        (',
'            select a.res.response.items[0].name process from extracts a',
'            union all',
'            select a.res.response.items[1].name from extracts a',
'            union all',
'            select a.res.response.items[2].name from extracts a',
'            union all',
'            select a.res.response.items[3].name from extracts a',
