wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(19540895435254587)
,p_event_id=>wwv_flow_imp.id(19538907840254586)
,p_event_result=>'TRUE'
,p_action_sequence=>40
,p_execute_on_page_init=>'N'
,p_static_id=>'native-execute-plsql-code'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'DECLARE',
    '	l_response      CLOB;',
    '	v_sql varchar2(4000) := '''' ;',
    '	v_base_url varchar2(200) := '''';',
    '    v_process varchar2(200) := '''';',
    '    v_domain varchar2(200) := '''';',
    '    v_alias varchar2(200) := '''';',
    '    v_body varchar2(4000) := '''';',
    '    v_schema_name varchar2(200) := '''';',
    '    v_tables varchar2(200) := '''';',
    '    l_order_obj  JSON_OBJECT_T;',
    '',
    '',
    'BEGIN',
    '',
    '	select gubun1 ||'':''||gubun2||gubun3 into v_base_url',
    '	from ogg_conf',
    '	where keya = ''REPLICATURL'' ',
    '	and keyb = ''ADMIN''',
    '	;',
    '',
    '    v_body := ''',
    '    {',
    '        "name": "report",',
    '        "reportType": "checkpointTables",',
    '        "credentials": {',
    '            "alias": "&P3_ALIAS_DISPLAY."',
    '        },',
    '        "specification": "*.*"',
    '    }    ',
    '    '';',
    '',
    '	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
    '',
    '	l_response := apex_web_service.make_rest_request ',
    '	(',
    '		p_url                  => v_base_url || ''/commands/execute'', ',
    '        --p_url                  => ''http://172.28.0.5:9012/services/OGGHUB/adminsrvr/v2/commands/execute'', ',
    '		p_http_method          => ''POST'', ',
    '        p_body                 => v_body,',
    '		--p_transfer_timeout     => 10, ',
    '		p_username             => ''oggadmin'', ',
    '		p_password             => ''WElcome1234##'',',
    '		p_scheme               => ''Basic''',
    '	); ',
    '',
    '',
    '    begin',
    '        execute immediate ''truncate table ggsckpt'';',
    '        execute immediate ''truncate table tmp'';',
    '    end;',
    '        ',
    '',
    '    insert into tmp values (''domain : &P3_DOMAIN_DISPLAY.'',sysdate);',
    '    insert into tmp values (''alias : &P3_ALIAS_DISPLAY.'',sysdate);',
    '    insert into tmp values (l_response,sysdate);    ',
    '    commit;',
    '',
    '',
    '    insert into ggsckpt',
    '    select id,''&P3_DOMAIN_DISPLAY.'' domain,''&P3_ALIAS_DISPLAY.'' alias, a.table_name ',
    '    from',
    '    (',
    '        select ''1'' id,a.table_name ',
    '        from JSON_TABLE(l_response, ',
    '            ''$[*]'' COLUMNS (',
    '                table_name varchar2(4000) PATH ''$.response.tables[0]''',
    '                ) ',
    '            ) a ',
    '        union all',
    '        select ''2'' id,a.table_name ',
    '        from JSON_TABLE(l_response, ',
    '            ''$[*]'' COLUMNS (',
    '                table_name varchar2(4000) PATH ''$.response.tables[1]''',
    '                ) ',
    '            ) a         ',
    '        union all',
    '        select ''3'' id,a.table_name ',
    '        from JSON_TABLE(l_response, ',
    '            ''$[*]'' COLUMNS (',
    '                table_name varchar2(4000) PATH ''$.response.tables[2]''',
    '                ) ',
    '            ) a         ',
    '        union all',
    '        select ''4'' id,a.table_name ',
    '        from JSON_TABLE(l_response, ',
    '            ''$[*]'' COLUMNS (',
    '                table_name varchar2(4000) PATH ''$.response.tables[3]''',
    '                ) ',
    '            ) a         ',
    '        union all',
    '        select ''5'' id,a.table_name ',
    '        from JSON_TABLE(l_response, ',
    '            ''$[*]'' COLUMNS (',
    '                table_name varchar2(4000) PATH ''$.response.tables[4]''',
    '                ) ',
    '            ) a   ',
    '    ) a',
    '    where a.table_name is not null',
    '    ;',
    '    commit;',
    '    ',
    '	v_sql := ''',
    '        select a.id idno,a.domain ,a.alias,a.ckpt "Checkpoint Table" from ggsckpt a',
    '    '';',
    '	',
    '	--return v_sql;',
    '',
    'END;',
    '')),
  'show_processing', 'N')).to_clob
,p_wait_for_result=>'Y'
);
