,p_plug_name=>'New'
,p_static_id=>'new'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(141233965818187007009)
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'	l_response      CLOB;',
'	--v_sql varchar2(4000) := '''' ;',
'    v_sql clob := '''' ;',
'	v_base_url varchar2(200) := '''';',
'    v_process varchar2(200) := '''';',
'	v_upper_process varchar2(200) := '''';',
'	v_body varchar2(4000) := '''';',
'	',
'    cursor c1 ',
'    is',
'        select remdq(json_serialize(process)) process',
'        from ',
'        (',
'            select a.session_id,a.res.response.items[0].name process from extracts a',
'            union all',
'            select a.session_id,a.res.response.items[1].name from extracts a',
'            union all',
'            select a.session_id,a.res.response.items[2].name from extracts a',
'            union all',
'            select a.session_id,a.res.response.items[3].name from extracts a',
'            union all',
'            select a.session_id,a.res.response.items[4].name from extracts a',
'            union all',
'            select a.session_id,a.res.response.items[5].name from extracts a',
'            union all',
'            select a.session_id,a.res.response.items[6].name from extracts a',
'            union all',
'            select a.session_id,a.res.response.items[7].name from extracts a',
'            union all',
'            select a.session_id,a.res.response.items[8].name from extracts a',
'            union all',
'            select a.session_id,a.res.response.items[9].name from extracts a',
'        )',
'        where process is not null',
'        and session_id = ''&APP_SESSION.''',
'        ; ',
'        	',
'BEGIN',
'',
'	select gubun1 ||'':''||gubun2||gubun3 into v_base_url',
'	from ogg_conf',
'	where keya = ''EXTRACTURL'' ',
'	and keyb = ''ADMIN''',
'	;',
'',
'    insert into tmp (res) values (v(''APP_SESSION''));',
'    commit;',
'',
'',
'    insert into tmp (res) values (v(''APP_USER''));',
'    commit;',
'',
'',
'    insert into tmp (res) values (''&APP_USER.'');',
'    commit;',
'',
'',
'    select upper(''&P4_PROCESS.'') into v_upper_process from dual;',
'',
'    insert into tmp (res) values (v_upper_process);',
'    commit;',
'	',
'	',
'	v_body := ''',
'	{',
'		"command": "SHOWTRANS",',
'		"isReported": true',
'	}        ',
'	'';',
'',
'	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'	l_response := apex_web_service.make_rest_request ',
'	(',
'		p_url                  => v_base_url || ''/extracts/''||v_upper_process||''/command'', ',
'        --p_url                  => ''http://172.28.0.5:9112/services/v2'' || ''/extracts'', ',
'		p_http_method          => ''POST'', ',
'		--p_transfer_timeout     => 10, ',
'        p_body                 => v_body,		',
'		p_username             => ''oggadmin'', ',
'		p_password             => ''WElcome1234##'',',
'		p_scheme               => ''Basic''',
'	); ',
'',
'	--dbms_output.put_line(''Response Status : '' || apex_web_service.g_status_code);',
'	--dbms_output.put_line(''Response Payload: '' || l_response);',
'	--begin',
'        --execute immediate ''truncate table extracts'';',
'    --end;',
'',
'',
'',
'    insert into tmp (res) values (''v_base_url: ''||v_base_url || ''/extracts/''''||v_upper_process||''''/command'');',
'    commit;',
'	',
'	',
'	',
'    delete from EXTRACTTRANS',
'    where user_id = ''&APP_USER.''',
'    and session_id = ''&APP_SESSION.'';',
'',
'    insert into EXTRACTTRANS (user_id,session_id,process,res,stat) values (v(''APP_USER''),v(''APP_SESSION''),v_upper_process,l_response,apex_web_service.g_status_code);',
'    commit;',
'',
'',
'	v_sql := ''',
'        select process, msg, status_val,',
'            xid,',
'            scn,',
'            redoSeq,',
'            redoRba',
'        from',
'        (    ',
'    		select process, ',
'                ''''     Please kill or skip long running session '''' msg,',
'                ''''warning'''' status_val,',
'                remdq(json_serialize(a.res.response.replyData.currentInflightTransactions.xid)) xid,',
'    			remdq(json_serialize(a.res.response.replyData.currentInflightTransactions.scn)) scn,',
'    			remdq(json_serialize(a.res.response.replyData.currentInflightTransactions.redoSeq)) redoSeq,',
'    			remdq(json_serialize(a.res.response.replyData.currentInflightTransactions.redoRba)) redoRba',
'    		from extracttrans a',
'            where process is not null',
'            and session_id = ''''&APP_SESSION.''''        ',
'        )',
'        where xid is not null',
'    '';',
'	',
'	return v_sql;',
'',
'END;',
''))
,p_template_component_type=>'REPORT'
,p_lazy_loading=>false
,p_plug_source_type=>'TMPL_THEME_42$CONTENT_ROW'
,p_plug_query_num_rows=>15
,p_plug_query_num_rows_type=>'SET'
,p_show_total_row_count=>false
,p_landmark_type=>'region'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'APPLY_THEME_COLORS', 'Y',
  'BADGE_COL_WIDTH', 't-ContentRow-badge--md',
  'BADGE_LABEL', '&STATUS_VAL.',
  'BADGE_LABEL_DISPLAY', 'N',
  'BADGE_STATE', 'STATUS_VAL',
  'BADGE_VALUE', 'STATUS_VAL',
  'DESCRIPTION', wwv_flow_string.join(wwv_flow_t_varchar2(
    '<b><b>&MSG. &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</b></b><br>',
    '<b><b>XID : ',
    '&XID. &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;',
    'SCN : ',
    '&SCN. ',
    '</b></b><br><br>')),
  'DISPLAY_AVATAR', 'N',
  'DISPLAY_BADGE', 'Y',
  'HIDE_BORDERS', 'N',
  'REMOVE_PADDING', 'N')).to_clob
);
