wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(8660682681909277)
,p_event_id=>wwv_flow_imp.id(8660570534909276)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_static_id=>'native-execute-plsql-code'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'DECLARE',
    '	l_response      CLOB;',
    '	v_sql varchar2(4000) := '''' ;',
    '	v_base_url varchar2(200) := '''';',
    '    v_process varchar2(200) := '''';',
    '    v_body varchar2(4000) := '''';',
    '    v_status varchar2(200) := '''';',
    '    v_xid varchar2(200) := '''';',
    '	',
    'BEGIN',
    '',
    '',
    '	select gubun1 ||'':''||gubun2||gubun3 into v_base_url',
    '	from ogg_conf',
    '	--where keya = ''EXTRACTPOST'' ',
    '    where keya = ''EXTRACTURL'' ',
    '	and keyb = ''ADMIN''',
    '	;',
    '',
    '',
    '',
    '',
    '    select ',
    '        remdq(json_serialize(a.res.response.replyData.currentInflightTransactions.xid)) into v_xid',
    '    from extracttrans a',
    '    where process is not null',
    '    and session_id = ''&APP_SESSION.''',
    '    ;',
    '',
    '/*',
    '    select upper(''&P8_PROCESS.'') into v_process ',
    '    from dual;',
    '    select distinct remdq(json_serialize(a.res.response.status)) into v_status',
    '    from replicatstatus a',
    '    where user_id = ''&APP_USER.''',
    '    and session_id = ''&APP_SESSION.''',
    '    and process = v_process',
    '    ;',
    '',
    '',
    '    insert into tmp values (''status : ''|| v_status,sysdate);',
    '    commit;',
    '*/    ',
    '',
    '    select upper(''&P4_PROCESS.'') into v_process from dual;',
    '',
    '    v_body := ''{',
    '        "command": "SKIPTRANS",',
    '        "arguments": "''||v_xid||''",',
    '        "isReported": true',
    '    }'';',
    '',
    '    insert into tmp values (''v_body : ''|| v_body,sysdate);',
    '    commit;',
    '    ',
    '',
    '    insert into tmp values (''p_url : ''|| v_base_url || ''/extracts/''||v_process||''/command'',sysdate);',
    '    commit;',
    '    ',
    '',
    '	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
    '',
    '	l_response := apex_web_service.make_rest_request ',
    '	(',
    '		p_url                  => v_base_url || ''/extracts/''||v_process||''/command'', ',
    '		p_http_method          => ''POST'', ',
    '		--p_transfer_timeout     => 10, ',
    '        p_body                 => v_body,',
    '		p_username             => ''oggadmin'', ',
    '		p_password             => ''WElcome1234##'',',
    '		p_scheme               => ''Basic''',
    '	); ',
    '',
    '	--dbms_output.put_line(''Response Status : '' || apex_web_service.g_status_code);',
    '	--dbms_output.put_line(''Response Payload: '' || l_response);',
    '',
    '    insert into tmp values (''v_body : ''|| v_body,sysdate);',
    '    commit;',
    '	',
    '    insert into tmp values (l_response,sysdate);',
    '    commit;    ',
    'END;')),
  'show_processing', 'N')).to_clob
,p_wait_for_result=>'Y'
);
