wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(18736262696744933)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'execute'
,p_static_id=>'execute'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'	l_response      CLOB;',
'	v_sql varchar2(4000) := '''' ;',
'	v_base_url varchar2(200) := '''';',
'    v_process varchar2(200) := '''';',
'    v_body varchar2(4000) := '''';',
'    v_status varchar2(200) := '''';',
'	',
'BEGIN',
'',
'',
'	select gubun1 ||'':''||gubun2||gubun3 into v_base_url',
'	from ogg_conf',
'	where keya = ''EXTRACTURL'' ',
'	and keyb = ''ADMIN''',
'	;',
'',
'    select upper(''&P4_PROCESS.'') into v_process ',
'    from dual;',
'',
'    select distinct remdq(json_serialize(a.res.response.status)) into v_status',
'    from extractstatus a',
'    where user_id = ''&APP_USER.''',
'    and session_id = ''&APP_SESSION.''',
'    and process = v_process',
'    ;',
'',
'    if v_status = ''stopped'' or v_status = ''abended'' then',
'',
'        v_body := ''{',
'            "name":"start",',
'            "processName":"''||v_process||''"',
'        }'';',
'',
'    	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'    	l_response := apex_web_service.make_rest_request ',
'    	(',
'    		p_url                  => v_base_url || ''/commands/execute'', ',
'    		p_http_method          => ''POST'', ',
'    		--p_transfer_timeout     => 10, ',
'            p_body                 => v_body,',
'    		p_username             => ''oggadmin'', ',
'    		p_password             => ''WElcome1234##'',',
'    		p_scheme               => ''Basic''',
'    	); ',
'',
'    	--dbms_output.put_line(''Response Status : '' || apex_web_service.g_status_code);',
'    	--dbms_output.put_line(''Response Payload: '' || l_response);',
'',
'        insert into tmp values (''v_body : ''|| v_body,sysdate);',
'        commit;',
'    	',
'        insert into tmp values (l_response,sysdate);',
'        commit;',
'    elsif v_status = ''running'' then',
'',
'        v_body := ''{',
'            "name":"stop",',
'            "processName":"''||v_process||''"',
'        }'';',
'',
'    	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'    	l_response := apex_web_service.make_rest_request ',
'    	(',
'    		p_url                  => v_base_url || ''/commands/execute'', ',
'    		p_http_method          => ''POST'', ',
'    		--p_transfer_timeout     => 10, ',
'            p_body                 => v_body,',
'    		p_username             => ''oggadmin'', ',
'    		p_password             => ''WElcome1234##'',',
'    		p_scheme               => ''Basic''',
'    	); ',
'',
'    	--dbms_output.put_line(''Response Status : '' || apex_web_service.g_status_code);',
'    	--dbms_output.put_line(''Response Payload: '' || l_response);',
'',
'        insert into tmp values (''v_body : ''|| v_body,sysdate);',
'        commit;',
'    	',
'        insert into tmp values (l_response,sysdate);',
'        commit;    ',
'    end if;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>11307920066291828
);
end;
/
prompt --application/pages/page_00005
begin
wwv_flow_imp_page.create_page(
 p_id=>5
,p_name=>'Report Extract'
,p_alias=>'REPORT-EXTRACT'
,p_step_title=>'Report Extract'
,p_autocomplete_on_off=>'OFF'
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
