'',
'    	l_response := apex_web_service.make_rest_request ',
'    	(',
'    		p_url                  => v_base_url || ''/extracts/''||v_upper_process||''/info/reports/''||v_report, ',
'            --p_url                  => ''http://172.28.0.5:9112/services/v2'' || ''/replicats'', ',
'    		p_http_method          => ''GET'', ',
'    		--p_transfer_timeout     => 10, ',
'    		p_username             => ''oggadmin'', ',
'    		p_password             => ''WElcome1234##'',',
'    		p_scheme               => ''Basic''',
'    	); ',
'',
'        insert into reportdetail_tmp (report,res,stat) values (v_report,l_response,apex_web_service.g_status_code);',
'        commit;',
'        ',
'        insert into reportdetail (report,res,stat) values (v_report,l_response,apex_web_service.g_status_code);',
'        commit;',
'        ',
'        update reportdetail a',
'        set res = substr(a.res,instr(a.res,''lines'')+8)',
'        ;',
'/*',
'        insert into reportdetail ',
'        select v_report,a.lines,null,sysdate ',
'        from JSON_TABLE(l_response, ',
'            ''$[*]'' COLUMNS (',
'                lines clob PATH ''$.response.lines''',
'                ) ',
'            ) a ',
'        ;',
