'*/        ',
'    end loop;',
'',
'    ',
'	v_sql := ''',
'        select remdq(json_serialize(name)) process',
'        from',
'        (',
'            select a.res.response.items[0].name name from extracts a',
'            union all',
'            select a.res.response.items[1].name from extracts a',
'            union all',
