,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'@font-face{',
'font-family:''Peyda'';',
'src:url(''#WORKSPACE_FILES#Peyda-Regular.ttf'') format(''truetype'') !important;',
