,p_step_template=>wwv_flow_imp.id(141233931299871006969)
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'17'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(64665564654440474)
,p_plug_name=>'Report'
,p_static_id=>'report'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_escape_on_http_output=>'Y'
,p_plug_template=>wwv_flow_imp.id(141234097036331007039)
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_02'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'	l_response      CLOB;',
'	v_sql varchar2(4000) := '''' ;',
'	v_base_url varchar2(200) := '''';',
'    v_upper_process varchar2(200) := '''';',
'    v_report varchar2(200) := '''';',
'',
'    cursor c1',
'    is',
'        select remdq(json_serialize(name)) process',
'        from',
'        (',
'            select a.res.response.items[0].name name from reports a',
'            union all',
'            select a.res.response.items[1].name from reports a',
'            union all',
'            select a.res.response.items[2].name from reports a',
'            union all',
'            select a.res.response.items[3].name from reports a',
'            union all',
'            select a.res.response.items[4].name from reports a',
'            union all',
'            select a.res.response.items[5].name from reports a',
'            union all',
'            select a.res.response.items[6].name from reports a',
'            union all',
'            select a.res.response.items[7].name from reports a',
'            union all',
'            select a.res.response.items[8].name from reports a',
'            union all',
'            select a.res.response.items[9].name from reports a',
'            union all',
'            select a.res.response.items[10].name from reports a',
'            union all',
'            select a.res.response.items[11].name from reports a',
'            union all',
'            select a.res.response.items[12].name from reports a',
'            union all',
'            select a.res.response.items[13].name from reports a',
'            union all',
'            select a.res.response.items[14].name from reports a',
'            union all',
'            select a.res.response.items[15].name from reports a',
'            union all',
'            select a.res.response.items[16].name from reports a',
'            union all',
'            select a.res.response.items[17].name from reports a',
'            union all',
'            select a.res.response.items[18].name from reports a',
'            union all',
'            select a.res.response.items[19].name from reports a',
'            union all',
'            select a.res.response.items[20].name from reports a',
'        )',
'        where name is not null',
'        and name like ''%rpt'';',
'',
'BEGIN',
'',
'	select gubun1 ||'':''||gubun2||gubun3 into v_base_url',
'	from ogg_conf',
'	where keya = ''REPLICATURL'' ',
'	and keyb = ''ADMIN''',
'	;',
'',
'    select ''&P7_PROCESS.'' into v_upper_process from dual;',
'',
'	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'	l_response := apex_web_service.make_rest_request ',
'	(',
'		p_url                  => v_base_url || ''/replicats/''||v_upper_process||''/info/reports'', ',
'        --p_url                  => ''http://172.28.0.5:9112/services/v2'' || ''/replicats'', ',
'		p_http_method          => ''GET'', ',
'		--p_transfer_timeout     => 10, ',
'		p_username             => ''oggadmin'', ',
'		p_password             => ''WElcome1234##'',',
'		p_scheme               => ''Basic''',
'	); ',
'',
'	--dbms_output.put_line(''Response Status : '' || apex_web_service.g_status_code);',
'	--dbms_output.put_line(''Response Payload: '' || l_response);',
'	begin',
'        execute immediate ''truncate table reports'';',
'        execute immediate ''truncate table reportdetail'';',
'        execute immediate ''truncate table reportdetail_tmp'';',
'    end;',
'    ',
'    insert into reports (res,stat) values (l_response,apex_web_service.g_status_code);',
'    commit;',
'',
'    open c1;',
'    loop',
'        fetch c1 into v_report;',
'        exit when c1%NOTFOUND;',
'',
'    	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'    	l_response := apex_web_service.make_rest_request ',
'    	(',
'    		p_url                  => v_base_url || ''/replicats/''||v_upper_process||''/info/reports/''||v_report, ',
'            --p_url                  => ''http://172.28.0.5:9112/services/v2'' || ''/replicats'', ',
'    		p_http_method          => ''GET'', ',
'    		--p_transfer_timeout     => 10, ',
'    		p_username             => ''oggadmin'', ',
'    		p_password             => ''WElcome1234##'',',
'    		p_scheme               => ''Basic''',
'    	); ',
'',
'        insert into reportdetail_tmp (report,res,stat) values (v_report,l_response,apex_web_service.g_status_code);',
'        commit;',
'        ',
'        insert into reportdetail (report,res,stat) values (v_report,l_response,apex_web_service.g_status_code);',
'        commit;',
'        ',
'        update reportdetail a',
'        set res = substr(a.res,instr(a.res,''lines'')+8)',
'        ;',
'/*',
'        insert into reportdetail ',
'        select v_report,a.lines,null,sysdate ',
'        from JSON_TABLE(l_response, ',
'            ''$[*]'' COLUMNS (',
'                lines clob PATH ''$.response.lines''',
'                ) ',
'            ) a ',
'        ;',
'        commit;',
'*/        ',
'    end loop;',
'',
'    ',
'	v_sql := ''',
'        select remdq(json_serialize(name)) process',
'        from',
'        (',
'            select a.res.response.items[0].name name from reports a',
'            union all',
'            select a.res.response.items[1].name from reports a',
'            union all',
'            select a.res.response.items[2].name from reports a',
'            union all',
'            select a.res.response.items[3].name from reports a',
'            union all',
'            select a.res.response.items[4].name from reports a',
'            union all',
'            select a.res.response.items[5].name from reports a',
'            union all',
'            select a.res.response.items[6].name from reports a',
'            union all',
'            select a.res.response.items[7].name from reports a',
'            union all',
'            select a.res.response.items[8].name from reports a',
'            union all',
'            select a.res.response.items[9].name from reports a',
'            union all',
'            select a.res.response.items[10].name from reports a',
'            union all',
'            select a.res.response.items[11].name from reports a',
'            union all',
'            select a.res.response.items[12].name from reports a',
'            union all',
'            select a.res.response.items[13].name from reports a',
'            union all',
'            select a.res.response.items[14].name from reports a',
'            union all',
'            select a.res.response.items[15].name from reports a',
'            union all',
'            select a.res.response.items[16].name from reports a',
'            union all',
'            select a.res.response.items[17].name from reports a',
'            union all',
'            select a.res.response.items[18].name from reports a',
'            union all',
'            select a.res.response.items[19].name from reports a',
'            union all',
'            select a.res.response.items[20].name from reports a',
'        )',
'        where name is not null',
'        and name like ''''%rpt''''',
'    '';',
'	',
'	return v_sql;',
'',
'END;'))
,p_plug_source_type=>'NATIVE_JQM_LIST_VIEW'
,p_plug_query_num_rows=>15
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'link_target', 'f?p=&APP_ID.:174:&SESSION.::&DEBUG.:174:P174_PROCESS:&PROCESS.',
  'text_column', 'PROCESS')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(64771091324538616)
,p_name=>'P7_PROCESS'
,p_item_sequence=>20
,p_source_type=>'ALWAYS_NULL'
,p_display_as=>'NATIVE_HIDDEN'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'value_protected', 'Y')).to_clob
);
end;
/
