'        ',
unistr('        -- \D558\B2E8 \D478\D130'),
'        ''<div style="background: #f9fafb; padding: 10px 20px; border-top: 1px solid #f3f4f6; text-align: right;">'' ||',
unistr('            ''<span style="font-size: 0.75rem; color: #9ca3af;">Action: \C989\C2DC \C804\D654 \C5F0\ACB0 \AD8C\C7A5</span>'' ||'),
'        ''</div>'' ||',
'    ''</div>'' as comment_text,',
'    cust_id as user_icon',
'FROM (',
'    SELECT ',
'        G.CUST_ID,',
'        G.CONSULT_TEXT,',
'        S.SITUATION as MATCHED_SITUATION,',
unistr('        ''\25B6 \B9DE\CDA4 \C804\B7B5: '' || S.SOLUTION || CHR(10) ||'),
unistr('        ''\25B6 \CD94\CC9C \BA58\D2B8: "'' || DBMS_LOB.SUBSTR(S.SUCCESS_STORY, 100, 1) || ''..."'' as AI_COACHING_GUIDE,'),
'        ROW_NUMBER() OVER (PARTITION BY G.CUST_ID ORDER BY DBMS_RANDOM.VALUE) as final_rn',
'    FROM (',
'        SELECT T.* FROM soe.OSA_CANCEL_PREDICTION_gen T ',
'        WHERE T.CONSULT_TEXT IS NOT NULL AND ROWNUM <= 20',
'    ) G',
'    CROSS APPLY (',
'        SELECT MIN(VECTOR_DISTANCE(G.CONSULT_VECTOR, C.CONSULT_VECTOR, COSINE)) as MIN_DIST',
'        FROM soe.OSA_CANCEL_PREDICTION C',
'    ) K',
'    CROSS APPLY (',
'        SELECT * FROM (',
'            SELECT SITUATION, SOLUTION, SUCCESS_STORY,',
'                   ROW_NUMBER() OVER (ORDER BY VECTOR_DISTANCE(G.CONSULT_VECTOR, KNOWLEDGE_VECTOR, COSINE)) as dist_rn',
'            FROM soe.SUCCESS_CASE_KNOWLEDGE',
'        ) WHERE dist_rn <= 3 ',
'        ORDER BY DBMS_RANDOM.VALUE',
'        FETCH FIRST 1 ROW ONLY',
'    ) S',
')',
'WHERE final_rn = 1 AND ROWNUM <= 5;'))
,p_ajax_enabled=>'Y'
