wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(12708927228746846)
,p_process_sequence=>20
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Execute_Select_AI'
,p_static_id=>'execute-select-ai'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_response CLOB;',
'    v_api_key  VARCHAR2(4000) := apex_app_setting.get_value(''GROQ_API_KEY'');',
'    v_url      VARCHAR2(1000) := ''https://api.groq.com/openai/v1/chat/completions'';',
'    v_question CLOB;',
'BEGIN',
'',
'',
'    insert into soe.tmp  values ('' debug -> 1-1-1-0 '' ,systimestamp);',
'    commit;',
unistr('    -- 1. \C804\C1A1 \B370\C774\D130 \C815\C81C (\B530\C634\D45C \CC98\B9AC)'),
'    apex_web_service.set_request_headers(',
'        p_name_01 => ''Content-Type'', p_value_01 => ''application/json'',',
'        p_name_02 => ''Authorization'', p_value_02 => ''Bearer '' || v_api_key,',
'        p_reset   => TRUE',
'    );',
'',
'    insert into soe.tmp  values ('' debug -> 1-1-1-1 '' ,systimestamp);',
'    commit;',
'',
'    v_question := :P8_AI_QUESTION;',
unistr('    v_question := REPLACE(v_question, ''\005C'', ''\005C\005C''); -- \BC31\C2AC\B798\C2DC \CC98\B9AC'),
unistr('    v_question := REPLACE(v_question, ''"'', ''\005C"''); -- \D070\B530\C634\D45C \CC98\B9AC'),
unistr('    v_question := REPLACE(v_question, CHR(10), '' ''); -- \C904\BC14\AFC8(Line Feed) \C81C\AC70'),
