wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(12587766535082181)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Generate AI Coaching'
,p_static_id=>'generate-ai-coaching'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_response CLOB;',
'    v_msg      CLOB;',
unistr('    v_api_key  VARCHAR2(4000) := apex_app_setting.get_value(''GROQ_API_KEY''); -- \BC1C\AE09\BC1B\C740 \D0A4 \C785\B825'),
'    v_url      VARCHAR2(1000) := ''https://api.groq.com/openai/v1/chat/completions'';',
'BEGIN',
'    DELETE FROM SOE.AI_COACH_RESULT WHERE SESSION_ID = :APP_SESSION;',
'',
'    FOR r IN (',
'        SELECT G.CUST_ID, G.CONSULT_TEXT, S.SITUATION',
'        FROM (',
'            SELECT * FROM (',
'                SELECT T.*, ROW_NUMBER() OVER (PARTITION BY T.CONSULT_TEXT ORDER BY DBMS_RANDOM.VALUE) as RN',
'                FROM soe.OSA_CANCEL_PREDICTION_gen T',
'                WHERE T.CONSULT_TEXT IS NOT NULL',
'            ) WHERE RN = 1 AND ROWNUM <= 3 ',
'        ) G',
'        CROSS APPLY (',
'            SELECT * FROM (',
'                SELECT SITUATION, ',
'                       ROW_NUMBER() OVER (ORDER BY VECTOR_DISTANCE(G.CONSULT_VECTOR, KNOWLEDGE_VECTOR, COSINE)) as DIST_RN',
'                FROM soe.SUCCESS_CASE_KNOWLEDGE',
'            ) WHERE DIST_RN <= 1',
'        ) S',
'    ) LOOP',
unistr('        -- Llama 3 API \D638\CD9C \C124\C815'),
'        apex_web_service.set_request_headers(',
'            p_name_01 => ''Content-Type'', p_value_01 => ''application/json'',',
'            p_name_02 => ''Authorization'', p_value_02 => ''Bearer '' || v_api_key,',
'            p_reset   => TRUE',
'        );',
'',
unistr('        -- Llama 3 \C804\C6A9 \D504\B86C\D504\D2B8 (\AC80\C0C9\B41C SITUATION\C744 LLM\C5D0 \C8FC\C785)'),
'        l_response := apex_web_service.make_rest_request(',
'            p_url         => v_url,',
'            p_http_method => ''POST'',',
'            p_body        => ''{',
'                "model": "llama-3.3-70b-versatile",',
'                "messages": [',
unistr('                    {"role": "system", "content": "\B2F9\C2E0\C740 \D55C\AD6D\C758 \C720\B2A5\D55C \C790\C0B0\AD00\B9AC\C0AC\C785\B2C8\B2E4. \C81C\ACF5\B41C \C9C0\CE68\C744 \BC14\D0D5\C73C\B85C \ACE0\AC1D\C5D0\AC8C \CE5C\C808\D558\ACE0 \C804\BB38\C801\C778 \B300\C751 \BA54\C2DC\C9C0\B97C 2\C904\B85C \C791\C131\D558\C138\C694."},'),
unistr('                    {"role": "user", "content": "\ACE0\AC1D\BB38\C758: '' || r.CONSULT_TEXT || '' / \CC38\ACE0\C9C0\CE68: '' || r.SITUATION || ''"}'),
'                ],',
'                "temperature": 0.7',
'            }''',
'        );',
'',
unistr('        -- \C751\B2F5 \D30C\C2F1 (Llama 3\B294 OpenAI\C640 \D615\C2DD\C774 \AC19\C74C)'),
'        v_msg := JSON_VALUE(l_response, ''$.choices[0].message.content'');',
'        ',
'        IF v_msg IS NULL THEN',
unistr('            v_msg := ''Llama \C5F0\B3D9 \D655\C778 \C911... \C804\BB38: '' || DBMS_LOB.SUBSTR(l_response, 500, 1);'),
'        END IF;',
'',
'        INSERT INTO SOE.AI_COACH_RESULT (CUST_ID, MSG_TEXT, SESSION_ID, CONSULT_TEXT, MATCHED_GUIDE)',
'        VALUES (r.CUST_ID, v_msg, :APP_SESSION, r.CONSULT_TEXT, r.SITUATION);',
'',
'        ',
'',
'        insert into soe.tmp  values ('' AI_COACH_RESULT -> 1-1-1-0 '' || r.SITUATION,systimestamp);',
'        commit;',
'    END LOOP;',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>22816104110722340
);
end;
