'DECLARE',
'	l_response      CLOB;',
'    l_response_b     BLOB;',
'	v_sql varchar2(4000) := '''' ;',
'	v_base_url varchar2(200) := '''';',
'    v_body varchar2(4000) := '''';',
'    v_start_point varchar2(4000) := '''';',
'    v_upper_process varchar2(200) := '''';',
'    v_sequence_start number;',
'    v_sequence_end number;',
'    lt_parm_names   apex_application_global.VC_ARR2; ',
'    lt_parm_values  apex_application_global.VC_ARR2; ',
'',
'    hFile          UTL_FILE.file_type;    -- file handle of destination file ',
'    lobOffset      number := 1;           -- we start reading at the 1st byte in the blob ',
'    lobSize        number;                -- size of the blob ',
'    bytesRead      number := 32767; ',
'    rawBuffer      raw(32767); ',
'    amount         number; ',
'    directory varchar2(2000) := ''TRAILS'';',
'    fileName varchar2(2000) := '''';',
'    v_lob blob;',
'    v_directory_path varchar2(2000) := '''';',
'    v_argument_1 varchar2(2000) := '''';',
'',
'BEGIN',
'',
'	select gubun1 ||'':''||gubun2||gubun3 into v_base_url',
'	from ogg_conf',
'	where keya = ''EXTRACTURL'' ',
'	and keyb = ''ADMIN''',
'	;',
'',
'    lt_parm_names(1)  := ''download''; ',
'    lt_parm_values(1) := ''true''; ',
'    --lt_parm_names(2)  := ''$top''; ',
'    --lt_parm_values(2) := ''2''; ',
'',
'    --select to_number(''&P9_SEQUENCE_START.''),to_number(''&P9_SEQUENCE_END.'') into v_sequence_start, v_sequence_end from dual;',
'    select to_number(''&P9_SEQUENCE_START.'') into v_sequence_start from dual;',
'',
'    begin ',
'        execute immediate ''truncate table ggadmin.tmp'';',
'        execute immediate ''truncate table ggadmin.trail_arg'';',
'    end;',
'',
'    select ''&P9_PROCESS.'' into v_upper_process from dual;',
'',
'',
'',
'    insert into tmp values (''trail : &P9_PROCESS.'',sysdate);',
'    commit;',
'',
'    insert into tmp values (''delete_options : &P9_DELETE_OPTION.'',sysdate);',
'    commit;',
'',
'    insert into tmp values (''v_start : &P9_SEQUENCE_START.'',sysdate);',
'    commit;',
'',
'    --insert into tmp values (''v_end : &P9_SEQUENCE_END.'',sysdate);',
'    --commit;',
'',
'    insert into trail_arg values (''2'',''&P9_SEQUENCE_START.'');',
'    commit;',
'',
'    --insert into trail_arg values (''3'',''&P9_SEQUENCE_END.'');',
'    --commit;',
'',
'',
'    --for i in v_sequence_start..v_sequence_end loop',
'    for i in v_sequence_start..v_sequence_start loop',
'        insert into tmp values (''in loop : '' || i,sysdate);',
'        commit;',
'        ',
'    	--apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_name_02  => ''Accept'', p_value_02 => ''application/binary'', p_reset    => TRUE); ',
'',
'',
'    	--apex_web_service.set_request_headers ( p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'',
'    	apex_web_service.set_request_headers ( p_name_01  => ''Accept'', p_value_01 => ''application/binary'', p_reset    => TRUE); ',
'',
'',
'',
'    	--l_response := apex_web_service.make_rest_request ',
'        l_response_b := apex_web_service.make_rest_request_b',
'    	(',
'    		p_url                  => v_base_url || ''/trails/&P9_PROCESS./sequences/''||i, ',
'    		p_http_method          => ''GET'', ',
'    		--p_transfer_timeout     => 10, ',
'            --p_body                 => v_body,',
'    		p_username             => ''oggadmin'', ',
'    		p_password             => ''WElcome1234##'',',
'            p_parm_name            => lt_parm_names,',
'            p_parm_value           => lt_parm_values, ',
'    		p_scheme               => ''Basic''',
'    	); ',
'',
'    	--dbms_output.put_line(''Response Status : '' || apex_web_service.g_status_code);',
'    	--dbms_output.put_line(''Response Payload: '' || l_response);',
'  --dbms_output.put_line(''Response Status : '' || apex_web_service.g_status_code);',
'  --dbms_output.put_line(''File Size       : '' || ',
'    --apex_string_util.to_display_filesize(p_size_in_bytes => dbms_lob.getlength(l_file_blob)));',
'',
'        insert into tmp values (''Response Status : '' || apex_web_service.g_status_code,sysdate);',
'        commit; ',
'',
'        insert into tmp values (''File Size       : '' || apex_string_util.to_display_filesize(p_size_in_bytes => dbms_lob.getlength(l_response_b)),sysdate);',
'        commit; ',
'',
'        insert into tmp values (l_response,sysdate);',
'        commit; ',
'',
'',
'        select ''&P9_PROCESS.''||lpad(i,9,''0'') into filename from dual;',
'',
'        --insert into tmp values (l_response_b,sysdate);',
'        insert into tmp3 values (l_response_b);',
'        commit; ',
'',
'',
'',
'        --select DBMS_LOB.GetLength( res ) into lobSize from ggadmin.tmp3;',
'        --select res into v_lob from ggadmin.tmp3;',
'',
'        lobSize := DBMS_LOB.GetLength( l_response_b ); ',
'',
'        hFile := UTL_FILE.fOpen( directory, fileName, ''wb'' ); ',
'',
'        lobOffset := 1; ',
'        bytesRead := 32767; ',
'        if lobSize < bytesRead then ',
'               bytesRead := lobSize; ',
'        end if; ',
'',
'        while lobOffset <= lobSize ',
'        loop ',
'               amount := least(bytesRead, lobSize - lobOffset + 1); ',
'               DBMS_LOB.read( ',
'                       lob_loc=> l_response_b, ',
'                       amount => amount, ',
'                       offset => lobOffset, ',
'                       buffer => rawBuffer ',
'               ); ',
'',
'               lobOffset := lobOffset + amount; ',
'',
'               UTL_FILE.put_raw( hFile, rawBuffer ); ',
'        end loop; ',
'',
'        UTL_FILE.fClose( hFile ); ',
'',
'        --begin',
'            --dbms_scheduler.run_job( ''convert_job1'');',
'        --end;',
'   ',
'    end loop;',
'',
'',
'    select directory_path||''/''||filename into v_argument_1 from all_directories where directory_name = ''TRAILS'';',
'  ',
'END;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>18655045251852856
);
end;
