wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(26085112309316716)
,p_plug_name=>'Related Tables and LOB Context'
,p_static_id=>'related-tables-lob-context'
,p_parent_plug_id=>wwv_flow_imp.id(56168450207264685)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(141234094937171007037)
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select c.times,c.resv1,c.resv2,c.resv3,c.resv4,c.resv5,c.resv6,',
'       c.resv7,c.resv8,c.resv9,c.resv10,c.cnt,c.resv11,c.max_val,',
'    (',
'        select listagg(distinct trim(x.resv6)||'' ''||trim(x.resv11)||'' ''||',
'               ''avg_row_len=>''||nvl(to_char(t.avg_row_len),''N/A'')||'' ''||',
'               ''LOB=>''||case when exists (select 1',
'                                           from all_tab_columns tc',
'                                           where tc.table_name = x.table_name',
'                                             and (x.owner_name is null or tc.owner = x.owner_name)',
'                                             and tc.data_type in (''CLOB'',''BLOB'')) then ''Yes'' else ''No'' end, '','')',
'               within group (order by trim(x.resv6)||'' ''||trim(x.resv11))',
'        from (',
'            select l.*,',
'                   case when instr(trim(l.resv11), ''.'') > 0 then upper(substr(trim(l.resv11),1,instr(trim(l.resv11), ''.'')-1)) end owner_name,',
'                   upper(case when instr(trim(l.resv11), ''.'') > 0 then substr(trim(l.resv11),instr(trim(l.resv11), ''.'')+1) else trim(l.resv11) end) table_name',
'            from ggadmin.lgd_tmp l',
'            where l.global_rba <= c.global_rba ',
'              and l.global_rba >= c.max_val',
'        ) x',
'        left join all_tables t on t.table_name = x.table_name',
'                              and (x.owner_name is null or t.owner = x.owner_name)',
'    ) related_tables',
'from ',
'(',
'    select b.val times,resv1,resv2,resv3,resv4,resv5,resv6,resv7,resv8,resv9,resv10,',
'        (',
'            select count(*)',
'            from ggadmin.lgd_tmp t',
'            where t.global_rba <= b.global_rba',
'            and t.global_rba >= b.max_val',
'        ) cnt,',
'        resv11,',
'        max_val,',
'        b.global_rba',
'    from',
'    (',
'        select t.*,',
'            (',
'                select /*+ index_desc (k lgd_tmp_idx02) */ k.global_rba',
'                from ggadmin.lgd_tmp k',
'                where k.global_rba < t.global_rba',
'                and k.resv1 = ''(x00)''',
'                and rownum = 1',
'            ) max_val',
'        from',
'        (',
'            select * ',
'            from',
'            (',
'                select ',
'                    to_timestamp(trim(A.RESV4) || '' '' || substr(trim(a.resv5),1,instr( trim(a.resv5),''.'',1,2) -1) ,''YYYY/MM/DD HH24:MI:SS.FF'') val',
'                    ,a.*',
'                from ggadmin.lgd_tmp a',
'                where resv4 is not null',
'            ) ',
'            order by global_rba ',
'        ) t',
'    ) b',
'    where resv1 = ''(x02)''',
') c',
unistr('where c.cnt >= :P10_FILTER_CNT    -- large transaction \C870\AC74\C124\C815 ex> 100000\AC74 \C774\C0C1'),
';',
''))
