wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(91031764334359851)
,p_name=>'Trail Analysis Summary'
,p_static_id=>'trail-analysis-summary'
,p_template=>wwv_flow_imp.id(141233964465888007007)
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader:t-Region--noPadding'
,p_component_template_options=>'#DEFAULT#:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with commits as (',
'  select b.global_rba,',
'         (select count(*)',
'          from ggadmin.lgd_tmp t',
'          where t.global_rba <= b.global_rba',
'            and t.global_rba >= b.max_val) cnt',
'  from (',
'    select t.*,',
'           (select /*+ index_desc (k lgd_tmp_idx02) */ k.global_rba',
'            from ggadmin.lgd_tmp k',
'            where k.global_rba < t.global_rba',
'              and k.resv1 = ''(x00)''',
'              and rownum = 1) max_val',
'    from ggadmin.lgd_tmp t',
'    where t.resv1 = ''(x02)''',
'  ) b',
'), summary as (',
'  select (select count(distinct file_name) from ggadmin.lgd_tmp where file_name is not null) trail_files,',
'         (select count(*) from ggadmin.lgd_tmp) parsed_rows,',
'         (select count(*) from ggadmin.lgd_tmp where resv11 is not null) table_rows,',
'         (select count(*) from commits) commit_count,',
'         (select nvl(max(cnt),0) from commits) max_rows_per_commit,',
'         (select count(distinct resv11) from ggadmin.lgd_tmp where resv11 is not null) table_count,',
'         (select min(file_name) keep (dense_rank first order by file_no) from ggadmin.lgd_tmp where file_name is not null) first_file,',
'         (select max(file_name) keep (dense_rank last order by file_no) from ggadmin.lgd_tmp where file_name is not null) last_file',
'  from dual',
')',
'select ''<style>',
'.ta-summary{display:grid;grid-template-columns:repeat(6,minmax(120px,1fr));gap:10px;margin:0 0 16px 0}',
'.ta-card{border:1px solid #d9dee7;background:#fff;border-radius:6px;padding:12px 14px;min-height:78px}',
'.ta-label{font-size:11px;text-transform:uppercase;color:#64748b;font-weight:700;letter-spacing:.04em}',
'.ta-value{font-size:24px;font-weight:800;color:#111827;line-height:1.25;margin-top:6px}',
'.ta-note{font-size:12px;color:#64748b;margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}',
'.ta-head{display:flex;align-items:flex-end;justify-content:space-between;margin:0 0 10px 0}',
'.ta-title{font-size:22px;font-weight:800;color:#111827}',
'.ta-range{font-size:12px;color:#475569}',
'@media(max-width:900px){.ta-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.ta-head{display:block}.ta-range{margin-top:4px}}',
'</style>'' ||',
'''<div class="ta-head"><div class="ta-title">Trail Transaction Analysis</div><div class="ta-range">'' || nvl(first_file,''-'') || '' - '' || nvl(last_file,''-'') || ''</div></div>'' ||',
'''<div class="ta-summary">'' ||',
'''<div class="ta-card"><div class="ta-label">Trail Files</div><div class="ta-value">'' || trail_files || ''</div><div class="ta-note">loaded sequence files</div></div>'' ||',
'''<div class="ta-card"><div class="ta-label">Parsed Rows</div><div class="ta-value">'' || parsed_rows || ''</div><div class="ta-note">records in staging</div></div>'' ||',
'''<div class="ta-card"><div class="ta-label">Table Rows</div><div class="ta-value">'' || table_rows || ''</div><div class="ta-note">records with table name</div></div>'' ||',
'''<div class="ta-card"><div class="ta-label">Commit Ends</div><div class="ta-value">'' || commit_count || ''</div><div class="ta-note">x02 candidates</div></div>'' ||',
'''<div class="ta-card"><div class="ta-label">Max Rows/Commit</div><div class="ta-value">'' || max_rows_per_commit || ''</div><div class="ta-note">largest candidate</div></div>'' ||',
'''<div class="ta-card"><div class="ta-label">Tables</div><div class="ta-value">'' || table_count || ''</div><div class="ta-note">distinct table names</div></div>'' ||',
'''</div>'' as summary_html',
'from summary'))
,p_query_row_template=>wwv_flow_imp.id(141234156560532007094)
,p_query_num_rows=>1
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'ROW_RANGES_IN_SELECT_LIST'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
