,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    user_icon,',
'    user_name,',
'    comment_date,',
'    risk_status,',
'    risk_label,',
'    comment_text',
'FROM (',
'    SELECT ',
'        cust_id as user_icon,',
'        ''AI Coach'' as user_name,',
unistr('        ''\ACE0\AC1D ID: '' || cust_id as comment_date,'),
'        risk_status,',
'        risk_label,',
unistr('        -- DBMS_LOB.SUBSTR\B97C \C0AC\C6A9\D558\C5EC CLOB\C744 VARCHAR2(4000)\B85C \BCC0\D658 (\C5D0\B7EC \D574\ACB0 \D575\C2EC)'),
'        ''<div style="padding:12px; background-color:#eef7ff; border-radius:8px; border:1px solid #0066cc;">'' ||',
unistr('        ''<b>\D83E\DD16 AI \B9DE\CDA4\D615 \B300\C751 \C2A4\D06C\B9BD\D2B8:</b><br>'' || '),
'        DBMS_LOB.SUBSTR(msg_text, 4000, 1) || ''</div>'' as comment_text,',
'        ROW_NUMBER() OVER (PARTITION BY risk_label ORDER BY created_at DESC) as rn',
'    FROM (',
'        SELECT ',
'            c.cust_id,',
'            c.msg_text,',
'            c.created_at,',
'            CASE ',
'                WHEN dist < 0.27   THEN ''danger''',
'                WHEN dist < 0.275  THEN ''warning''',
'                WHEN dist < 0.3    THEN ''success''',
'                ELSE ''info''',
'            END as risk_status,',
'            CASE ',
unistr('                WHEN dist < 0.27   THEN ''\ACE0\C704\D5D8'''),
unistr('                WHEN dist < 0.275  THEN ''\C911\C704\D5D8'''),
unistr('                WHEN dist < 0.3    THEN ''\C800\C704\D5D8'''),
unistr('                ELSE ''\C815\C0C1'''),
'            END as risk_label',
'        FROM (',
'            SELECT ',
'                c.CUST_ID, ',
'                c.MSG_TEXT, ',
'                c.CREATED_AT,',
'                VECTOR_DISTANCE(p.CONSULT_VECTOR, ',
'                    (SELECT CONSULT_VECTOR FROM soe.osa_cancel_prediction WHERE PRED_ID = (SELECT MAX(PRED_ID) FROM soe.osa_cancel_prediction)), ',
'                    COSINE) as dist',
'            FROM soe.AI_COACH_RESULT c',
'            LEFT JOIN soe.osa_cancel_prediction_gen p ON c.CUST_ID = p.CUST_ID',
'            WHERE c.SESSION_ID = :APP_SESSION',
'        ) c',
'    )',
')',
'WHERE rn = 1 ',
unistr('AND risk_label != ''\C815\C0C1'''),
'ORDER BY DECODE(risk_status, ''danger'', 1, ''warning'', 2, ''success'', 3, 4);'))
,p_template_component_type=>'REPORT'
,p_lazy_loading=>false
,p_plug_source_type=>'TMPL_THEME_42$CONTENT_ROW'
,p_plug_query_num_rows=>15
,p_plug_query_num_rows_type=>'SET'
,p_show_total_row_count=>false
,p_landmark_type=>'region'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'APPLY_THEME_COLORS', 'Y',
  'AVATAR_ICON', 'fa-user',
  'AVATAR_SHAPE', 't-Avatar--rounded',
  'AVATAR_TYPE', 'icon',
  'BADGE_COL_WIDTH', 't-ContentRow-badge--md',
  'BADGE_LABEL', '&RISK_LABEL.',
  'BADGE_LABEL_DISPLAY', 'N',
  'BADGE_STATE', 'RISK_STATUS',
  'BADGE_VALUE', 'RISK_STATUS',
  'DESCRIPTION', '&COMMENT_TEXT.',
  'DISPLAY_AVATAR', 'Y',
  'DISPLAY_BADGE', 'Y',
  'HIDE_BORDERS', 'N',
  'REMOVE_PADDING', 'N')).to_clob
);
