wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(107942101094459116021)
,p_name=>'Response'
,p_static_id=>'response'
,p_region_name=>'COMMENTS'
,p_parent_plug_id=>wwv_flow_imp.id(6353222284257865670)
,p_template=>wwv_flow_imp.id(141233964465888007007)
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#:margin-top-md'
,p_component_template_options=>'#DEFAULT#:t-Comments--chat'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'',
unistr('select ''\BB38\C758) '' || consult_text || ''<br><b>\AC00\C774\B4DC\C9C0\CE68)</b> '' || matched_situation comment_text ,'),
'    cust_id user_icon, null comment_date, null user_name, null actions,',
'    null attribute_1,null attribute_2,null attribute_3,null attribute_4',
'from ',
'(',
'SELECT ',
'    G.CUST_ID,',
'    G.CONSULT_TEXT,',
'    ROUND((1 - K.MIN_DIST) * 100, 1) || ''%'' as RISK_SCORE,',
'    S.SITUATION as MATCHED_SITUATION,',
unistr('    ''\25B6 \B9DE\CDA4 \C804\B7B5: '' || S.SOLUTION || CHR(10) ||'),
unistr('    ''\25B6 \CD94\CC9C \BA58\D2B8: "'' || DBMS_LOB.SUBSTR(S.SUCCESS_STORY, 100, 1) || ''..."'' as AI_COACHING_GUIDE'),
'FROM (',
unistr('    -- 1. \ACE0\AC1D ID\BFD0\B9CC \C544\B2C8\B77C \C0C1\B2F4 \D14D\C2A4\D2B8(CONSULT_TEXT)\B3C4 \C911\BCF5\C744 \C904\C5EC \B2E4\C591\D558\AC8C \C0D8\D50C\B9C1'),
'    SELECT * FROM (',
'        SELECT T.*, ',
'               ROW_NUMBER() OVER (PARTITION BY T.CONSULT_TEXT ORDER BY DBMS_RANDOM.VALUE) as RN',
'        FROM soe.OSA_CANCEL_PREDICTION_gen T',
'        WHERE T.CONSULT_TEXT IS NOT NULL',
unistr('    ) WHERE RN = 1 AND ROWNUM <= 15  -- \B2E4\C591\D55C \C0C1\B2F4 \B0B4\C6A9\C744 \AC00\C9C4 15\AC74 \CD94\CD9C'),
') G',
'CROSS APPLY (',
unistr('    -- \BCA1\D130 \C720\C0AC\B3C4 \CD5C\C19F\AC12 \ACC4\C0B0'),
'    SELECT MIN(VECTOR_DISTANCE(G.CONSULT_VECTOR, C.CONSULT_VECTOR, COSINE)) as MIN_DIST',
'    FROM soe.OSA_CANCEL_PREDICTION C',
') K',
'CROSS APPLY (',
unistr('    -- \B2E4\C591\C131\C744 \C704\D574 \AC70\B9AC\AC00 \AC00\AE4C\C6B4 \C0C1\C704 3\AC1C \C911 \D558\B098\B97C \B79C\B364\D558\AC8C \B9E4\CE6D (\ACE0\C815 \B9E4\CE6D \D0C8\D53C)'),
'    SELECT * FROM (',
'        SELECT SITUATION, SOLUTION, SUCCESS_STORY,',
'               ROW_NUMBER() OVER (ORDER BY VECTOR_DISTANCE(G.CONSULT_VECTOR, KNOWLEDGE_VECTOR, COSINE)) as DIST_RN',
'        FROM soe.SUCCESS_CASE_KNOWLEDGE',
unistr('    ) WHERE DIST_RN <= 3  -- \C720\C0AC\B3C4 TOP 3 \CD94\CD9C'),
unistr('    ORDER BY DBMS_RANDOM.VALUE -- \ADF8\C911 \D558\B098\B97C \B79C\B364 \C120\D0DD\D558\C5EC \ACB0\ACFC\C758 \B2E4\C591\C131 \D655\BCF4'),
'    FETCH FIRST 1 ROW ONLY',
') S',
'ORDER BY DBMS_RANDOM.VALUE',
')',
';'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P11_PROJECT_ID'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(141234154349324007092)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'No Comments'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
