'    select ''&P62_PROCESS.'' into v_upper_process from dual;',
'',
'    select distinct remdq(json_serialize(a.res.response.credentials.alias)) alias into v_alias',
'    from extractdetail a',
'    where process = v_upper_process',
'    and session_id = ''&APP_SESSION.''',
'    ;',
'',
'    select length(''&P62_EXTRACT_BEGIN_CSN.'') into is_csn_null from dual;',
'',
'    insert into tmp values (''is_csn_null : ''||is_csn_null,sysdate);',
'    commit;',
'',
'    if is_csn_null > 0 then',
'        v_body := ''',
'        {',
'            "credentials": {',
'                "alias": "''||v_alias||''"',
'            },',
'            "begin": {',
'                "at": {',
'                    "csn": &P62_EXTRACT_BEGIN_CSN.',
'                }',
'            }',
'        }    ',
'        '';',
'    else',
'        v_body := ''',
'        {',
'            "credentials": {',
'                "alias": "''||v_alias||''"',
'            },',
'            "begin": "now"',
'        }    ',
'        '';    ',
'    end if;',
'',
'',
'    insert into tmp values (''v_body : ''||v_body,sysdate);',
'    commit;',
'',
'	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'	l_response := apex_web_service.make_rest_request ',
'	(',
'		p_url                  => v_base_url || ''/extracts/''||v_upper_process, ',
'		p_http_method          => ''PATCH'', ',
'		--p_transfer_timeout     => 10, ',
'        p_body                 => v_body,',
'		p_username             => ''oggadmin'', ',
'		p_password             => ''WElcome1234##'',',
'		p_scheme               => ''Basic''',
'	); ',
'',
'	--dbms_output.put_line(''Response Status : '' || apex_web_service.g_status_code);',
'	--dbms_output.put_line(''Response Payload: '' || l_response);',
'',
'    insert into tmp values (l_response,sysdate);',
'    commit;',
'',
'END;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>11323663240308508
);
end;
