'DECLARE',
'	l_response      CLOB;',
'	v_sql varchar2(4000) := '''' ;',
'	v_base_url varchar2(200) := '''';',
'    v_body varchar2(4000) := '''';',
'    v_start_point varchar2(4000) := '''';',
'    v_upper_process varchar2(200) := '''';',
'	',
'BEGIN',
'',
'	select gubun1 ||'':''||gubun2||gubun3 into v_base_url',
'	from ogg_conf',
'	where keya = ''EXTRACTURL'' ',
'	and keyb = ''ADMIN''',
'	;',
'',
'',
'    select ''&P68_PROCESS.'' into v_upper_process from dual;',
'',
'    select ''&P68_START_POINT.'' into v_start_point from dual;',
'',
'    insert into tmp values (''v_start_point : ''||v_start_point,sysdate);',
'    commit;',
'',
'    if v_start_point = ''at'' then',
'        v_body := ''',
'        {',
'            "name": "start",',
'            "processType": "extract",',
'            "processName": "&P68_PROCESS.",',
'            "at": &P68_CSN.',
'        }        ',
'        '';',
'    else',
'        v_body := ''',
'        {',
'            "name": "start",',
'            "processType": "extract",',
'            "processName": "&P68_PROCESS.",',
'            "after": &P68_CSN.',
'        }     ',
'        '';    ',
'    end if;',
'',
'',
'    insert into tmp values (''v_body : ''||v_body,sysdate);',
'    commit;',
'',
'	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'	l_response := apex_web_service.make_rest_request ',
'	(',
'		p_url                  => v_base_url || ''/commands/execute'', ',
'		p_http_method          => ''POST'', ',
'		--p_transfer_timeout     => 10, ',
'        p_body                 => v_body,',
'		p_username             => ''oggadmin'', ',
'		p_password             => ''WElcome1234##'',',
'		p_scheme               => ''Basic''',
'	); ',
'',
'	--dbms_output.put_line(''Response Status : '' || apex_web_service.g_status_code);',
'	--dbms_output.put_line(''Response Payload: '' || l_response);',
'',
'    insert into tmp values (l_response,sysdate);',
'    commit;',
'',
'END;',
'',
''))
