wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(37431781004072660)
,p_plug_name=>'Replicats'
,p_static_id=>'replicats'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(141233965818187007009)
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'	l_response      CLOB;',
'	--v_sql varchar2(4000) := '''' ;',
'    v_sql clob := '''' ;',
'	v_base_url varchar2(200) := '''';',
'    v_process varchar2(200) := '''';',
'',
'    cursor c1 ',
'    is',
'        select distinct remdq(json_serialize(process)) process',
'        from ',
'        (',
'            select a.session_id,a.res.response.items[0].name process from replicats a',
'            union all',
'            select a.session_id,a.res.response.items[1].name from replicats a',
'            union all',
'            select a.session_id,a.res.response.items[2].name from replicats a',
'            union all',
'            select a.session_id,a.res.response.items[3].name from replicats a',
'            union all',
'            select a.session_id,a.res.response.items[4].name from replicats a',
'            union all',
'            select a.session_id,a.res.response.items[5].name from replicats a',
'            union all',
'            select a.session_id,a.res.response.items[6].name from replicats a',
'            union all',
'            select a.session_id,a.res.response.items[7].name from replicats a',
'            union all',
'            select a.session_id,a.res.response.items[8].name from replicats a',
'            union all',
'            select a.session_id,a.res.response.items[9].name from replicats a',
'        )',
'        where process is not null',
'        and session_id = ''&APP_SESSION.''',
'        ; ',
'',
'BEGIN',
'',
'	select gubun1 ||'':''||gubun2||gubun3 into v_base_url',
'	from ogg_conf',
'	where keya = ''REPLICATURL'' ',
'	and keyb = ''ADMIN''',
'	;',
'',
'',
'    insert into tmp (res) values (v(''APP_SESSION''));',
'    commit;    ',
'',
'	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'	l_response := apex_web_service.make_rest_request ',
'	(',
'		p_url                  => v_base_url || ''/replicats'', ',
'        --p_url                  => ''http://172.28.0.5:9112/services/v2'' || ''/replicats'', ',
'		p_http_method          => ''GET'', ',
'		--p_transfer_timeout     => 10, ',
'		p_username             => ''oggadmin'', ',
'		p_password             => ''WElcome1234##'',',
'		p_scheme               => ''Basic''',
'	); ',
'',
'	--dbms_output.put_line(''Response Status : '' || apex_web_service.g_status_code);',
'	--dbms_output.put_line(''Response Payload: '' || l_response);',
'	--begin',
'        --execute immediate ''truncate table replicats'';',
'    --end;',
'',
'',
'',
'    delete from replicats',
'    where user_id = ''&APP_USER.''',
'    and session_id = ''&APP_SESSION.''',
'    ;',
'    ',
'    insert into replicats (user_id,session_id,res,stat) values (''&APP_USER.'',''&APP_SESSION.'',l_response,apex_web_service.g_status_code);',
'    commit;',
'',
'',
'',
'	--begin',
'        --execute immediate ''truncate table replicatstatus'';',
'        --execute immediate ''truncate table replicatdetail'';',
'    --end;',
'    ',
'',
'    delete from replicatstatus',
'    where user_id = ''&APP_USER.''',
'    and session_id = ''&APP_SESSION.''',
'    ;',
'',
'',
'    delete from replicatdetail',
'    where user_id = ''&APP_USER.''',
'    and session_id = ''&APP_SESSION.''',
'    ;',
'    commit;',
'',
'    open c1;',
'    loop',
'        fetch c1 into v_process;',
'        exit when c1%NOTFOUND;',
'',
'    	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'    	l_response := apex_web_service.make_rest_request ',
'    	(',
'    		p_url                  => v_base_url || ''/replicats/''||v_process||''/info/status'', ',
'            --p_url                  => ''http://172.28.0.5:9112/services/v2'' || ''/replicats'', ',
'    		p_http_method          => ''GET'', ',
'    		--p_transfer_timeout     => 10, ',
'    		p_username             => ''oggadmin'', ',
'    		p_password             => ''WElcome1234##'',',
'    		p_scheme               => ''Basic''',
'    	); ',
'',
'        insert into replicatstatus (user_id,session_id,process,res,stat) values (''&APP_USER.'',''&APP_SESSION.'',v_process,l_response,apex_web_service.g_status_code);',
'        commit;',
'',
'    	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'    	l_response := apex_web_service.make_rest_request ',
'    	(',
'    		p_url                  => v_base_url || ''/replicats/''||v_process, ',
'            --p_url                  => ''http://172.28.0.5:9112/services/v2'' || ''/replicats'', ',
'    		p_http_method          => ''GET'', ',
'    		--p_transfer_timeout     => 10, ',
'    		p_username             => ''oggadmin'', ',
'    		p_password             => ''WElcome1234##'',',
'    		p_scheme               => ''Basic''',
'    	); ',
'',
'        insert into replicatdetail (user_id,session_id,process,res,stat) values (''&APP_USER.'',''&APP_SESSION.'',v_process,l_response,apex_web_service.g_status_code);',
'        commit;',
'',
'    end loop;',
'    close c1;',
'    ',
'	v_sql := ''',
'        select process,max(status) status,max(lag) lag, max(sincelagreported) sincelagreported,',
'            max(status_val) status_val,',
'            max(status_label) status_label,',
'            max(action_label) action_label,',
'            max(process_label) process_label',
'        from',
'        (',
'            select process,status,lag,sincelagreported,',
'                case when status = ''''running'''' then ''''success''''',
'                    when status = ''''stopped'''' then ''''danger''''',
'                    when status = ''''abended'''' then ''''warning''''',
'                    end status_val,',
'                case when status = ''''running'''' then ''''fa-stop-circle-o''''',
'                    when status = ''''stopped'''' then ''''fa-play''''',
'                    when status = ''''abended'''' then ''''fa-play''''',
'                    end status_label,',
'                case when status = ''''running'''' then ''''Stop''''',
'                    when status = ''''stopped'''' then ''''Start''''',
'                    when status = ''''abended'''' then ''''Start''''',
'                    end action_label,',
'                case when status = ''''running'''' then ''''fa-person-running''''',
'                    when status = ''''stopped'''' then ''''fa-person-standing''''',
'                    when status = ''''abended'''' then ''''fa-person-standing''''',
'                    end process_label         ',
'            from',
'            (',
'                select session_id,remdq(json_serialize(a.res.response.items[0].name)) process,remdq(json_serialize(a.res.response.items[0].status)) status,null lag,null sincelagreported',
'                from replicats a',
'                union all',
'                select session_id,remdq(json_serialize(a.res.response.items[1].name)) process,remdq(json_serialize(a.res.response.items[1].status)) status,null lag,null sincelagreported',
'                from replicats a',
'                union all',
'                select session_id,remdq(json_serialize(a.res.response.items[2].name)) process,remdq(json_serialize(a.res.response.items[2].status)) status,null lag,null sincelagreported',
'                from replicats a',
'                union all',
'                select session_id,remdq(json_serialize(a.res.response.items[3].name)) process,remdq(json_serialize(a.res.response.items[3].status)) status,null lag,null sincelagreported',
'                from replicats a',
'                union all',
'                select session_id,remdq(json_serialize(a.res.response.items[4].name)) process,remdq(json_serialize(a.res.response.items[4].status)) status,null lag,null sincelagreported',
'                from replicats a',
'                union all',
'                select session_id,remdq(json_serialize(a.res.response.items[5].name)) process,remdq(json_serialize(a.res.response.items[5].status)) status,null lag,null sincelagreported',
'                from replicats a',
'                union all',
'                select session_id,remdq(json_serialize(a.res.response.items[6].name)) process,remdq(json_serialize(a.res.response.items[6].status)) status,null lag,null sincelagreported',
'                from replicats a',
'                union all',
'                select session_id,remdq(json_serialize(a.res.response.items[7].name)) process,remdq(json_serialize(a.res.response.items[7].status)) status,null lag,null sincelagreported',
'                from replicats a',
'                union all',
'                select session_id,remdq(json_serialize(a.res.response.items[8].name)) process,remdq(json_serialize(a.res.response.items[8].status)) status,null lag,null sincelagreported',
'                from replicats a',
'                union all',
'                select session_id,remdq(json_serialize(a.res.response.items[9].name)) process,remdq(json_serialize(a.res.response.items[9].status)) status,null lag,null sincelagreported',
'                from replicats a',
'                union all',
'                select session_id,process,null,json_serialize(a.res.response.lag) lag,json_serialize(a.res.response.sinceLagReported) sinceLagReported ',
'                from replicatstatus a',
'            )',
'            where process is not null',
'            and session_id = ''''&APP_SESSION.''''',
'        )',
'        group by process',
'    '';',
'	',
'	return v_sql;',
'',
'END;'))
,p_template_component_type=>'REPORT'
,p_lazy_loading=>false
,p_plug_source_type=>'TMPL_THEME_42$CONTENT_ROW'
,p_plug_query_num_rows=>15
,p_plug_query_num_rows_type=>'SET'
,p_show_total_row_count=>false
,p_landmark_type=>'region'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'APPLY_THEME_COLORS', 'Y',
  'AVATAR_ICON', '&PROCESS_LABEL.',
  'AVATAR_SHAPE', 't-Avatar--noShape',
