wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(18832985460949774)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'execute'
,p_static_id=>'execute'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'	l_response      CLOB;',
'	v_sql varchar2(4000) := '''' ;',
'	v_base_url varchar2(200) := '''';',
'    v_body varchar2(4000) := '''';',
'    is_rba_null varchar2(4000) := '''';',
'    v_upper_process varchar2(200) := '''';',
'    v_alias varchar2(200) := '''';',
'    v_begin_now varchar2(200) := '''';',
'	',
'BEGIN',
'',
'	select gubun1 ||'':''||gubun2||gubun3 into v_base_url',
'	from ogg_conf',
'	where keya = ''REPLICATURL'' ',
'	and keyb = ''ADMIN''',
'	;',
'',
'',
'    select ''&P90_PROCESS.'' into v_upper_process from dual;',
'',
'    select distinct remdq(json_serialize(a.res.response.credentials.alias)) alias into v_alias',
'    from replicatdetail a',
'    where user_id = ''&APP_USER.''',
'    and session_id = ''&APP_SESSION.''',
'    and process = v_upper_process',
'    ;',
'',
'    select length(''&P90_REPLICAT_BEGIN_RBA.'') into is_rba_null from dual;',
'',
'    select length(''&P90_BEGIN_NOW.'') into v_begin_now from dual;',
'',
'    insert into tmp values (''is_rba_null : ''||is_rba_null,sysdate);',
'    commit;',
'',
'    insert into tmp values (''v_begin_now : ''||v_begin_now,sysdate);',
'    commit;',
'',
'    if is_rba_null > 0 then',
'        v_body := ''',
'        {',
'            "credentials": {',
'                "alias": "''||v_alias||''"',
'            },',
'            "begin": {',
'                "sequence": &P90_REPLICAT_BEGIN_SEQUENCE.,',
'                "offset": &P90_REPLICAT_BEGIN_RBA.',
'            }',
'        }    ',
'        '';',
'    else',
'        v_body := ''',
'        {',
'            "credentials": {',
'                "alias": "''||v_alias||''"',
'            },',
'            "begin": "now"',
'        }    ',
'        '';    ',
'    end if;',
'',
'',
'    insert into tmp values (''v_body : ''||v_body,sysdate);',
'    commit;',
'',
'	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'	l_response := apex_web_service.make_rest_request ',
'	(',
