wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(37406998252129090)
,p_plug_name=>'New'
,p_static_id=>'new'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(141233965818187007009)
,p_plug_display_sequence=>30
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'	l_response      CLOB;',
'	v_sql varchar2(4000) := '''' ;',
'	v_base_url varchar2(200) := '''';',
'    v_process varchar2(200) := '''';',
'    v_domain varchar2(200) := '''';',
'    v_alias varchar2(200) := '''';',
'',
'    cursor c1 ',
'    is',
'        select distinct remdq(json_serialize(domain)) domain',
'        from',
'        (',
'            select a.session_id,a.res.response.items[0].name domain from ggdomains a',
'            union all',
'            select a.session_id,a.res.response.items[1].name domain from ggdomains a',
'            union all',
'            select a.session_id,a.res.response.items[2].name domain from ggdomains a',
'            union all',
'            select a.session_id,a.res.response.items[3].name domain from ggdomains a',
'            union all',
'            select a.session_id,a.res.response.items[4].name domain from ggdomains a',
'        )',
'        where domain is not null',
'        and session_id = ''&APP_SESSION.''',
'        ; ',
'        	',
'    cursor c2',
'    is ',
'        select distinct domain,remdq(json_serialize(alias)) alias',
'        from',
'        (',
'            select a.session_id,a.domain,a.res.response.items[0].name alias from ggalias a',
'            union all',
'            select a.session_id,a.domain,a.res.response.items[1].name from ggalias a',
'            union all',
'            select a.session_id,a.domain,a.res.response.items[2].name from ggalias a',
'            union all',
'            select a.session_id,a.domain,a.res.response.items[3].name from ggalias a',
'            union all',
'            select a.session_id,a.domain,a.res.response.items[4].name from ggalias a',
'        )',
'        where alias is not null',
'        and session_id = ''&APP_SESSION.''',
'        ;        ',
'',
'BEGIN',
'',
'	select gubun1 ||'':''||gubun2||gubun3 into v_base_url',
'	from ogg_conf',
'	where keya = ''EXTRACTURL'' ',
'	and keyb = ''ADMIN''',
'	;',
'',
'	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'	l_response := apex_web_service.make_rest_request ',
'	(',
'		p_url                  => v_base_url || ''/credentials'', ',
'        --p_url                  => ''http://172.28.0.5:9112/services/v2'' || ''/replicats'', ',
'		p_http_method          => ''GET'', ',
'		--p_transfer_timeout     => 10, ',
'		p_username             => ''oggadmin'', ',
'		p_password             => ''WElcome1234##'',',
'		p_scheme               => ''Basic''',
'	); ',
'',
'	--dbms_output.put_line(''Response Status : '' || apex_web_service.g_status_code);',
'	--dbms_output.put_line(''Response Payload: '' || l_response);',
'	--begin',
'        --execute immediate ''truncate table ggdomains'';',
'    --end;',
'',
'    delete from ggdomains',
'    where user_id = ''&APP_USER.''',
'    and session_id = ''&APP_SESSION.''',
'    ;',
'    commit;',
'',
'    insert into ggdomains (user_id,session_id,res) values (''&APP_USER.'',''&APP_SESSION.'',l_response);',
'    commit;',
'',
'	--begin',
'        --execute immediate ''truncate table ggalias'';',
'    --end;',
'    ',
'    delete from ggalias',
'    where user_id = ''&APP_USER.''',
'    and session_id = ''&APP_SESSION.''',
'    ;',
'    commit;',
'',
'    open c1;',
'    loop',
'        fetch c1 into v_domain;',
'        exit when c1%NOTFOUND;',
'',
'    	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'    	l_response := apex_web_service.make_rest_request ',
'    	(',
'    		p_url                  => v_base_url || ''/credentials/''||v_domain, ',
'            --p_url                  => ''http://172.28.0.5:9112/services/v2'' || ''/replicats'', ',
'    		p_http_method          => ''GET'', ',
'    		--p_transfer_timeout     => 10, ',
'    		p_username             => ''oggadmin'', ',
'    		p_password             => ''WElcome1234##'',',
'    		p_scheme               => ''Basic''',
'    	); ',
'',
'        insert into ggalias values (''&APP_USER.'',''&APP_SESSION.'',v_domain,l_response,sysdate);',
'        commit;',
'',
'    end loop;',
'    ',
'	--begin',
'        --execute immediate ''truncate table ggconnections'';',
'    --end;',
'',
'    delete from ggconnections',
'    where user_id = ''&APP_USER.''',
'    and session_id = ''&APP_SESSION.''',
'    ;',
'    commit;',
'    ',
'    open c2;',
'    loop',
'        fetch c2 into v_domain, v_alias;',
'        exit when c2%NOTFOUND;',
'        ',
'    	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'    	l_response := apex_web_service.make_rest_request ',
'    	(',
'    		p_url                  => v_base_url || ''/credentials/''||v_domain||''/''||v_alias, ',
'            --p_url                  => ''http://172.28.0.5:9112/services/v2'' || ''/replicats'', ',
'    		p_http_method          => ''GET'', ',
'    		--p_transfer_timeout     => 10, ',
'    		p_username             => ''oggadmin'', ',
'    		p_password             => ''WElcome1234##'',',
'    		p_scheme               => ''Basic''',
'    	); ',
'',
'        insert into ggconnections values (''&APP_USER.'',''&APP_SESSION.'',v_domain,v_alias,l_response,sysdate);',
'        commit;',
'',
'    end loop;',
'	v_sql := ''',
'        select a.domain,a.alias,remdq(json_serialize(a.res.response.userid)) userid from ggconnections a where user_id = ''''&APP_USER.'''' and session_id = ''''&APP_SESSION.'''' ',
'    '';',
'	',
'	return v_sql;',
'',
'END;',
''))
,p_template_component_type=>'REPORT'
,p_lazy_loading=>false
,p_plug_source_type=>'TMPL_THEME_42$CONTENT_ROW'
,p_plug_query_num_rows=>15
,p_plug_query_num_rows_type=>'SET'
,p_show_total_row_count=>false
,p_landmark_type=>'region'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'APPLY_THEME_COLORS', 'Y',
  'BADGE_COL_WIDTH', 't-ContentRow-badge--lg',
  'BADGE_LABEL', '&DOMAIN.',
  'BADGE_LABEL_DISPLAY', 'N',
  'BADGE_SIZE', 't-Badge--md',
  'BADGE_STATE', 'DOMAIN',
  'BADGE_VALUE', 'DOMAIN',
  'DESCRIPTION', '&ALIAS.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&USERID.',
  'DISPLAY_AVATAR', 'N',
  'DISPLAY_BADGE', 'Y',
  'HIDE_BORDERS', 'N',
  'REMOVE_PADDING', 'N')).to_clob
);
