,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'	l_response      CLOB;',
'	v_sql varchar2(4000) := '''' ;',
'	v_base_url varchar2(200) := '''';',
'    v_process varchar2(200) := '''';',
'    v_domain varchar2(200) := '''';',
'    v_alias varchar2(200) := '''';',
'    v_body varchar2(4000) := '''';',
'    v_schema_name varchar2(200) := '''';',
'    v_tables varchar2(200) := '''';',
'    l_order_obj  JSON_OBJECT_T;',
'',
'',
'BEGIN',
'',
'	select gubun1 ||'':''||gubun2||gubun3 into v_base_url',
'	from ogg_conf',
'	where keya = ''EXTRACTURL'' ',
'	and keyb = ''ADMIN''',
'	;',
'',
'    v_body := ''',
'    {',
'        "name": "report",',
'        "reportType": "checkpointTables",',
'        "credentials": {',
'            "alias": "&P134_ALIAS."',
'        },',
'        "specification": "*.*"',
'    }    ',
'    '';',
'',
'	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'	l_response := apex_web_service.make_rest_request ',
'	(',
'		p_url                  => v_base_url || ''/commands/execute'', ',
'        --p_url                  => ''http://172.28.0.5:9012/services/OGGHUB/adminsrvr/v2/commands/execute'', ',
'		p_http_method          => ''POST'', ',
'        p_body                 => v_body,',
'		--p_transfer_timeout     => 10, ',
'		p_username             => ''oggadmin'', ',
'		p_password             => ''WElcome1234##'',',
'		p_scheme               => ''Basic''',
'	); ',
'',
'',
'    begin',
'        execute immediate ''truncate table ogg_ckpt_ui'';',
'    end;',
'    ',
'    delete from ogg_ckpt_ui',
'    where user_id = ''&APP_USER.''',
'    and session_id = ''&APP_SESSION.''',
'    ;',
'    commit;',
'',
'',
'',
'',
'    insert into ogg_ckpt_ui',
'    select ''&APP_USER.'',''&APP_SESSION.'',id,''&P134_DOMAIN.'' domain,''&P134_ALIAS.'' alias, a.table_name ',
'    from',
'    (',
'        select ''1'' id,a.table_name ',
'        from JSON_TABLE(l_response, ',
'            ''$[*]'' COLUMNS (',
'                table_name varchar2(4000) PATH ''$.response.tables[0]''',
'                ) ',
'            ) a ',
'        union all',
'        select ''2'' id,a.table_name ',
'        from JSON_TABLE(l_response, ',
'            ''$[*]'' COLUMNS (',
'                table_name varchar2(4000) PATH ''$.response.tables[1]''',
'                ) ',
'            ) a         ',
'        union all',
'        select ''3'' id,a.table_name ',
'        from JSON_TABLE(l_response, ',
'            ''$[*]'' COLUMNS (',
'                table_name varchar2(4000) PATH ''$.response.tables[2]''',
'                ) ',
'            ) a         ',
'        union all',
'        select ''4'' id,a.table_name ',
'        from JSON_TABLE(l_response, ',
'            ''$[*]'' COLUMNS (',
'                table_name varchar2(4000) PATH ''$.response.tables[3]''',
'                ) ',
'            ) a         ',
'        union all',
'        select ''5'' id,a.table_name ',
'        from JSON_TABLE(l_response, ',
'            ''$[*]'' COLUMNS (',
'                table_name varchar2(4000) PATH ''$.response.tables[4]''',
'                ) ',
'            ) a   ',
'    ) a',
'    where a.table_name is not null',
'    ;',
'    commit;',
'    ',
'	v_sql := ''',
'        select a.id idno,a.domain ,a.alias,a.ckpt "Checkpoint Table" from ogg_ckpt_ui a',
'    '';',
'	',
'	return v_sql;',
'',
'END;',
''))
,p_template_component_type=>'REPORT'
,p_lazy_loading=>false
,p_plug_source_type=>'TMPL_THEME_42$CONTENT_ROW'
,p_plug_query_num_rows=>15
,p_plug_query_num_rows_type=>'SET'
,p_show_total_row_count=>false
,p_landmark_type=>'region'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'APPLY_THEME_COLORS', 'Y',
  'AVATAR_ICON', 'fa-table',
  'AVATAR_SHAPE', 't-Avatar--noShape',
  'AVATAR_TYPE', 'icon',
  'DESCRIPTION', wwv_flow_string.join(wwv_flow_t_varchar2(
    '<b>Checkpoint Table </b><br>',
    '&CHECKPOINT_TABLE.')),
  'DISPLAY_AVATAR', 'Y',
  'DISPLAY_BADGE', 'N',
  'HIDE_BORDERS', 'N',
  'REMOVE_PADDING', 'N')).to_clob
);
