wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(38081285252058837)
,p_plug_name=>'Distribution Paths'
,p_static_id=>'distribution-paths'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(141233965818187007009)
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'	l_response      CLOB;',
'	--v_sql varchar2(4000) := '''' ;',
'    v_sql CLOB := '''' ;',
'	v_base_url varchar2(200) := '''';',
'    v_process varchar2(200) := '''';',
'',
'    cursor c1',
'    is',
'        select distinct remdq(json_serialize(name)) process ',
'        from ',
'        (',
'            select a.session_id,a.res.response.items[0].name name from distpath a',
'            union all',
'            select a.session_id,a.res.response.items[1].name from distpath a',
'            union all',
'            select a.session_id,a.res.response.items[2].name from distpath a',
'            union all',
'            select a.session_id,a.res.response.items[3].name from distpath a',
'            union all',
'            select a.session_id,a.res.response.items[4].name from distpath a',
'            union all',
'            select a.session_id,a.res.response.items[5].name from distpath a',
'            union all',
'            select a.session_id,a.res.response.items[6].name from distpath a',
'            union all',
'            select a.session_id,a.res.response.items[7].name from distpath a',
'            union all',
'            select a.session_id,a.res.response.items[8].name from distpath a',
'            union all',
'            select a.session_id,a.res.response.items[9].name from distpath a',
'        )',
'        where name is not null',
'        and session_id = ''&APP_SESSION.''',
'        ;',
'',
'BEGIN',
'',
'	select gubun1 ||'':''||gubun2||gubun3 into v_base_url',
'	from ogg_conf',
'	where keya = ''DISTPATHURL'' ',
'    and keyb = ''ADMIN''',
'	;',
'',
'',
'    insert into tmp (res) values (v(''APP_SESSION''));',
'    commit;',
'    ',
'	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'	l_response := apex_web_service.make_rest_request ',
'	(',
'		p_url                  => v_base_url || ''/sources'', ',
'        --p_url                  => ''http://172.28.0.5:9112/services/v2'' || ''/replicats'', ',
'		p_http_method          => ''GET'', ',
'		--p_transfer_timeout     => 10, ',
'		p_username             => ''oggadmin'', ',
'		p_password             => ''WElcome1234##'',',
'		p_scheme               => ''Basic''',
'	); ',
'',
'	--dbms_output.put_line(''Response Status : '' || apex_web_service.g_status_code);',
'	--dbms_output.put_line(''Response Payload: '' || l_response);',
'	--begin',
'        --execute immediate ''truncate table distpath'';',
'        --execute immediate ''truncate table distpathinfo'';',
'        --execute immediate ''truncate table distpathdetail'';     ',
'        --execute immediate ''truncate table distpathcheckpoints''; ',
'    --end;',
'',
'    delete from distpath',
'    where user_id = ''&APP_USER.''',
'    and session_id = ''&APP_SESSION.''',
'    ;',
'',
'    delete from distpathinfo',
'    where user_id = ''&APP_USER.''',
'    and session_id = ''&APP_SESSION.''',
'    ;',
'',
'    delete from distpathdetail',
'    where user_id = ''&APP_USER.''',
'    and session_id = ''&APP_SESSION.''',
'    ;',
'',
'    delete from distpathcheckpoints',
'    where user_id = ''&APP_USER.''',
'    and session_id = ''&APP_SESSION.''',
'    ;',
'    commit;',
'    ',
'    insert into distpath (user_id,session_id,res,stat) values (''&APP_USER.'',''&APP_SESSION.'',l_response,apex_web_service.g_status_code);',
'    commit;',
'',
'    open c1;',
'    loop',
'        fetch c1 into v_process;',
'        exit when c1%NOTFOUND;',
'',
'    	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'    	l_response := apex_web_service.make_rest_request ',
'    	(',
'    		p_url                  => v_base_url || ''/sources/''||v_process||''/info'', ',
'            --p_url                  => ''http://172.28.0.5:9112/services/v2'' || ''/replicats'', ',
'    		p_http_method          => ''GET'', ',
'    		--p_transfer_timeout     => 10, ',
'    		p_username             => ''oggadmin'', ',
'    		p_password             => ''WElcome1234##'',',
'    		p_scheme               => ''Basic''',
'    	); ',
'',
'        insert into distpathinfo values (''&APP_USER.'',''&APP_SESSION.'',v_process,l_response,apex_web_service.g_status_code,sysdate);',
'        commit;',
'',
'    	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'    	l_response := apex_web_service.make_rest_request ',
'    	(',
'    		p_url                  => v_base_url || ''/sources/''||v_process, ',
'            --p_url                  => ''http://172.28.0.5:9112/services/v2'' || ''/replicats'', ',
'    		p_http_method          => ''GET'', ',
'    		--p_transfer_timeout     => 10, ',
'    		p_username             => ''oggadmin'', ',
'    		p_password             => ''WElcome1234##'',',
'    		p_scheme               => ''Basic''',
'    	); ',
'',
'        insert into distpathdetail values (''&APP_USER.'',''&APP_SESSION.'',v_process,l_response,apex_web_service.g_status_code,sysdate);',
'        commit;',
'',
'    	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'    	l_response := apex_web_service.make_rest_request ',
'    	(',
'    		p_url                  => v_base_url || ''/sources/''||v_process||''/checkpoints'', ',
'            --p_url                  => ''http://172.28.0.5:9112/services/v2'' || ''/replicats'', ',
'    		p_http_method          => ''GET'', ',
'    		--p_transfer_timeout     => 10, ',
'    		p_username             => ''oggadmin'', ',
'    		p_password             => ''WElcome1234##'',',
'    		p_scheme               => ''Basic''',
'    	); ',
'',
'        insert into distpathcheckpoints values (''&APP_USER.'',''&APP_SESSION.'',v_process,l_response,apex_web_service.g_status_code,sysdate);',
'        commit;',
'',
'    end loop;',
'    close c1;',
'    ',
'	v_sql := ''',
'        select a.process,',
'            max(remdq(json_serialize(a.status))) status,',
'            case when max(remdq(json_serialize(a.status))) = ''''stopped'''' then ''''danger''''',
'                 when max(remdq(json_serialize(a.status))) = ''''abend'''' then ''''warning''''',
'                 when max(remdq(json_serialize(a.status))) = ''''killed'''' then ''''warning''''',
'                 when max(remdq(json_serialize(a.status))) = ''''running'''' then ''''success'''' end status_label,        ',
'            case when max(remdq(json_serialize(a.status))) = ''''stopped'''' then ''''fa-play''''',
'                 when max(remdq(json_serialize(a.status))) = ''''abend'''' then ''''fa-play''''',
'                 when max(remdq(json_serialize(a.status))) = ''''killed'''' then ''''fa-play''''',
'                 when max(remdq(json_serialize(a.status))) = ''''running'''' then ''''fa-stop-circle-o'''' end play_label,  ',
'            case when max(remdq(json_serialize(a.status))) = ''''running'''' then ''''Stop''''',
'                 when max(remdq(json_serialize(a.status))) = ''''stopped'''' then ''''Start''''',
'                 when max(remdq(json_serialize(a.status))) = ''''killed'''' then ''''Start'''' ',
'                 when max(remdq(json_serialize(a.status))) = ''''abended'''' then ''''Start'''' end action_label,',
'            case when max(remdq(json_serialize(a.status))) = ''''running'''' then ''''fa-person-running''''',
'                 when max(remdq(json_serialize(a.status))) = ''''stopped'''' then ''''fa-person-standing''''',
'                 when max(remdq(json_serialize(a.status))) = ''''killed'''' then ''''fa-person-standing'''' ',
'                 when max(remdq(json_serialize(a.status))) = ''''abended'''' then ''''fa-person-standing'''' end process_label,',
'            max(remdq(json_serialize(a.lag))) lag,max(remdq(json_serialize(a.sinceLagReported))) sinceLagReported,max(remdq(json_serialize(a.sourceExtractName))) sourceExtractName,max(remdq(json_serialize(a.sourceDatabaseName))) sourceDatabaseName,',
'            max(remdq(json_serialize(a.sourceuri))) sourceuri,max(remdq(json_serialize(a.targeturi))) targeturi,',
'            max(remdq(json_serialize(a.path))) path,max(remdq(json_serialize(a.inprefix))) inprefix,max(remdq(json_serialize(a.inseq))) inseq,max(remdq(json_serialize(a.inoffset))) inoffset,max(remdq(json_serialize(a.inlength))) inlength,',
'            max(remdq(json_serialize(a.outprefix))) outprefix,max(remdq(json_serialize(a.outseq))) outseq,max(remdq(json_serialize(a.outoffset))) outoffset,max(remdq(json_serialize(a.outlength))) outlength',
'        from',
'        (',
'            select a.session_id,a.process,a.res.response.lag lag,a.res.response.sinceLagReported sinceLagReported,a.res.response.sourceExtractName sourceExtractName,a.res.response.sourceDatabaseName sourceDatabaseName,null sourceuri, null targeturi ,'
||'null status,',
'                null path,null inprefix,null inseq,null inoffset,null inlength,null outprefix,null outseq,null outoffset,null outlength',
'            from distpathinfo a',
'            union all',
'            select a.session_id,a.process,null,null,null,null,a.res.response.source.uri sourceuri,a.res.response.target.uri targeturi ,a.res.response.status status ,',
'                null,null,null,null,null,null,null,null,null',
'            from distpathdetail a',
'            union all',
'            select a.session_id,a.process,null,null,null,null,null,null,null,',
'                a.res.response."current".input.starting.path path ,',
'                a.res.response."current".input."current".name inprefix,',
'                a.res.response."current".input."current".sequence inseq,',
'                a.res.response."current".input."current".offset inoffset,',
'                a.res.response."current".input."current".sequenceLength inlength,',
'                a.res.response."current".output."current".name outprefix,',
'                a.res.response."current".output."current".sequence outseq,',
'                a.res.response."current".output."current".offset outoffset,',
'                a.res.response."current".output."current".sequenceLength outlength',
'            from distpathcheckpoints a',
'        ) a',
'        where session_id = ''''&APP_SESSION.''''',
'        group by a.process',
'    '';',
'	',
'	return v_sql;',
'',
'END;'))
,p_template_component_type=>'REPORT'
,p_lazy_loading=>false
