wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(18866627430035897)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'execute'
,p_static_id=>'execute'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'	l_response      CLOB;',
'	v_sql varchar2(4000) := '''' ;',
'	v_base_url varchar2(200) := '''';',
'    v_process varchar2(200) := '''';',
'    v_body varchar2(4000) := '''';',
'    v_status varchar2(200) := '''';',
'	',
'BEGIN',
'',
'    begin',
'        execute immediate ''truncate table tmp'';',
'    end;',
'',
'	select gubun1 ||'':''||gubun2||gubun3 into v_base_url',
'	from ogg_conf',
'	where keya = ''DISTPATHURL'' ',
'    and keyb = ''ADMIN''',
'	;',
'',
'',
'',
'    insert into tmp (res) values (''v_base_url : ''||v_base_url);',
'    commit;',
'	',
'',
'    select upper(''&P143_PROCESS.'') into v_process ',
'    from dual;',
'',
'    ',
'    insert into tmp (res) values (''v_process : ''||v_process);',
'    commit;',
'	',
'',
'    select distinct remdq(json_serialize(a.res.response.status)) into v_status',
'    from distpathdetail a',
'    where user_id = ''&APP_USER.''',
'    and session_id = ''&APP_SESSION.''',
'    and process = ''&P143_PROCESS.''',
'    ;',
'',
'',
'',
'    insert into tmp (res) values (''v_status : ''||v_status);',
'    commit;',
'	',
'',
'    ',
'    if v_status = ''stopped'' then',
'',
'        v_body := ''{',
'            "status":"running"',
'        }'';',
'',
'    	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
