wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(19027849952242053)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'execute'
,p_static_id=>'execute'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'	l_response      CLOB;',
'	v_sql varchar2(4000) := '''' ;',
'	v_base_url varchar2(200) := '''';',
'    v_process varchar2(200) := '''';',
'    v_body varchar2(4000) := '''';',
'    v_pdb varchar2(200) := '''';',
'    v_type varchar2(200) := '''';',
'    v_checkpointtable varchar2(200) := '''';',
'	',
'BEGIN',
'',
'',
'	select gubun1 ||'':''||gubun2||gubun3 into v_base_url',
'	from ogg_conf',
'	where keya = ''EXTRACTURL'' ',
'	and keyb = ''ADMIN''',
'	;',
'',
'    select upper(''&P157_PROCESS.'') into v_process from dual;',
'',
'    select lower(''&P157_TYPE.'') into v_type from dual;',
'',
'    select remdq(ckpt) into v_checkpointtable from ggsckpt where id = ''&P157_CHECKPOINTTABLE.'';',
'',
'    SELECT ''"containers":["''||NAME||''"],'' into v_pdb FROM V$PDBS;    ',
'',
'    insert into tmp values ('' extract type : &P157_TYPE.'',sysdate);',
'    commit;',
'',
'',
'    insert into tmp values ('' extract type : '' ||v_type,sysdate);',
'    commit;',
'',
'    v_body := ''',
'    {',
'        "source": {',
'            "name": "&P157_TRAIL."',
'        },',
'        "credentials":{',
'            "alias":"&P157_ALIAS_DISPLAY."',
'        },',
'        "config":[',
'            "Replicat    &P157_PROCESS.",',
'            "UseridAlias &P157_ALIAS_DISPLAY.",',
'            "&P157_CONFIG."',
'        ],        ',
'        "checkpoint": {',
'            "table": "''||v_checkpointtable||''"',
'        },',
'        "mode": {',
'            "type": "''||v_type||''"',
'        }        ',
'    }    ',
'    '';',
'',
'',
'    insert into tmp values ('' v_body : ''||v_body,sysdate);',
'    commit;',
'',
'	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'	l_response := apex_web_service.make_rest_request ',
'	(',
'		p_url                  => v_base_url || ''/replicats/''||v_process, ',
'		p_http_method          => ''POST'', ',
'		--p_transfer_timeout     => 10, ',
'        p_body                 => v_body,',
'		p_username             => ''oggadmin'', ',
'		p_password             => ''WElcome1234##'',',
'		p_scheme               => ''Basic''',
'	); ',
'',
'	--dbms_output.put_line(''Response Status : '' || apex_web_service.g_status_code);',
'	--dbms_output.put_line(''Response Payload: '' || l_response);',
'	',
'    insert into tmp values (l_response,sysdate);',
'    commit;',
'',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>11599507321788948
);
end;
