'<div id="ac-wrap">',
'  <div id="ac-bar">',
'    <span class="ac-dot ac-dr"></span><span class="ac-dot ac-dy"></span><span class="ac-dot ac-dg"></span>',
'    <span id="ac-connstr">Oracle GoldenGate Administration Client</span>',
'    <span id="ac-status-led"></span>',
'  </div>',
'  <div id="ac-out"></div>',
'  <div id="ac-in-row">',
'    <span id="ac-prompt">OGG (not connected) 1&gt;&nbsp;</span>',
'    <input id="ac-cmd" type="text" autocomplete="off" spellcheck="false">',
'    <span id="ac-spinner">working...</span>',
'  </div>',
'</div>',
'',
'<script>',
'var AC = {',
'  cmdNo   : 1,',
'  hist    : [],',
'  histIdx : -1,',
'  busy    : false,',
'  connected: false,',
'  user    : ''&APP_USER!JS.'',',
'  appSession: ''&APP_SESSION!JS.'',',
'  sid     : ''OAC_'' + (String(''&APP_SESSION!JS.'') || Math.random().toString(36).substr(2,10).toUpperCase())',
'};',
'',
'var OUT    = document.getElementById(''ac-out'');',
'var CMD    = document.getElementById(''ac-cmd'');',
'var SPN    = document.getElementById(''ac-spinner'');',
'var PROMPT = document.getElementById(''ac-prompt'');',
'var CSTR   = document.getElementById(''ac-connstr'');',
'var LED    = document.getElementById(''ac-status-led'');',
'',
'function apexAjaxEndpoint() {',
'  var path = window.location.pathname;',
'  var idx = path.indexOf(''/r/'');',
'  if (idx >= 0) return path.substring(0, idx) + ''/wwv_flow.ajax'';',
'  idx = path.toLowerCase().indexOf(''/ords/'');',
'  if (idx >= 0) return path.substring(0, idx + 6) + ''wwv_flow.ajax'';',
'  return ''wwv_flow.ajax'';',
'}',
'function apexPageValue(id, fallback) {',
'  var el = document.getElementById(id);',
'  return el && el.value ? el.value : fallback;',
'}',
'function apexAjaxFallback(processName, payload) {',
'  var body = new URLSearchParams();',
'  body.append(''p_flow_id'', apexPageValue(''pFlowId'', ''&APP_ID!JS.''));',
'  body.append(''p_flow_step_id'', apexPageValue(''pFlowStepId'', ''&APP_PAGE_ID!JS.''));',
'  body.append(''p_instance'', apexPageValue(''pInstance'', ''&APP_SESSION!JS.''));',
'  body.append(''p_request'', ''APPLICATION_PROCESS='' + processName);',
'  Object.keys(payload || {}).forEach(function(k){ body.append(k, payload[k]); });',
'  return fetch(apexAjaxEndpoint(), {',
'    method: ''POST'',',
'    credentials: ''same-origin'',',
'    headers: {''Content-Type'': ''application/x-www-form-urlencoded; charset=UTF-8''},',
'    body: body.toString()',
'  }).then(function(r){ if(!r.ok) throw new Error(''HTTP '' + r.status); return r.json(); });',
'}',
'function apexProcess(processName, payload) {',
'  payload = payload || {};',
'  return new Promise(function(resolve, reject) {',
'    function run(tries) {',
'      var ax = window.apex || (window.parent && window.parent.apex);',
'      if (ax && ax.server && ax.server.process) {',
'        ax.server.process(processName, payload, {',
'          dataType: ''json'',',
'          success: resolve,',
'          error: function(jqXHR, textStatus, errorThrown) {',
'            reject(new Error(jqXHR.responseText || errorThrown || textStatus));',
'          }',
'        });',
'        return;',
'      }',
'      if (tries > 0) { setTimeout(function(){ run(tries - 1); }, 50); return; }',
'      apexAjaxFallback(processName, payload).then(resolve).catch(reject);',
'    }',
'    run(40);',
'  });',
'}',
'function adminClientExec(cmd) {',
'  return apexProcess(''ADMINCLIENT_EXEC'', {x01: cmd, x02: ''OGG''});',
'}',
'var HUB_DISP  = ''http://172.28.0.5:9012 OGGHUB'';',
'',
unistr('/* \2500\2500 output helpers \2500\2500 */'),
'function ph(html) {',
'  var d = document.createElement(''div'');',
'  d.innerHTML = html;',
'  OUT.appendChild(d);',
'  OUT.scrollTop = OUT.scrollHeight;',
'}',
'function ptext(text) {',
'  /* Syntax-highlight the adminclient text output */',
'  var html = esc(text)',
'    /* Status words */',
'    .replace(/\bRUNNING\b/g,     ''<span style="color:#3fb950;font-weight:bold">RUNNING</span>'')',
'    .replace(/\bSTOPPED\b/g,     ''<span style="color:#8b949e;font-weight:bold">STOPPED</span>'')',
'    .replace(/\bABENDED\b/g,     ''<span style="color:#f85149;font-weight:bold">ABENDED</span>'')',
'    .replace(/\bINITIALIZED\b/g, ''<span style="color:#79c0ff;font-weight:bold">INITIALIZED</span>'')',
'    /* field labels: "Word Word " style */',
'    .replace(/((?:[A-Z][a-zA-Z]+ )+(?:[A-Z][a-zA-Z]+\s+)?)(\s{2,})/g,',
'             ''<span style="color:#79c0ff">$1</span>$2'')',
'    /* OGG error codes */',
'    .replace(/\b(OGG-\d+)\b/g,  ''<span style="color:#d29922">$1</span>'');',
'  ph(''<pre style="margin:0;margin-bottom:2px">'' + html + ''</pre>'');',
'}',
'function perr(msg)  { ph(''<span style="color:#f85149">  '' + esc(msg) + ''</span>''); }',
'function pwarn(msg) { ph(''<span style="color:#d29922">  '' + esc(msg) + ''</span>''); }',
'function pok(msg)   { ph(''<span style="color:#3fb950">  '' + esc(msg) + ''</span>''); }',
'function pinfo(msg) { ph(''<span style="color:#8b949e">''   + esc(msg) + ''</span>''); }',
'function esc(s){ return String(s||'''').replace(/&/g,''&amp;'').replace(/</g,''&lt;'').replace(/>/g,''&gt;''); }',
'function lastHist(){',
'  for (var i = 0; i < AC.hist.length; i++) {',
'    if (AC.hist[i] && AC.hist[i] !== ''!'') return AC.hist[i];',
'  }',
'  return '''';',
'}',
'',
unistr('/* \2500\2500 prompt \2500\2500 */'),
'function updatePrompt() {',
'  var ctx = AC.connected ? HUB_DISP : ''not connected'';',
'  PROMPT.innerHTML = ''OGG (<span style="color:#c9d1d9">'' + esc(ctx) + ''</span>) '' +',
'                     ''<span style="color:#8b949e">'' + AC.cmdNo + ''</span>&gt;&nbsp;'';',
'}',
'',
unistr('/* \2500\2500 banner \2500\2500 */'),
'function banner() {',
'  ph(''<span style="color:#e3a832;font-weight:bold">Oracle GoldenGate Administration Client</span>'' +',
unistr('     '' <span style="color:#8b949e">for Oracle \2014 Web Terminal</span>'');'),
unistr('  ph(''<span style="color:#484f58">\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500</span>'');'),
'  ph('''');',
'  doConnect();',
'}',
'',
unistr('/* \2500\2500 auto-connect \2500\2500 */'),
'function doConnect() {',
'  LED.style.background = ''#d29922'';',
'  CSTR.textContent = ''Connecting to OGG Hub...'';',
'',
'  adminClientExec(''info replicat d01'')',
'    .then(function(o) {',
'      AC.connected = true;',
'      LED.style.background = ''#27c93f'';',
'      CSTR.textContent = HUB_DISP + ''  (oggadmin)'';',
'      updatePrompt();',
'      pok(''Successfully connected to OGG Hub (OGGHUB)'');',
'      ph('''');',
'      displayResponse(o, ''info replicat d01'');',
'      AC.cmdNo++;',
'      updatePrompt();',
'      CMD.focus();',
'    })',
'    .catch(function(e) {',
'      LED.style.background = ''#f85149'';',
'      CSTR.textContent = ''Connection failed'';',
'      perr(''Cannot connect to OGG Hub: '' + e.message);',
'      updatePrompt();',
'      CMD.focus();',
'    });',
'}',
'',
unistr('/* \2500\2500 keyboard \2500\2500 */'),
'CMD.addEventListener(''keydown'', function(e) {',
'  if (e.key === ''Enter'') {',
'    e.preventDefault(); e.stopPropagation();',
'    var raw = CMD.value.trim();',
'    CMD.value = '''';',
'    if (!raw) return;',
'    ph(''OGG&gt; <span style="color:#e6edf3">'' + esc(raw) + ''</span>'');',
'    AC.histIdx = -1;',
'    if (raw === ''!'') {',
'      var replay = lastHist();',
'      if (replay) {',
'        pinfo(''Repeating: '' + replay);',
'        runCmd(replay);',
'      } else {',
'        runCmd(''!'');',
'      }',
'      return;',
'    }',
'    if (/^!/.test(raw)) {',
'      pwarn(''Use ! by itself to repeat the previous command.'');',
'      return;',
'    }',
'    AC.hist.unshift(raw); if (AC.hist.length > 200) AC.hist.pop();',
'    runCmd(raw);',
'  } else if (e.key === ''ArrowUp'') {',
'    e.preventDefault();',
'    if (AC.histIdx < AC.hist.length-1){ AC.histIdx++; CMD.value = AC.hist[AC.histIdx]; }',
'  } else if (e.key === ''ArrowDown'') {',
'    e.preventDefault();',
'    if (AC.histIdx > 0){ AC.histIdx--; CMD.value = AC.hist[AC.histIdx]; }',
'    else { AC.histIdx = -1; CMD.value = ''''; }',
'  }',
'});',
'document.getElementById(''ac-wrap'').addEventListener(''click'', function(){ CMD.focus(); });',
'',
unistr('/* \2500\2500 dispatcher \2500\2500 */'),
'function runCmd(raw) {',
'  var c = raw.trim().toLowerCase().split(/\s+/)[0];',
'  if (c===''clear''||c===''cls'')  { OUT.innerHTML=''''; return; }',
'  if (c===''help''||c===''?'')     { cmdHelp(); AC.cmdNo++; updatePrompt(); return; }',
'  if (c===''connect'')           { doConnect(); return; }',
'  if (c===''exit''||c===''quit'')  { pinfo(''Session ended.''); CMD.disabled=true; return; }',
'  execCommand(raw);',
'}',
'',
unistr('/* \2500\2500 ORDS call \2500\2500 */'),
'function execCommand(cmd) {',
'  if (AC.busy) return;',
'  setBusy(true);',
'  adminClientExec(cmd)',
'    .then(function(o){',
'      setBusy(false);',
'      displayResponse(o, cmd);',
'      AC.cmdNo++;',
'      updatePrompt();',
'    })',
'    .catch(function(e){',
'      setBusy(false);',
'      perr(e.message);',
'      AC.cmdNo++;',
'      updatePrompt();',
'    });',
'}',
'',
unistr('/* \2500\2500 response formatter \2500\2500 */'),
'function displayResponse(o, cmd) {',
'  if (!o) { pinfo(''(no response)''); return; }',
'  if (o._notfound) { perr(''Command not recognized: '' + cmd); pinfo(''Type help for supported commands.''); return; }',
unistr('  if (o._empty)    { pinfo(''(command executed \2014 no output)''); return; }'),
'  if (o.error)     { perr(o.error); return; }',
'',
unistr('  /* messages array \2014 errors / info */'),
'  if (o.messages && o.messages.length) {',
'    o.messages.forEach(function(m) {',
'      var sev = (m.severity || '''').toUpperCase();',
'      var txt = (m.code ? m.code + ''  '' : '''') + (m.title || m.text || '''');',
'      if      (sev===''ERROR''||sev===''SEVERE'') perr(txt);',
'      else if (sev===''WARNING'')               pwarn(txt);',
'      else                                    pok(txt);',
'    });',
'    ph('''');',
'    return;',
'  }',
'',
unistr('  /* response.reply \2014 actual adminclient text (array or string) */'),
'  if (o.response && o.response.reply !== undefined) {',
'    var reply = o.response.reply;',
'    var text  = Array.isArray(reply) ? reply.join('''') : String(reply);',
'    if (text.trim()) ptext(text);',
unistr('    else             pinfo(''(command executed \2014 no output)'');'),
'    ph('''');',
'    return;',
'  }',
'',
'  pinfo(''(no output)'');',
'}',
'',
unistr('/* \2500\2500 help \2500\2500 */'),
'function cmdHelp() {',
'  ph([',
'    ''<span style="color:#e3b341;font-weight:bold">EXTRACT:</span>'',',
'    ''  <span style="color:#79c0ff">info extract &lt;name&gt;</span>'',',
'    ''  <span style="color:#79c0ff">start / stop / delete extract &lt;name&gt;</span>'',',
'    ''  <span style="color:#79c0ff">add extract &lt;name&gt; integrated tranlog begin now</span>'',',
'    ''  <span style="color:#79c0ff">add exttrail &lt;path&gt; extract &lt;name&gt; megabytes &lt;n&gt;</span>'',',
'    ''  <span style="color:#79c0ff">alter extract &lt;name&gt; begin now</span>'',',
'    ''  <span style="color:#79c0ff">alter extract &lt;name&gt; scn &lt;scn&gt;</span>'',',
'    ''  <span style="color:#79c0ff">register extract &lt;name&gt; database (containers(&lt;pdb&gt;))</span>'',',
'    ''  <span style="color:#79c0ff">unregister extract &lt;name&gt;</span>'',',
'    '''',',
'    ''<span style="color:#e3b341;font-weight:bold">REPLICAT:</span>'',',
'    ''  <span style="color:#79c0ff">info replicat &lt;name&gt;</span>'',',
'    ''  <span style="color:#79c0ff">start / stop / delete replicat &lt;name&gt;</span>'',',
'    ''  <span style="color:#79c0ff">add replicat &lt;name&gt; exttrail &lt;trail&gt; checkpointtable &lt;tbl&gt;</span>'',',
'    ''  <span style="color:#79c0ff">alter replicat &lt;name&gt; begin now</span>'',',
'    '''',',
'    ''<span style="color:#e3b341;font-weight:bold">DISTPATH:</span>'',',
'    ''  <span style="color:#79c0ff">info / start / stop / delete distpath &lt;name&gt;</span>'',',
'    ''  <span style="color:#79c0ff">add distpath &lt;name&gt; source &lt;src&gt; target &lt;tgt&gt;</span>'',',
'    ''  <span style="color:#79c0ff">alter distpath &lt;name&gt; begin &lt;ts&gt;</span>'',',
'    '''',',
'    ''<span style="color:#e3b341;font-weight:bold">Terminal:</span>'',',
unistr('    ''  <span style="color:#79c0ff">connect</span>  \2014 reconnect   '' +'),
unistr('    ''<span style="color:#79c0ff">clear</span>  \2014 clear screen   '' +'),
unistr('    ''<span style="color:#79c0ff">exit</span>  \2014 end session'','),
'    ''''',
'  ].join(''\n''));',
'}',
'',
unistr('/* \2500\2500 helpers \2500\2500 */'),
'function setBusy(v) {',
'  AC.busy = v; CMD.disabled = v;',
'  SPN.style.display = v ? ''inline'' : ''none'';',
'  if (!v) CMD.focus();',
'}',
'',
'banner();',
'</script>',
''))
);
