);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3739491075975898)
,p_plug_name=>'Logdump'
,p_static_id=>'logdump-section-159'
,p_region_template_options=>'#DEFAULT#'
,p_escape_on_http_output=>'Y'
,p_plug_template=>wwv_flow_imp.id(141234128251200007065)
,p_plug_display_sequence=>20
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<style>',
'#ld-wrap{display:flex;flex-direction:column;height:650px;',
'         background:#0d1117;border-radius:8px;overflow:hidden;',
'         font-family:''Courier New'',Courier,monospace;font-size:13px}',
'',
'/* title bar */',
'#ld-bar{background:#161b22;padding:9px 14px;display:flex;align-items:center;',
'        gap:6px;border-bottom:1px solid #30363d;flex-shrink:0}',
'.ld-dot{width:12px;height:12px;border-radius:50%;display:inline-block}',
'.ld-dr{background:#ff5f56}.ld-dy{background:#ffbd2e}.ld-dg{background:#27c93f}',
'#ld-title{color:#8b949e;font-size:12px;margin-left:6px}',
'',
'/* output */',
'#ld-out{flex:1;overflow-y:auto;padding:12px 16px;color:#c9d1d9;',
'        line-height:1.65;word-break:break-all}',
'#ld-out pre{margin:0;white-space:pre-wrap;font-family:inherit;font-size:inherit}',
'',
'/* input row */',
'#ld-in-row{display:flex;align-items:center;padding:8px 14px;flex-shrink:0;',
'           border-top:1px solid #21262d;background:#0d1117}',
'#ld-prompt{color:#c74634;font-weight:bold;white-space:nowrap;margin-right:6px}',
'#ld-cmd{flex:1;background:transparent;border:none;color:#c9d1d9;',
'        font-family:''Courier New'',Courier,monospace;font-size:13px;',
'        outline:none;caret-color:#c74634}',
'#ld-spinner{color:#8b949e;font-size:12px;margin-left:8px;display:none}',
'</style>',
'',
'<div id="ld-wrap">',
'  <div id="ld-bar">',
'    <span class="ld-dot ld-dr"></span>',
'    <span class="ld-dot ld-dy"></span>',
'    <span class="ld-dot ld-dg"></span>',
'    <span id="ld-title">Logdump  --  Trail Analysis</span>',
'  </div>',
'  <div id="ld-out"></div>',
'  <div id="ld-in-row">',
'    <span id="ld-prompt">logdump&gt; </span>',
'    <input id="ld-cmd" type="text" autocomplete="off" spellcheck="false">',
'    <span id="ld-spinner">loading...</span>',
'  </div>',
'</div>',
'',
'<script>',
'/* ================================================================',
'   STATE',
'   ================================================================ */',
'var ST = {',
'  trail    : null,',
'  opts     : {ghdr:true, detail:true, usertoken:true, headertoken:true, ggstoken:true},',
'  cache    : [],',
'  idx      : -1,',
'  nextRba  : null,',
'  eof      : false,',
'  busy     : false,',
'  hist     : [],',
'  histIdx  : -1,',
'  skipRba  : null   /* skip this RBA on next fetch (set after scanforendtrans etc.) */',
'};',
'',
'var OUT = document.getElementById(''ld-out'');',
'var CMD = document.getElementById(''ld-cmd'');',
'var SPN = document.getElementById(''ld-spinner'');',
'',
'/* ================================================================',
'   OUTPUT HELPERS',
'   ================================================================ */',
'function ph(html) {',
'  var d = document.createElement(''div'');',
'  d.innerHTML = html;',
'  OUT.appendChild(d);',
'  OUT.scrollTop = OUT.scrollHeight;',
'}',
'function perr(msg) { ph(''<span style="color:#f85149">ERROR: '' + esc(msg) + ''</span>''); }',
'function pinfo(msg){ ph(''<span style="color:#8b949e">'' + esc(msg) + ''</span>''); }',
'function pok(msg)  { ph(''<span style="color:#3fb950">'' + esc(msg) + ''</span>''); }',
'function esc(s)    {',
'  return String(s||'''')',
'    .replace(/&/g,''&amp;'').replace(/</g,''&lt;'').replace(/>/g,''&gt;'');',
'}',
'function fmtSz(b){',
'  if(b>1048576)return(b/1048576).toFixed(1)+'' MB'';',
'  if(b>1024)return(b/1024).toFixed(1)+'' KB'';',
'  return b+'' B'';',
'}',
'',
'/* ================================================================',
'   STARTUP BANNER + TRAIL LIST',
'   ================================================================ */',
'function banner() {',
'  ph(''<span style="color:#c74634;font-weight:bold">Oracle GoldenGate Logdump</span>'' +',
'     '' <span style="color:#8b949e">-- Web Terminal</span>'');',
'  ph(''<span style="color:#484f58">Click a trail file below to open it, or type '' +',
'     ''<span style="color:#c9d1d9">help</span> for all commands.</span>'');',
'  ph('''');',
'  loadTrails();',
'}',
'',
'function apexAjaxEndpoint() {',
'  var path = window.location.pathname;',
'  var idx = path.indexOf(''/r/'');',
'  if (idx >= 0) return path.substring(0, idx) + ''/wwv_flow.ajax'';',
'  idx = path.toLowerCase().indexOf(''/ords/'');',
'  if (idx >= 0) return path.substring(0, idx + 6) + ''wwv_flow.ajax'';',
'  return ''wwv_flow.ajax'';',
'}',
'function apexPageValue(id, fallback) {',
'  var el = document.getElementById(id);',
'  return el && el.value ? el.value : fallback;',
'}',
'function apexAjaxFallback(processName, payload) {',
'  var body = new URLSearchParams();',
'  body.append(''p_flow_id'', apexPageValue(''pFlowId'', ''&APP_ID!JS.''));',
'  body.append(''p_flow_step_id'', apexPageValue(''pFlowStepId'', ''&APP_PAGE_ID!JS.''));',
'  body.append(''p_instance'', apexPageValue(''pInstance'', ''&APP_SESSION!JS.''));',
'  body.append(''p_request'', ''APPLICATION_PROCESS='' + processName);',
'  Object.keys(payload || {}).forEach(function(k){ body.append(k, payload[k]); });',
'  return fetch(apexAjaxEndpoint(), {',
'    method: ''POST'',',
'    credentials: ''same-origin'',',
'    headers: {''Content-Type'': ''application/x-www-form-urlencoded; charset=UTF-8''},',
'    body: body.toString()',
'  }).then(function(r){ if(!r.ok) throw new Error(''HTTP '' + r.status); return r.json(); });',
'}',
'function apexProcess(processName, payload) {',
'  payload = payload || {};',
'  return new Promise(function(resolve, reject) {',
'    function run(tries) {',
'      var ax = window.apex || (window.parent && window.parent.apex);',
'      if (ax && ax.server && ax.server.process) {',
'        ax.server.process(processName, payload, {',
'          dataType: ''json'',',
'          success: resolve,',
'          error: function(jqXHR, textStatus, errorThrown) {',
'            reject(new Error(jqXHR.responseText || errorThrown || textStatus));',
'          }',
'        });',
'        return;',
'      }',
'      if (tries > 0) { setTimeout(function(){ run(tries - 1); }, 50); return; }',
'      apexAjaxFallback(processName, payload).then(resolve).catch(reject);',
'    }',
'    run(40);',
'  });',
'}',
'function logdumpAjax(processName, payload) {',
'  return apexProcess(processName, payload || {});',
'}',
'',
'function loadTrails() {',
'  logdumpAjax(''LOGDUMP_TRAILS'', {})',
'    .then(function(o) {',
'      var trails = o.trails || [];',
'      if (o.error) { perr(''Trails error: '' + o.error); return; }',
'      if (trails.length) {',
'        pinfo(''Trail files  (click to open):'');',
'        trails.forEach(function(t, i) {',
'          var d2 = document.createElement(''div'');',
'          d2.style.cssText = ''padding:2px 0;cursor:pointer'';',
'          d2.innerHTML =',
'            ''  <span style="color:#484f58">['' + (i+1) + '']</span>  '' +',
'            ''<span style="color:#79c0ff;text-decoration:underline;cursor:pointer" '' +',
'            ''title="click to open">'' + esc(t.name) + ''</span>'' +',
'            ''  <span style="color:#484f58">('' + fmtSz(t.size) + '')</span>'';',
'          d2.addEventListener(''click'', function() {',
'            var cmd = ''open '' + t.path;',
'            ph(''<span style="color:#c74634;font-weight:bold">logdump&gt; </span>'' +',
'               ''<span style="color:#e6edf3">'' + esc(cmd) + ''</span>'');',
'            cmdOpen(t.path);',
'          });',
'          OUT.appendChild(d2);',
'        });',
'        ph('''');',
'      } else {',
'        pinfo(''(No trail files found - type  open <path>  manually)'');',
'      }',
'      OUT.scrollTop = OUT.scrollHeight;',
'    })',
'    .catch(function(e){ perr(''Trails fetch error: '' + e.message); });',
'}',
'',
'/* ================================================================',
'   INPUT HANDLER',
'   ================================================================ */',
'CMD.addEventListener(''keydown'', function(e) {',
'  if (e.key === ''Enter'') {',
'    e.preventDefault();   /* prevent APEX form submit */',
'    e.stopPropagation();',
'    var raw = CMD.value.trim();',
'    CMD.value = '''';',
'    if (raw) { ST.hist.unshift(raw); if (ST.hist.length > 200) ST.hist.pop(); }',
'    ST.histIdx = -1;',
'    ph(''<span style="color:#c74634;font-weight:bold">logdump&gt; </span>'' +',
'       ''<span style="color:#e6edf3">'' + esc(raw) + ''</span>'');',
'    if (raw) runCmd(raw);',
'',
'  } else if (e.key === ''ArrowUp'') {',
'    e.preventDefault();',
'    if (ST.histIdx < ST.hist.length - 1) {',
'      ST.histIdx++;',
'      CMD.value = ST.hist[ST.histIdx];',
'    }',
'  } else if (e.key === ''ArrowDown'') {',
'    e.preventDefault();',
'    if (ST.histIdx > 0) { ST.histIdx--; CMD.value = ST.hist[ST.histIdx]; }',
'    else { ST.histIdx = -1; CMD.value = ''''; }',
'  }',
'});',
'',
'document.getElementById(''ld-wrap'').addEventListener(''click'', function() { CMD.focus(); });',
'',
'/* ================================================================',
'   COMMAND DISPATCHER',
'   ================================================================ */',
'function runCmd(raw) {',
'  var p = raw.trim().split(/\s+/);',
'  var c = p[0].toLowerCase();',
'  var a = p.slice(1);',
'',
'  if      (c === ''open'')                              cmdOpen(a.join('' ''));',
'  else if (c === ''n'' || c === ''next'')                 cmdNext();',
'  else if (c === ''p'' || c === ''prev'')                 cmdPrev();',
'  else if (c === ''pos'' || c === ''position'')           cmdPos(a[0]);',
'  else if (c === ''ghdr'')                              cmdOpt(''ghdr'', a[0]);',
'  else if (c === ''detail'')                            cmdOpt(''detail'', a[0]===''data''?a[1]:a[0]);',
'  else if (c === ''usertoken'')                         cmdOpt(''usertoken'', a[0]===''detail''?a[1]:a[0]);',
'  else if (c === ''headertoken'')                       cmdOpt(''headertoken'', a[0]===''detail''?a[1]:a[0]);',
'  else if (c === ''ggstoken'')                          cmdOpt(''ggstoken'', a[0]===''detail''?a[1]:a[0]);',
'  else if (c === ''status'' || c === ''info'')            cmdStatus();',
'  else if (c === ''clear'' || c === ''cls'')              OUT.innerHTML = '''';',
'  else if (c === ''help'' || c === ''?'')                 cmdHelp();',
'  else if (c === ''exit'' || c === ''quit'' || c === ''q''){ pinfo(''Session ended.''); CMD.disabled = true; }',
'  else cmdPassthrough(raw);   /* forward unknown cmds directly to logdump */',
'}',
'',
'/* ================================================================',
'   COMMANDS',
'   ================================================================ */',
'function cmdOpen(path) {',
'  if (!path) { perr(''Usage: open <trail_path>''); return; }',
'  ST.trail   = path;',
'  ST.cache   = [];',
'  ST.idx     = -1;',
'  ST.nextRba = null;',
'  ST.eof     = false;',
'  pok(''Trail opened: '' + path);',
'  pinfo(''Options : '' + optsStr());',
'  pinfo(''Type n to read the first record.'');',
'  ph('''');',
'}',
'',
'function cmdOpt(key, val) {',
'  if (!val) { perr(''Usage: '' + key + '' on|off''); return; }',
'  var on = val.toLowerCase() === ''on'';',
'  if (ST.opts[key] === on) { pinfo(key + '' already '' + (on ? ''on'' : ''off'')); return; }',
'  ST.opts[key] = on;',
'  pok(key + (on ? '' on'' : '' off''));',
'  if (ST.trail) {',
'    /* clear cache so next n re-fetches with updated options */',
'    var curRba = (ST.idx >= 0 && ST.cache[ST.idx]) ? ST.cache[ST.idx].rba : null;',
'    ST.cache = [];',
'    ST.idx   = -1;',
'    if (curRba !== null) ST.nextRba = curRba;',
'    ST.eof = false;',
'    pinfo(''(re-fetches from RBA '' + (curRba !== null ? curRba : ''0'') + '' on next n)'');',
'  }',
'}',
'',
'function cmdPos(rba) {',
'  if (!rba || isNaN(rba)) { perr(''Usage: pos <rba_number>''); return; }',
'  if (!ST.trail) { perr(''No trail open. Use: open <path>''); return; }',
'  ST.cache   = [];',
'  ST.idx     = -1;',
'  ST.nextRba = parseInt(rba, 10);',
'  ST.eof     = false;',
'  pok(''Positioned at RBA '' + rba);',
'  pinfo(''Type n to read.'');',
'}',
'',
'function cmdNext() {',
'  if (!ST.trail) { perr(''No trail open. Use: open <path>''); return; }',
'  if (ST.busy)   return;',
'',
'  /* serve from cache */',
'  if (ST.idx < ST.cache.length - 1) {',
'    ST.idx++;',
'    showRec(ST.cache[ST.idx]);',
'    return;',
'  }',
'',
'  if (ST.eof) { pinfo(''*** End of trail ***''); return; }',
'',
'  /* fetch next batch */',
'  setBusy(true);',
'  var pos = ST.nextRba !== null ? String(ST.nextRba) : ''0'';',
'',
'  logdumpAjax(''LOGDUMP_READ'', {x01: ST.trail, x02: pos, x03: optsStr(), x04: ''5''})',
'    .then(function(o) {',
'      setBusy(false);',
'      if (o.error) { perr(o.error); return; }',
'',
'      var recs = o.records || [];',
'',
'      /* skip a record already shown by scanforendtrans / similar scan commands */',
'      if (ST.skipRba !== null && recs.length > 0 && recs[0].rba === ST.skipRba) {',
'        recs = recs.slice(1);',
'      }',
'      ST.skipRba = null;',
'',
'      if (!recs.length) {',
'        if (o.eof) { ST.eof = true; pinfo(''*** End of trail ***''); }',
'        else {',
'          /* the only fetched record was skipped; advance position and tell user */',
'          ST.nextRba = o.next_rba;',
unistr('          pinfo(''(skipped duplicate \2014 press n again)'');'),
'        }',
'        return;',
'      }',
'',
'      recs.forEach(function(r) { ST.cache.push(r); });',
'      ST.nextRba = o.next_rba;',
'      ST.eof     = o.eof;',
'      ST.idx++;',
'      showRec(ST.cache[ST.idx]);',
'    })',
'    .catch(function(e) {',
'      setBusy(false);',
'      perr(''Fetch error: '' + e.message);',
'    });',
'}',
'',
'function cmdPrev() {',
'  if (!ST.trail)   { perr(''No trail open.''); return; }',
'  if (ST.idx <= 0) { pinfo(''Already at first record.''); return; }',
'  ST.idx--;',
'  showRec(ST.cache[ST.idx]);',
'}',
'',
'function cmdStatus() {',
'  pinfo([',
'    ''Trail   : '' + (ST.trail || ''(none)''),',
'    ''Options : '' + optsStr(),',
'    ''Cache   : '' + ST.cache.length + '' records,  current='' + (ST.idx + 1),',
'    ''Next RBA: '' + (ST.nextRba !== null ? ST.nextRba : ''(start)''),',
'    ''EOF     : '' + ST.eof',
'  ].join(''\n''));',
'}',
'',
'function cmdHelp() {',
'  ph([',
'    ''<span style="color:#e3b341">Built-in commands:</span>'',',
'    ''  <span style="color:#79c0ff">open &lt;path&gt;</span>               Open trail file'',',
'    ''  <span style="color:#79c0ff">n</span>  /  <span style="color:#79c0ff">next</span>               Next record'',',
'    ''  <span style="color:#79c0ff">p</span>  /  <span style="color:#79c0ff">prev</span>               Previous record (from cache)'',',
'    ''  <span style="color:#79c0ff">pos &lt;rba&gt;</span>                  Jump to RBA position'',',
'    ''  <span style="color:#79c0ff">ghdr on|off</span>                Toggle global header (Hdr-Ind section)'',',
'    ''  <span style="color:#79c0ff">detail data on|off</span>         Toggle column values + hex dump'',',
'    ''  <span style="color:#79c0ff">usertoken detail on|off</span>    Toggle user tokens'',',
'    ''  <span style="color:#79c0ff">headertoken detail on|off</span>  Toggle header tokens'',',
'    ''  <span style="color:#79c0ff">ggstoken detail on|off</span>     Toggle GGS tokens'',',
'    ''  <span style="color:#79c0ff">status</span>                     Show session info'',',
'    ''  <span style="color:#79c0ff">clear</span>                      Clear screen'',',
'    ''  <span style="color:#79c0ff">exit</span>                       End session'',',
'    '''',',
'    ''<span style="color:#e3b341">Passthrough (sent directly to logdump):</span>'',',
'    ''  <span style="color:#79c0ff">scanforendtrans</span>            Scan to end of current transaction'',',
'    ''  <span style="color:#79c0ff">count</span>                      Count records in trail'',',
'    ''  <span style="color:#79c0ff">fileheader</span>                 Show trail file header info'',',
'    ''  <span style="color:#79c0ff">filter include table &lt;tbl&gt;</span> Filter by table name'',',
'    ''  <span style="color:#79c0ff">filter clear</span>               Clear filter'',',
'    ''  <span style="color:#79c0ff">show</span>                       Show current logdump settings'',',
'    ''  <span style="color:#8b949e">... any other logdump command is also accepted</span>''',
'  ].join(''\n''));',
'  ph('''');',
'}',
'',
'function cmdPassthrough(raw) {',
'  if (!ST.trail) { perr(''No trail open. Use: open <path>''); return; }',
'  if (ST.busy) return;',
'  setBusy(true);',
'',
'  /* use current record''s rba as position so context is preserved */',
'  var pos = (ST.idx >= 0 && ST.cache[ST.idx])',
'    ? String(ST.cache[ST.idx].rba)',
'    : (ST.nextRba !== null ? String(ST.nextRba) : ''0'');',
'',
'  logdumpAjax(''LOGDUMP_EXEC'', {x01: ST.trail, x02: pos, x03: optsStr(), x04: raw})',
'    .then(function(o) {',
'      setBusy(false);',
'      if (o.error) { perr(o.error); return; }',
'      if (o.output) {',
'        ph(''<pre style="margin:0;margin-bottom:4px;color:#c9d1d9;white-space:pre-wrap">'' +',
'           esc(o.output) + ''</pre>'');',
'',
unistr('        /* \2500\2500 position-tracking: update ST.nextRba when command moves the cursor \2500\2500 */'),
'        var rbaFromOutput = extractPositionFromOutput(o.output);',
'        if (rbaFromOutput !== null) {',
'          ST.cache   = [];',
'          ST.idx     = -1;',
'          ST.nextRba = rbaFromOutput;',
'          ST.eof     = false;',
'          ST.skipRba = rbaFromOutput;  /* skip re-showing this record on next n */',
'          pinfo(''(cursor at RBA '' + rbaFromOutput + ''  --  press n for NEXT record)'');',
'        }',
'      } else {',
'        pinfo(''(no output)'');',
'      }',
'    })',
'    .catch(function(e) {',
'      setBusy(false);',
'      perr(''Exec error: '' + e.message);',
'    });',
'}',
'',
'/* Extract the final cursor RBA from passthrough command output.',
'   Returns null when the command is not a position-changing scan. */',
'function extractPositionFromOutput(out) {',
'  /* scanforendtrans / scanforbegin output:',
'       "End of Transaction found at RBA 886281"',
'       "Begin of Transaction found at RBA 12345" */',
'  var m = out.match(/(?:End|Begin) of Transaction found at RBA\s+(\d+)/i);',
'  if (m) return parseInt(m[1], 10);',
'',
'  /* generic "found at RBA NNN" fallback */',
'  m = out.match(/found at RBA\s+(\d+)/i);',
'  if (m) return parseInt(m[1], 10);',
'',
'  return null;',
'}',
'',
'/* ================================================================',
'   RECORD RENDERER',
'   ================================================================ */',
'function showRec(rec) {',
'  if (!rec) { perr(''(empty record)''); return; }',
'',
'  var sep = ''<span style="color:#30363d">'' + rep(''-'', 68) + ''</span>'';',
'  var html = sep + ''\n'';',
'',
'  var op    = String(rec.operation || '''').toUpperCase();',
'  var opClr = ''#79c0ff'';',
'  if      (op === ''INSERT'') opClr = ''#3fb950'';',
'  else if (op === ''UPDATE'') opClr = ''#d29922'';',
'  else if (op === ''DELETE'') opClr = ''#f85149'';',
'',
'  if (rec.timestamp)',
'    html += ''<span style="color:#8b949e">'' + esc(rec.timestamp) + ''</span>  '';',
'  if (rec.operation)',
'    html += ''<span style="color:'' + opClr + '';font-weight:bold">'' +',
'            padR(esc(rec.operation), 10) + ''</span>  '';',
'  if (rec.length !== undefined)',
'    html += ''Len  '' + padL(String(rec.length), 6) + ''  '';',
'  if (rec.rba !== undefined)',
'    html += ''RBA  '' + padL(String(rec.rba), 8);',
'  html += ''\n'';',
'',
'  if (rec.table)',
'    html += ''<span style="color:#e3b341">Name: '' + esc(rec.table) + ''</span>\n'';',
'',
'  if (rec.raw) {',
'    var lines = esc(rec.raw).split(''\n'');',
'    lines = lines.map(function(ln) {',
'      if (/^_{20,}/.test(ln)) return null;',
'      return ln.replace(',
'        /^([A-Za-z][A-Za-z0-9 _\-]{1,28})\s*(:\s*)(.+)/,',
'        function(_, k, sp, v) {',
'          return ''<span style="color:#79c0ff">'' + k + ''</span>'' +',
'                 ''<span style="color:#484f58">'' + sp + ''</span>'' +',
'                 ''<span style="color:#a8d8f8">'' + v + ''</span>'';',
'        }',
'      );',
'    }).filter(function(l){ return l !== null; });',
'    html += lines.join(''\n'');',
'  }',
'',
'  ph(''<pre style="margin:0;margin-bottom:6px">'' + html + ''</pre>'');',
'}',
'',
'/* ================================================================',
'   HELPERS',
'   ================================================================ */',
'function optsStr() {',
'  return Object.keys(ST.opts).filter(function(k){ return ST.opts[k]; }).join('','');',
'}',
'function setBusy(v) {',
'  ST.busy = v;',
'  CMD.disabled = v;',
'  SPN.style.display = v ? ''inline'' : ''none'';',
'  if (!v) CMD.focus();',
'}',
'function padR(s, n) { while(s.length < n) s += '' ''; return s; }',
'function padL(s, n) { while(s.length < n) s = '' '' + s; return s; }',
'function rep(c, n)  { var s = ''''; while(s.length < n) s += c; return s; }',
'',
'/* ================================================================',
'   INIT',
'   ================================================================ */',
'banner();',
'CMD.focus();',
'</script>',
''))
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(39186279422904334)
,p_plug_name=>'New'
,p_static_id=>'new'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(141233965818187007009)
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'	l_response      CLOB;',
'	v_sql varchar2(4000) := '''' ;',
'	v_base_url varchar2(200) := '''';',
'    v_process varchar2(200) := '''';',
'    v_trail varchar2(200) := '''';',
'',
'    cursor c1 ',
'    is',
'        select distinct remdq(json_serialize(name)) name',
'        from',
'        (',
'            select a.session_id,a.res.response.items[0].name name from trails a',
'            union all',
'            select a.session_id,a.res.response.items[1].name name from trails a',
'            union all',
'            select a.session_id,a.res.response.items[2].name name from trails a',
'            union all',
'            select a.session_id,a.res.response.items[3].name name from trails a',
'            union all',
'            select a.session_id,a.res.response.items[4].name name from trails a',
'            union all',
'            select a.session_id,a.res.response.items[5].name name from trails a',
'            union all',
'            select a.session_id,a.res.response.items[6].name name from trails a',
'            union all',
'            select a.session_id,a.res.response.items[7].name name from trails a',
'            union all',
'            select a.session_id,a.res.response.items[8].name name from trails a',
'            union all',
'            select a.session_id,a.res.response.items[9].name name from trails a',
'        )',
'        where session_id = ''&APP_SESSION.''',
'        and name is not null',
'        ;',
'',
'BEGIN',
'',
'	select gubun1 ||'':''||gubun2||gubun3 into v_base_url',
'	from ogg_conf',
'	where keya = ''EXTRACTURL'' ',
'	and keyb = ''ADMIN''',
'	;',
'',
'',
'    insert into tmp (res) values (v(''APP_SESSION''));',
'    commit;    ',
'',
'	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'	l_response := apex_web_service.make_rest_request ',
'	(',
'		p_url                  => v_base_url || ''/trails'', ',
'        --p_url                  => ''http://172.28.0.5:9112/services/v2'' || ''/replicats'', ',
'		p_http_method          => ''GET'', ',
'		--p_transfer_timeout     => 10, ',
'		p_username             => ''oggadmin'', ',
'		p_password             => ''WElcome1234##'',',
'		p_scheme               => ''Basic''',
'	); ',
'',
'	--dbms_output.put_line(''Response Status : '' || apex_web_service.g_status_code);',
'	--dbms_output.put_line(''Response Payload: '' || l_response);',
'	--begin',
'        --execute immediate ''truncate table trails'';',
'        --execute immediate ''truncate table traildetail'';',
'    --end;',
'',
'    delete from trails',
'    where user_id = ''&APP_USER.''',
'    and session_id = ''&APP_SESSION.''',
'    ;',
'',
'    delete from traildetail',
'    where user_id = ''&APP_USER.''',
'    and session_id = ''&APP_SESSION.''',
'    ;',
'    commit;',
'    ',
'    insert into trails (user_id,session_id,res,stat) values (''&APP_USER.'',''&APP_SESSION.'',l_response,apex_web_service.g_status_code);',
'    commit;',
'',
'    open c1;',
'    loop',
'        fetch c1 into v_trail;',
'        exit when c1%NOTFOUND;',
'',
'    	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'    	l_response := apex_web_service.make_rest_request ',
'    	(',
'    		p_url                  => v_base_url || ''/trails/''||v_trail, ',
'            --p_url                  => ''http://172.28.0.5:9112/services/v2'' || ''/replicats'', ',
'    		p_http_method          => ''GET'', ',
'    		--p_transfer_timeout     => 10, ',
'    		p_username             => ''oggadmin'', ',
'    		p_password             => ''WElcome1234##'',',
'    		p_scheme               => ''Basic''',
'    	); ',
'',
'        insert into traildetail (user_id,session_id,trail,res,stat) values (''&APP_USER.'',''&APP_SESSION.'',v_trail,l_response,apex_web_service.g_status_code);',
'        commit;',
'',
'    end loop;',
'    ',
'	v_sql := ''',
'        select remdq(json_serialize(a.res.response.name)) name,--a.res.response.processRef.processName name,',
'            remdq(json_serialize(a.res.response.processRef[0].processName)) producer,',
'            remdq(json_serialize(a.res.response.processRef[1].processName)) consumer,',
'            remdq(json_serialize(a.res.response.processRef[2].processName)) distpath,',
'            remdq(json_serialize(a.res.response.sizeMB)) Max_Size,',
'            remdq(json_serialize(a.res.response.spaceUsed)) Total_Space_Used,',
'            remdq(json_serialize(a.res.response.sequenceMin)) ||'''' to '''' || remdq(json_serialize(a.res.response.sequenceMax)) Sequences,',
'            ''''fa-download'''' actions,',
'            ''''fa-clock-o is-open'''' icon1,',
'            ''''fa-clock-o is-open" style="color:red'''' icon2',
'        from traildetail a ',
'        where session_id = ''''&APP_SESSION.''''',
'        order by session_id,trail',
'    '';',
'	',
'	return v_sql;',
'',
'END;'))
,p_template_component_type=>'REPORT'
,p_lazy_loading=>false
,p_plug_source_type=>'TMPL_THEME_42$CONTENT_ROW'
,p_plug_query_num_rows=>15
,p_plug_query_num_rows_type=>'SET'
,p_show_total_row_count=>false
,p_plug_header=>wwv_flow_string.join(wwv_flow_t_varchar2(
