 p_id=>160
,p_name=>'Data Streams'
,p_alias=>'DATA-STREAMS'
,p_step_title=>'Data Streams'
,p_autocomplete_on_off=>'OFF'
,p_step_template=>wwv_flow_imp.id(141233955725549006988)
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'27'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(38934531425229147)
,p_plug_name=>'Data Streams'
,p_static_id=>'data-streams'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(141233965818187007009)
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'	l_response      CLOB;',
'	v_sql varchar2(32767) := '''' ;',
'	v_base_url varchar2(200) := '''';',
'    v_process varchar2(200) := '''';',
'',
'    cursor c1 ',
'    is',
'    select distinct remdq(json_serialize(process)) process',
'    from',
'    (',
'        select a.session_id,a.res.response.items[0].name process,a.res.response.items[0].details.source.trail trail,a.res.response.items[0].details.qualityOfService qualityOfService from datastreams a',
'        union all',
'        select a.session_id,a.res.response.items[1].name,a.res.response.items[1].details.source.trail,a.res.response.items[1].details.qualityOfService from datastreams a',
'        union all',
'        select a.session_id,a.res.response.items[2].name,a.res.response.items[2].details.source.trail,a.res.response.items[2].details.qualityOfService from datastreams a',
'        union all',
'        select a.session_id,a.res.response.items[3].name,a.res.response.items[3].details.source.trail,a.res.response.items[3].details.qualityOfService from datastreams a',
'        union all',
'        select a.session_id,a.res.response.items[4].name,a.res.response.items[4].details.source.trail,a.res.response.items[4].details.qualityOfService from datastreams a',
'        union all',
'        select a.session_id,a.res.response.items[5].name,a.res.response.items[5].details.source.trail,a.res.response.items[5].details.qualityOfService from datastreams a',
'        union all',
'        select a.session_id,a.res.response.items[6].name,a.res.response.items[6].details.source.trail,a.res.response.items[6].details.qualityOfService from datastreams a',
'        union all',
'        select a.session_id,a.res.response.items[7].name,a.res.response.items[7].details.source.trail,a.res.response.items[7].details.qualityOfService from datastreams a',
'        union all',
'        select a.session_id,a.res.response.items[8].name,a.res.response.items[8].details.source.trail,a.res.response.items[8].details.qualityOfService from datastreams a',
'        union all',
'        select a.session_id,a.res.response.items[9].name,a.res.response.items[9].details.source.trail,a.res.response.items[9].details.qualityOfService from datastreams a',
'    )',
'    where process is not null',
'    and session_id = ''&APP_SESSION.''',
'    ;',
'',
'BEGIN',
'',
'	select gubun1 ||'':''||gubun2||gubun3 into v_base_url',
'	from ogg_conf',
'	where keya = ''DISTPATHURL'' ',
'	and keyb = ''ADMIN''',
'	;',
'',
'	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'	l_response := apex_web_service.make_rest_request ',
'	(',
'		p_url                  => v_base_url || ''/stream'', ',
'        --p_url                  => ''http://172.28.0.5:9112/services/v2'' || ''/replicats'', ',
'		p_http_method          => ''GET'', ',
'		--p_transfer_timeout     => 10, ',
'		p_username             => ''oggadmin'', ',
'		p_password             => ''WElcome1234##'',',
'		p_scheme               => ''Basic''',
'	); ',
'',
'	--dbms_output.put_line(''Response Status : '' || apex_web_service.g_status_code);',
'	--dbms_output.put_line(''Response Payload: '' || l_response);',
'	begin',
'        --execute immediate ''truncate table datastreams'';',
'        --execute immediate ''truncate table datastreamyaml'';',
'        execute immediate ''truncate table tmp'';',
'    end;',
'',
'    delete from datastreams',
'    where user_id = ''&APP_USER.''',
'    and session_id = ''&APP_SESSION.''',
'    ;',
'',
'    delete from datastreamyaml',
'    where user_id = ''&APP_USER.''',
'    and session_id = ''&APP_SESSION.''',
'    ;',
'    ',
'    commit;',
'',
'    insert into datastreams (user_id,session_id,res,stat) values (''&APP_USER.'',''&APP_SESSION.'',l_response,apex_web_service.g_status_code);',
'    commit;',
'',
'    ',
'    insert into tmp (res) values (l_response);',
'    commit;',
'',
'    open c1;',
'    loop',
'        fetch c1 into v_process;',
'        exit when c1%NOTFOUND;',
'',
'    	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'    	l_response := apex_web_service.make_rest_request ',
'    	(',
'    		p_url                  => v_base_url || ''/stream/''||v_process||''/yaml'', ',
'            --p_url                  => ''http://172.28.0.5:9112/services/v2'' || ''/replicats'', ',
'    		p_http_method          => ''GET'', ',
'    		--p_transfer_timeout     => 10, ',
'    		p_username             => ''oggadmin'', ',
'    		p_password             => ''WElcome1234##'',',
'    		p_scheme               => ''Basic''',
'    	); ',
'',
'        insert into datastreamyaml values (''&APP_USER.'',''&APP_SESSION.'',v_process,l_response,apex_web_service.g_status_code,sysdate);',
'        commit;',
'',
'        ',
'    end loop;',
'',
'',
'',
'	v_sql := ''',
'    select process,',
'           trail,',
'           ''''<div class="ds-row">''''||',
'           ''''<div class="dc dc1"><strong>''''||apex_escape.html(process)||''''</strong></div>''''||',
'           ''''<div class="dc dc2"><span class="ds-trail">''''||apex_escape.html(trail)||''''</span></div>''''||',
'           ''''<div class="dc dc3"><span class="ds-host">''''||apex_escape.html(nvl(host,''''-''''))||''''</span></div>''''||',
'           ''''<div class="dc dc4">''''||apex_escape.html(nvl(port,''''-''''))||''''</div>''''||',
'           ''''<div class="dc dc5"><span class="ds-protocol">''''||apex_escape.html(nvl(protocol,''''-''''))||''''</span></div>''''||',
'           ''''<div class="dc dc6"><span class="ds-qos">''''||apex_escape.html(nvl(qualityOfService,''''-''''))||''''</span></div>''''||',
'           ''''</div>'''' qualityOfService',
'      from (',
'    select distinct',
'        remdq(json_serialize(ds.process)) process,',
'        remdq(json_serialize(ds.trail)) trail,',
'        remdq(json_serialize(ds.qualityOfService)) qualityOfService,',
'        (select regexp_substr(',
'                  regexp_replace(regexp_substr(dbms_lob.substr(y.res,4000,1), ''''host:[[:space:]]*[^[:space:]]+''''), ''''^host:[[:space:]]*'''', ''''''''),',
'                  ''''^[^:]+'''')',
'           from datastreamyaml y',
'          where y.session_id = ''''&APP_SESSION.''''',
'            and y.process = remdq(json_serialize(ds.process))',
'            and rownum = 1) host,',
'        (select regexp_substr(',
'                  regexp_replace(regexp_substr(dbms_lob.substr(y.res,4000,1), ''''host:[[:space:]]*[^[:space:]]+''''), ''''^host:[[:space:]]*'''', ''''''''),',
'                  ''''[0-9]+$'''')',
'           from datastreamyaml y',
'          where y.session_id = ''''&APP_SESSION.''''',
'            and y.process = remdq(json_serialize(ds.process))',
'            and rownum = 1) port,',
'        (select lower(regexp_replace(',
'                  regexp_substr(dbms_lob.substr(y.res,4000,1), ''''protocol:[[:space:]]*[^[:space:]]+''''),',
'                  ''''^protocol:[[:space:]]*'''', ''''''''))',
'           from datastreamyaml y',
'          where y.session_id = ''''&APP_SESSION.''''',
'            and y.process = remdq(json_serialize(ds.process))',
'            and rownum = 1) protocol',
'        from',
'        (',
'            select a.session_id,a.res.response.items[0].name process,a.res.response.items[0].details.source.trail trail,a.res.response.items[0].details.qualityOfService qualityOfService from datastreams a',
'            union all',
'            select a.session_id,a.res.response.items[1].name,a.res.response.items[1].details.source.trail,a.res.response.items[1].details.qualityOfService from datastreams a',
'            union all',
'            select a.session_id,a.res.response.items[2].name,a.res.response.items[2].details.source.trail,a.res.response.items[2].details.qualityOfService from datastreams a',
'            union all',
'            select a.session_id,a.res.response.items[3].name,a.res.response.items[3].details.source.trail,a.res.response.items[3].details.qualityOfService from datastreams a',
'            union all',
'            select a.session_id,a.res.response.items[4].name,a.res.response.items[4].details.source.trail,a.res.response.items[4].details.qualityOfService from datastreams a',
'            union all',
'            select a.session_id,a.res.response.items[5].name,a.res.response.items[5].details.source.trail,a.res.response.items[5].details.qualityOfService from datastreams a',
'            union all',
'            select a.session_id,a.res.response.items[6].name,a.res.response.items[6].details.source.trail,a.res.response.items[6].details.qualityOfService from datastreams a',
'            union all',
'            select a.session_id,a.res.response.items[7].name,a.res.response.items[7].details.source.trail,a.res.response.items[7].details.qualityOfService from datastreams a',
'            union all',
'            select a.session_id,a.res.response.items[8].name,a.res.response.items[8].details.source.trail,a.res.response.items[8].details.qualityOfService from datastreams a',
'            union all',
'            select a.session_id,a.res.response.items[9].name,a.res.response.items[9].details.source.trail,a.res.response.items[9].details.qualityOfService from datastreams a',
'        ) ds',
'        where ds.process is not null',
'        and session_id = ''''&APP_SESSION.''''',
'        ) rendered_ds',
''';',
'	',
'	return v_sql;',
'',
'END;'))
,p_template_component_type=>'REPORT'
,p_lazy_loading=>false
,p_plug_source_type=>'TMPL_THEME_42$CONTENT_ROW'
,p_plug_query_num_rows=>15
,p_plug_query_num_rows_type=>'SET'
,p_show_total_row_count=>false
,p_plug_header=>wwv_flow_string.join(wwv_flow_t_varchar2(
