'',
'	select gubun1 ||'':''||gubun2||gubun3 into v_base_url',
'	from ogg_conf',
'	where keya = ''EXTRACTURL'' ',
'	and keyb = ''ADMIN''',
'	;',
'',
'',
'    select to_number(''&P163_SEQUENCE_START.''),to_number(''&P163_SEQUENCE_END.'') into v_sequence_start, v_sequence_end from dual;',
'',
'    begin ',
'        execute immediate ''truncate table tmp'';',
'    end;',
'',
'    select ''&P163_PROCESS.'' into v_upper_process from dual;',
'',
'    insert into tmp values (''delete_options : &P163_DELETE_OPTION.'',sysdate);',
'    commit;',
'',
'    insert into tmp values (''v_start : &P163_SEQUENCE_START.'',sysdate);',
'    commit;',
'',
'    insert into tmp values (''v_end : &P163_SEQUENCE_END.'',sysdate);',
'    commit;',
'',
'    if ''&P163_DELETE_OPTION.'' = ''20'' then',
'        for i in v_sequence_start..v_sequence_end loop',
'            insert into tmp values (''in loop : '' || i,sysdate);',
'            commit;',
'            ',
'        	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'        	l_response := apex_web_service.make_rest_request ',
'        	(',
'        		p_url                  => v_base_url || ''/trails/&P163_PROCESS./sequences/''||i, ',
'        		p_http_method          => ''DELETE'', ',
'        		--p_transfer_timeout     => 10, ',
'                --p_body                 => v_body,',
'        		p_username             => ''oggadmin'', ',
'        		p_password             => ''WElcome1234##'',',
'        		p_scheme               => ''Basic''',
'        	); ',
'',
'        	--dbms_output.put_line(''Response Status : '' || apex_web_service.g_status_code);',
'        	--dbms_output.put_line(''Response Payload: '' || l_response);',
'',
'            insert into tmp values (l_response,sysdate);',
'            commit; ',
'',
'       ',
'        end loop;',
'',
'    elsif ''&P163_DELETE_OPTION.'' = ''10'' then   ',
'',
'    	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'    	l_response := apex_web_service.make_rest_request ',
'    	(',
'    		p_url                  => v_base_url || ''/trails/&P163_PROCESS.'', ',
'    		p_http_method          => ''DELETE'', ',
'    		--p_transfer_timeout     => 10, ',
'            --p_body                 => v_body,',
'    		p_username             => ''oggadmin'', ',
'    		p_password             => ''WElcome1234##'',',
'    		p_scheme               => ''Basic''',
'    	); ',
'',
'    	--dbms_output.put_line(''Response Status : '' || apex_web_service.g_status_code);',
'    	--dbms_output.put_line(''Response Payload: '' || l_response);',
'',
'        insert into tmp values (''p_url : ''||v_base_url || ''/trails/&P163_PROCESS.'',sysdate);',
'        commit; ',
'',
'        insert into tmp values (l_response,sysdate);',
'        commit; ',
'',
'    end if;',
'END;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>11469849295633252
);
