wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(18893318496080560)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'execute'
,p_static_id=>'execute'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_response_b     BLOB;',
'    l_dat_b          BLOB;',
'    v_base_url varchar2(200) := '''';',
'    v_sequence_start number;',
'    v_sequence_end number;',
'    lt_parm_names   apex_application_global.VC_ARR2; ',
'    lt_parm_values  apex_application_global.VC_ARR2; ',
'',
'    hFile          UTL_FILE.file_type;',
'    lobOffset      number;',
'    lobSize        number;',
'    bytesRead      number;',
'    rawBuffer      raw(32767);',
'    amount         number;',
'    directory varchar2(2000) := ''TRAILS'';',
'    fileName varchar2(2000) := '''';',
'    l_dat_file varchar2(2000) := ''lgd.dat'';',
'    l_request varchar2(100) := upper(nvl(v(''REQUEST''),''SUBMIT''));',
'',
'    procedure write_blob_to_file(p_blob in blob, p_filename in varchar2) is',
'    begin',
'        lobSize := DBMS_LOB.GetLength(p_blob);',
'        hFile := UTL_FILE.fOpen(directory, p_filename, ''wb'');',
'        lobOffset := 1;',
'        bytesRead := 32767;',
'        if lobSize < bytesRead then',
'            bytesRead := lobSize;',
'        end if;',
'',
'        while lobOffset <= lobSize loop',
'            amount := least(bytesRead, lobSize - lobOffset + 1);',
'            DBMS_LOB.read(',
'                lob_loc => p_blob,',
'                amount  => amount,',
'                offset  => lobOffset,',
'                buffer  => rawBuffer',
'            );',
'            lobOffset := lobOffset + amount;',
'            UTL_FILE.put_raw(hFile, rawBuffer);',
'        end loop;',
'        UTL_FILE.fClose(hFile);',
'    exception',
'        when others then',
'            begin',
'                if UTL_FILE.is_open(hFile) then',
'                    UTL_FILE.fClose(hFile);',
'                end if;',
'            exception when others then null;',
'            end;',
'            raise;',
'    end;',
'',
'    procedure drop_table_if_exists(p_table in varchar2) is',
'    begin',
'        execute immediate ''drop table ggadmin.'' || p_table || '' purge'';',
'    exception',
'        when others then',
'            if sqlcode != -942 then',
'                raise;',
'            end if;',
'    end;',
'',
'    procedure recreate_analysis_tables is',
'    begin',
'        drop_table_if_exists(''LGD_TMP'');',
'        drop_table_if_exists(''LGD'');',
'',
'        execute immediate q''[',
'create table ggadmin.lgd (',
'  file_no varchar2(40),',
'  file_name varchar2(512),',
'  resv1 varchar2(4000), resv2 varchar2(4000), resv3 varchar2(4000),',
'  resv4 varchar2(4000), resv5 varchar2(4000), resv6 varchar2(4000),',
'  resv7 varchar2(4000), resv8 varchar2(4000), resv9 varchar2(4000),',
'  resv10 varchar2(4000), resv11 varchar2(4000), resv12 varchar2(4000), resv13 varchar2(4000)',
')',
'organization external (',
'  type oracle_loader',
'  default directory TRAILS',
'  access parameters (',
'    records delimited by newline',
'    fields terminated by ''|''',
'    missing field values are null',
'    reject rows with all null fields',
'    (file_no char(40), file_name char(512),',
'     resv1 char(4000), resv2 char(4000), resv3 char(4000), resv4 char(4000), resv5 char(4000),',
'     resv6 char(4000), resv7 char(4000), resv8 char(4000), resv9 char(4000), resv10 char(4000),',
'     resv11 char(4000), resv12 char(4000), resv13 char(4000))',
'  )',
'  location (''lgd.dat'')',
')',
'parallel 5',
'reject limit unlimited',
']'';',
'',
'        execute immediate q''[',
'create table ggadmin.lgd_tmp nologging as',
'select row_number() over(order by file_no, resv10) id,',
'       sysdate dt,',
'       file_no, file_name,',
'       resv1, resv2, resv3, resv4, resv5, resv6, resv7, resv8, resv9,',
'       resv10, resv11, resv12, resv13,',
'       case when file_no is not null and resv10 is not null',
'            then file_no * 1000000000000000 + resv10',
'       end global_rba',
'from (',
'  select case when regexp_like(trim(file_no), ''^[0-9]+$'') then to_number(trim(file_no)) end file_no,',
'         trim(file_name) file_name,',
'         trim(resv1) resv1, trim(resv2) resv2, trim(resv3) resv3,',
'         trim(resv4) resv4, trim(resv5) resv5, trim(resv6) resv6,',
'         trim(resv7) resv7, trim(resv8) resv8, trim(resv9) resv9,',
'         case when regexp_like(trim(resv10), ''^[-]?[0-9]+$'') then to_number(trim(resv10)) end resv10,',
'         trim(resv11) resv11, trim(resv12) resv12, trim(resv13) resv13',
'  from ggadmin.lgd',
'  where trim(resv1) is not null',
')',
']'';',
'',
'        execute immediate ''create index ggadmin.lgd_tmp_idx01 on ggadmin.lgd_tmp (resv10, resv1)'';',
'        execute immediate ''create index ggadmin.lgd_tmp_idx02 on ggadmin.lgd_tmp (global_rba, resv1)'';',
'        begin',
'            dbms_stats.gather_table_stats(ownname => ''GGADMIN'', tabname => ''LGD_TMP'', cascade => true);',
'        exception when others then null;',
'        end;',
'    end;',
'',
'BEGIN',
'',
'    select gubun1 ||'':''||gubun2||gubun3 into v_base_url',
'    from ogg_conf',
'    where keya = ''EXTRACTURL'' ',
'    and keyb = ''ADMIN'';',
'',
'    lt_parm_names(1)  := ''download''; ',
'    lt_parm_values(1) := ''true''; ',
'',
'    v_sequence_start := to_number(:P164_SEQUENCE_START);',
'    v_sequence_end := to_number(:P164_SEQUENCE_END);',
'    if v_sequence_end < v_sequence_start then',
'        raise_application_error(-20000, ''Sequence End must be greater than or equal to Sequence Start.'');',
'    end if;',
'',
'    begin ',
'        execute immediate ''truncate table ggadmin.tmp'';',
'        execute immediate ''truncate table ggadmin.trail_arg'';',
'    end;',
'',
'    insert into trail_arg values (''2'',:P164_SEQUENCE_START);',
'    insert into trail_arg values (''3'',:P164_SEQUENCE_END);',
'    commit;',
'',
'    if l_request = ''SUBMIT'' then',
'        for i in v_sequence_start..v_sequence_end loop',
'            apex_web_service.set_request_headers(p_name_01 => ''Accept'', p_value_01 => ''application/binary'', p_reset => TRUE); ',
'            l_response_b := apex_web_service.make_rest_request_b(',
'                p_url        => v_base_url || ''/trails/'' || :P164_PROCESS || ''/sequences/'' || i, ',
'                p_http_method => ''GET'', ',
'                p_username    => ''oggadmin'', ',
'                p_password    => ''WElcome1234##'',',
'                p_parm_name   => lt_parm_names,',
'                p_parm_value  => lt_parm_values, ',
'                p_scheme      => ''Basic''',
'            ); ',
'',
'            if apex_web_service.g_status_code >= 400 then',
'                raise_application_error(-20001, ''Trail download failed. HTTP status='' || apex_web_service.g_status_code);',
'            end if;',
'',
'            filename := :P164_PROCESS || lpad(i,9,''0'');',
'            write_blob_to_file(l_response_b, filename);',
'        end loop;',
'        commit;',
'',
'    elsif l_request = ''ANALYZE'' then',
'        begin',
'            UTL_FILE.fRemove(directory, l_dat_file);',
'        exception when others then null;',
'        end;',
'',
'        apex_web_service.set_request_headers(p_name_01 => ''Accept'', p_value_01 => ''text/plain'', p_reset => TRUE);',
'        l_dat_b := apex_web_service.make_rest_request_b(',
'            p_url => ''http://172.28.0.5:8765/api/parse13dat?prefix='' || apex_util.url_encode(:P164_PROCESS) ||',
'                     ''&start='' || v_sequence_start || ''&end='' || v_sequence_end,',
'            p_http_method => ''GET''',
'        );',
'',
'        if apex_web_service.g_status_code >= 400 then',
'            raise_application_error(-20002, ''Trail parse DAT generation failed. HTTP status='' || apex_web_service.g_status_code);',
'        end if;',
'',
'        write_blob_to_file(l_dat_b, l_dat_file);',
'        recreate_analysis_tables;',
'        commit;',
'        apex_util.redirect_url(apex_page.get_url(p_page => 10, p_clear_cache => ''10''));',
'        apex_application.stop_apex_engine;',
'    end if;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>11464975865627455
);
end;
/
