wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(10032273479864741)
,p_plug_name=>'Admin Client Live Terminal'
,p_static_id=>'aclive-section-165'
,p_region_template_options=>'#DEFAULT#'
,p_escape_on_http_output=>'Y'
,p_plug_template=>wwv_flow_imp.id(141234128251200007065)
,p_plug_display_sequence=>10
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<style>',
'#al-wrap{display:flex;flex-direction:column;height:calc(100vh - 180px);min-height:520px;',
'         background:#0d1117;border-radius:8px;overflow:hidden;',
'         font-family:''Courier New'',Courier,monospace;font-size:13px}',
'#al-bar{background:#161b22;padding:8px 14px;display:flex;align-items:center;',
'        gap:8px;border-bottom:1px solid #30363d;flex-shrink:0}',
'.al-dot{width:12px;height:12px;border-radius:50%;display:inline-block}',
'.al-dr{background:#ff5f56}.al-dy{background:#ffbd2e}.al-dg{background:#27c93f}',
'.al-tab{padding:3px 12px;border-radius:4px;font-size:12px;font-weight:bold;',
'        cursor:pointer;border:1px solid #30363d;background:#0d1117;color:#8b949e;',
'        font-family:''Courier New'',Courier,monospace;transition:all .2s}',
'.al-tab:hover{border-color:#58a6ff;color:#58a6ff}',
'.al-tab.active-ogg {background:#0c2d6b;border-color:#58a6ff;color:#79c0ff}',
'.al-tab.active-bd  {background:#1a2d1a;border-color:#3fb950;color:#3fb950}',
'#al-connstr{color:#8b949e;font-size:11px;flex:1;margin-left:4px}',
'#al-led{width:8px;height:8px;border-radius:50%;background:#555;flex-shrink:0;transition:background .3s}',
'#al-out{flex:1;overflow-y:auto;padding:12px 16px;color:#c9d1d9;line-height:1.65;word-break:break-all}',
'#al-in-row{display:flex;align-items:center;padding:8px 14px;flex-shrink:0;',
'           border-top:1px solid #21262d;background:#0d1117}',
'#al-prompt{color:#e3a832;font-weight:bold;white-space:nowrap;margin-right:6px}',
'#al-cmd{flex:1;background:transparent;border:none;color:#c9d1d9;',
'        font-family:''Courier New'',Courier,monospace;font-size:13px;',
'        outline:none;caret-color:#e3a832}',
'#al-spinner{color:#8b949e;font-size:12px;margin-left:8px;display:none}',
'</style>',
'',
'<div id="al-wrap">',
'  <div id="al-bar">',
'    <span class="al-dot al-dr"></span>',
'    <span class="al-dot al-dy"></span>',
'    <span class="al-dot al-dg"></span>',
'    <button type="button" id="tab-ogg" class="al-tab active-ogg" onclick="switchDep(''OGG'')">OGGHUB</button>',
'    <button type="button" id="tab-bd"  class="al-tab"            onclick="switchDep(''BD'')">OGGBD</button>',
unistr('    <span id="al-connstr">Oracle GoldenGate Administration Client \2014 Live</span>'),
'    <span id="al-led"></span>',
'  </div>',
'  <div id="al-out"></div>',
'  <div id="al-in-row">',
'    <span id="al-prompt">OGG (not connected) 1&gt;&nbsp;</span>',
'    <input id="al-cmd" type="text" autocomplete="off" spellcheck="false">',
'    <span id="al-spinner">working...</span>',
'  </div>',
'</div>',
'',
'<script>',
'var DEPS = {',
'  OGG: { label:''OGGHUB'', host:''http://172.28.0.5:9012'', tabClass:''active-ogg'' },',
'  BD:  { label:''OGGBD'',  host:''http://172.28.0.6:9012'', tabClass:''active-bd''  }',
'};',
'',
'var AL = {',
'  cmdNo:1,',
'  hist:[],',
'  hidx:-1,',
'  busy:false,',
'  dep:''OGG'',',
'  user:''&APP_USER!JS.'',',
'  appSession:''&APP_SESSION!JS.'',',
'  sid:''AL_'' + (String(''&APP_SESSION!JS.'') || Math.random().toString(36).substr(2,10).toUpperCase())',
'};',
'',
'var OUT    = document.getElementById(''al-out'');',
'var CMD    = document.getElementById(''al-cmd'');',
'var SPN    = document.getElementById(''al-spinner'');',
'var PROMPT = document.getElementById(''al-prompt'');',
'var CSTR   = document.getElementById(''al-connstr'');',
'var LED    = document.getElementById(''al-led'');',
'',
'function apexAjaxEndpoint() {',
'  var path = window.location.pathname;',
'  var idx = path.indexOf(''/r/'');',
'  if (idx >= 0) return path.substring(0, idx) + ''/wwv_flow.ajax'';',
'  idx = path.toLowerCase().indexOf(''/ords/'');',
'  if (idx >= 0) return path.substring(0, idx + 6) + ''wwv_flow.ajax'';',
'  return ''wwv_flow.ajax'';',
'}',
'function apexPageValue(id, fallback) {',
'  var el = document.getElementById(id);',
'  return el && el.value ? el.value : fallback;',
'}',
'function apexAjaxFallback(processName, payload) {',
'  var body = new URLSearchParams();',
'  body.append(''p_flow_id'', apexPageValue(''pFlowId'', ''&APP_ID!JS.''));',
'  body.append(''p_flow_step_id'', apexPageValue(''pFlowStepId'', ''&APP_PAGE_ID!JS.''));',
'  body.append(''p_instance'', apexPageValue(''pInstance'', ''&APP_SESSION!JS.''));',
'  body.append(''p_request'', ''APPLICATION_PROCESS='' + processName);',
'  Object.keys(payload || {}).forEach(function(k){ body.append(k, payload[k]); });',
'  return fetch(apexAjaxEndpoint(), {',
'    method: ''POST'',',
'    credentials: ''same-origin'',',
'    headers: {''Content-Type'': ''application/x-www-form-urlencoded; charset=UTF-8''},',
'    body: body.toString()',
'  }).then(function(r){ if(!r.ok) throw new Error(''HTTP '' + r.status); return r.json(); });',
'}',
'function apexProcess(processName, payload) {',
'  payload = payload || {};',
'  return new Promise(function(resolve, reject) {',
'    function run(tries) {',
'      var ax = window.apex || (window.parent && window.parent.apex);',
'      if (ax && ax.server && ax.server.process) {',
'        ax.server.process(processName, payload, {',
'          dataType: ''json'',',
'          success: resolve,',
'          error: function(jqXHR, textStatus, errorThrown) {',
'            reject(new Error(jqXHR.responseText || errorThrown || textStatus));',
'          }',
'        });',
'        return;',
'      }',
'      if (tries > 0) { setTimeout(function(){ run(tries - 1); }, 50); return; }',
'      apexAjaxFallback(processName, payload).then(resolve).catch(reject);',
'    }',
'    run(40);',
'  });',
'}',
'function adminClientLiveExec(cmd) {',
'  return apexProcess(''ADMINCLIENT_LIVE_EXEC'', {x01: cmd, x02: AL.dep});',
'}',
'function adminClientLiveConfig() {',
'  return apexProcess(''ADMINCLIENT_LIVE_CONFIG'', {});',
'}',
'',
unistr('/* \2500\2500 output helpers \2500\2500 */'),
'function ph(html){',
'  var d=document.createElement(''div'');',
'  d.innerHTML=html;',
'  OUT.appendChild(d);',
'  OUT.scrollTop=OUT.scrollHeight;',
'}',
'function esc(s){return String(s||'''').replace(/&/g,''&amp;'').replace(/</g,''&lt;'').replace(/>/g,''&gt;'');}',
'function ptext(text){',
'  var html=esc(text)',
'    .replace(/\bRUNNING\b/g,    ''<span style="color:#3fb950;font-weight:bold">RUNNING</span>'')',
'    .replace(/\bSTOPPED\b/g,    ''<span style="color:#8b949e;font-weight:bold">STOPPED</span>'')',
'    .replace(/\bABENDED\b/g,    ''<span style="color:#f85149;font-weight:bold">ABENDED</span>'')',
'    .replace(/\bKILLED\b/g,     ''<span style="color:#f85149;font-weight:bold">KILLED</span>'')',
'    .replace(/\bINITIALIZED\b/g,''<span style="color:#79c0ff;font-weight:bold">INITIALIZED</span>'')',
'    .replace(/\b(OGG-\d+)\b/g,  ''<span style="color:#d29922">$1</span>'');',
'  ph(''<pre style="margin:0;margin-bottom:2px">''+html+''</pre>'');',
'}',
'function perr(msg) {ph(''<span style="color:#f85149">  ''+esc(msg)+''</span>'');}',
'function pok(msg)  {ph(''<span style="color:#3fb950">  ''+esc(msg)+''</span>'');}',
'function pinfo(msg){ph(''<span style="color:#8b949e">''+esc(msg)+''</span>'');}',
unistr('function psep()    {ph(''<span style="color:#30363d">\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500</span>'');}'),
'function lastHist(){',
'  for (var i = 0; i < AL.hist.length; i++) {',
'    if (AL.hist[i] && AL.hist[i] !== ''!'') return AL.hist[i];',
'  }',
'  return '''';',
'}',
'',
unistr('/* \2500\2500 prompt \2500\2500 */'),
'function updatePrompt(){',
'  var d = DEPS[AL.dep];',
'  PROMPT.innerHTML = ''OGG (<span style="color:#c9d1d9">''+esc(d.host+'' ''+d.label)+''</span>) ''',
'                   + ''<span style="color:#8b949e">''+AL.cmdNo+''</span>&gt;&nbsp;'';',
'}',
'',
unistr('/* \2500\2500 deployment switch \2500\2500 */'),
'function switchDep(dep){',
'  if(AL.busy) return;',
'  AL.dep = dep;',
'  AL.cmdNo = 1;',
'  AL.hist = []; AL.hidx = -1;',
'  /* update tab styles */',
'  document.getElementById(''tab-ogg'').className = ''al-tab'' + (dep===''OGG'' ? '' active-ogg'' : '''');',
'  document.getElementById(''tab-bd'').className  = ''al-tab'' + (dep===''BD''  ? '' active-bd''  : '''');',
'  OUT.innerHTML = '''';',
'  var d = DEPS[dep];',
'  psep();',
'  ph(''<span style="color:#e3a832;font-weight:bold">Switching to ''+esc(d.label)+''</span>'');',
'  psep();',
'  ph('''');',
'  doConnect();',
'}',
'',
unistr('/* \2500\2500 connect \2500\2500 */'),
'function doConnect(){',
'  var d = DEPS[AL.dep];',
'  LED.style.background=''#d29922'';',
'  CSTR.textContent = ''Connecting to ''+d.label+''...'';',
'  adminClientLiveExec(''info all'')',
'    .then(function(o){',
'      if(o.error) throw new Error(o.error);',
'      LED.style.background = AL.dep===''OGG'' ? ''#58a6ff'' : ''#3fb950'';',
'      CSTR.textContent = d.host+''  (''+d.label+'' / oggadmin)'';',
'      pok(''Connected to ''+d.label);',
'      ph('''');',
'      ptext(o.output||''(no output)'');',
'      ph('''');',
'      AL.cmdNo++;',
'      updatePrompt();',
'      CMD.focus();',
'    })',
'    .catch(function(e){',
'      LED.style.background=''#f85149'';',
unistr('      CSTR.textContent = d.label+'' \2014 connection failed'';'),
'      perr(''Cannot connect to ''+d.label+'': ''+e.message);',
'      updatePrompt();',
'      CMD.focus();',
'    });',
'}',
'',
unistr('/* \2500\2500 keyboard \2500\2500 */'),
'CMD.addEventListener(''keydown'',function(e){',
'  if(e.key===''Enter''){',
'    e.preventDefault();',
'    var raw=CMD.value.trim();',
'    CMD.value='''';',
'    if(!raw) return;',
'    ph(''OGG&gt; <span style="color:#e6edf3">''+esc(raw)+''</span>'');',
'    AL.hidx=-1;',
'    if(raw===''!''){',
'      var replay=lastHist();',
'      if(replay){',
'        pinfo(''Repeating: ''+replay);',
'        runCmd(replay);',
'      } else {',
'        runCmd(''!'');',
'      }',
'      return;',
'    }',
'    if(/^!/.test(raw)){',
'      perr(''Use ! by itself to repeat the previous command.'');',
'      return;',
'    }',
'    AL.hist.unshift(raw);if(AL.hist.length>200)AL.hist.pop();',
'    runCmd(raw);',
'  } else if(e.key===''ArrowUp''){',
'    e.preventDefault();',
'    if(AL.hidx<AL.hist.length-1){AL.hidx++;CMD.value=AL.hist[AL.hidx];}',
'  } else if(e.key===''ArrowDown''){',
'    e.preventDefault();',
'    if(AL.hidx>0){AL.hidx--;CMD.value=AL.hist[AL.hidx];}',
'    else{AL.hidx=-1;CMD.value='''';}',
'  }',
'});',
'document.getElementById(''al-wrap'').addEventListener(''click'',function(){CMD.focus();});',
'',
unistr('/* \2500\2500 dispatcher \2500\2500 */'),
'function runCmd(raw){',
'  var c=raw.trim().toLowerCase().split(/\s+/)[0];',
'  if(c===''clear''||c===''cls''){OUT.innerHTML='''';return;}',
'  if(c===''connect''){doConnect();return;}',
'  if(c===''exit''||c===''quit''){pinfo(''Session ended.'');CMD.disabled=true;return;}',
'  execCmd(raw);',
'}',
'',
'function execCmd(cmd){',
'  if(AL.busy) return;',
'  AL.busy=true; CMD.disabled=true; SPN.style.display=''inline'';',
'  adminClientLiveExec(cmd)',
'    .then(function(o){',
'      done();',
'      if(o.error) perr(o.error);',
'      else if(o.output!==undefined){',
'        if(o.output.trim()) ptext(o.output);',
unistr('        else pinfo(''(command executed \2014 no output)'');'),
'      } else pinfo(''(no output)'');',
'      ph('''');',
'    })',
'    .catch(function(e){done();perr(e.message);ph('''');});',
'}',
'',
unistr('/* ogg_conf \FFFD\FFFD\FFFD\FFFD\FFFD\FFFD config \FFFD\FFFD\FFFD\FFFD\FFFD\FFFD */'),
'function loadConfigAndConnect() {',
'  adminClientLiveConfig()',
'    .then(function(cfg){',
'      if(cfg.ogg_host) DEPS.OGG.host = cfg.ogg_host;',
'      if(cfg.bd_host)  DEPS.BD.host  = cfg.bd_host;',
'    })',
'    .catch(function(){})',
'    .finally(function(){ doConnect(); });',
'}',
'',
'function done(){',
'  AL.busy=false; CMD.disabled=false; SPN.style.display=''none'';',
'  AL.cmdNo++; updatePrompt(); CMD.focus();',
'}',
'',
unistr('/* \2500\2500 init \2500\2500 */'),
'ph(''<span style="color:#e3a832;font-weight:bold">Oracle GoldenGate Administration Client</span>''',
unistr('  +'' <span style="color:#8b949e">\2014 Live Terminal</span>'');'),
'ph(''<span style="color:#484f58">Deployments: </span>''',
'  +''<span style="color:#79c0ff">OGGHUB</span>''',
'  +'' <span style="color:#484f58">(OGG for Oracle) &nbsp;|&nbsp; </span>''',
'  +''<span style="color:#3fb950">OGGBD</span>''',
'  +'' <span style="color:#484f58">(OGG for BigData/Kafka)</span>'');',
'psep();',
'ph('''');',
'loadConfigAndConnect();',
'</script>',
''))
);
