,p_static_id=>'adminclient-live-config'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_ogg_host    varchar2(4000) := ''http://172.28.0.5:9012'';',
'  l_bd_host     varchar2(4000) := ''http://172.28.0.6:9012'';',
'  l_header_sent boolean := false;',
'',
'  procedure send_header is',
'  begin',
'    if not l_header_sent then',
'      owa_util.mime_header(''application/json'', false);',
'      owa_util.http_header_close;',
'      l_header_sent := true;',
'    end if;',
'  end;',
'begin',
'  begin',
'    select gubun1 || '':'' || gubun2',
'      into l_ogg_host',
'      from ogg_conf',
'     where keya = ''EXTRACTURL''',
'       and keyb = ''ADMIN''',
'       and rownum = 1;',
'  exception',
'    when others then null;',
'  end;',
'',
'  begin',
'    select gubun1 || '':'' || gubun2',
'      into l_bd_host',
'      from ogg_conf',
'     where keya = ''BDREPLICATURL''',
'       and keyb = ''ADMIN''',
'       and rownum = 1;',
'  exception',
'    when others then null;',
'  end;',
'',
'  send_header;',
'  apex_json.open_object;',
'  apex_json.write(''ogg_host'', l_ogg_host);',
'  apex_json.write(''bd_host'', l_bd_host);',
'  apex_json.close_object;',
'exception',
'  when others then',
'    send_header;',
'    sys.htp.prn(''{"error":'' || apex_json.stringify(sqlerrm) || ''}'');',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>101260101165001
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(10127077474475157)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'ADMINCLIENT_LIVE_EXEC'
,p_static_id=>'adminclient-live-exec'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_cmd         varchar2(32767) := apex_application.g_x01;',
'  l_dep         varchar2(30)    := upper(nvl(apex_application.g_x02, ''OGG''));',
'  l_response    clob;',
'  l_chunk       pls_integer := 32000;',
'  l_len         pls_integer;',
'  l_header_sent boolean := false;',
'',
'  procedure send_header is',
'  begin',
'    if not l_header_sent then',
'      owa_util.mime_header(''application/json'', false);',
'      owa_util.http_header_close;',
'      l_header_sent := true;',
'    end if;',
'  end;',
'',
'  procedure print_clob(p_clob in clob) is',
'  begin',
'    if p_clob is null then',
'      sys.htp.prn(''{}'');',
'      return;',
'    end if;',
'    l_len := dbms_lob.getlength(p_clob);',
'    if l_len = 0 then',
'      return;',
'    end if;',
'    for i in 1 .. ceil(l_len / l_chunk) loop',
'      sys.htp.prn(dbms_lob.substr(p_clob, l_chunk, ((i - 1) * l_chunk) + 1));',
'    end loop;',
'  end;',
'',
'  function helper_url return varchar2 is',
'  begin',
'    if l_dep in (''BD'', ''OGGBD'') then',
'      return ''http://172.28.0.6:8765/api/adminclient'';',
'    end if;',
'    return ''http://172.28.0.5:8765/api/adminclient'';',
'  end;',
'begin',
'  send_header;',
'  if l_cmd is null then',
'    sys.htp.prn(''{"error":"cmd parameter required"}'');',
'    return;',
'  end if;',
'',
'  l_response := apex_web_service.make_rest_request(',
'    p_url         => helper_url() || ''?cmd='' || apex_util.url_encode(l_cmd),',
'    p_http_method => ''GET'');',
'  print_clob(l_response);',
'exception',
'  when others then',
'    send_header;',
'    sys.htp.prn(''{"error":'' || apex_json.stringify(sqlerrm) || ''}'');',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>101260101165002
);
end;
