wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(4463552447010517)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CREATE_DATA_STREAM'
,p_static_id=>'execute'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'declare',
'  l_command  varchar2(4000);',
'  l_severity varchar2(30);',
'  l_code     varchar2(100);',
'  l_title    varchar2(4000);',
'begin',
'  :P166_STREAM_NAME := trim(:P166_STREAM_NAME);',
'  :P166_TRAIL := trim(:P166_TRAIL);',
'',
'  if not regexp_like(:P166_STREAM_NAME, ''^[A-Za-z][A-Za-z0-9_-]{0,127}$'') then',
'    raise_application_error(-20001,',
'      ''Data Stream Name must start with a letter and contain only letters, numbers, underscore, or hyphen.'');',
'  end if;',
'',
'  if not regexp_like(:P166_TRAIL, ''^[A-Za-z0-9_./-]{1,255}$'') then',
'    raise_application_error(-20002,',
'      ''Source Trail contains unsupported characters.'');',
'  end if;',
'',
'  l_command := ''ADD DATASTREAM '' || :P166_STREAM_NAME || '' '' || :P166_TRAIL;',
'',
'  -- Reuse the exact Web Admin Client parser and REST implementation.',
'  ggadmin.proc_command(',
'    v(''APP_USER''),',
'    v(''APP_SESSION''),',
'    l_command,',
'    null',
'  );',
'',
'  select json_value(res, ''$.messages[0].severity'' returning varchar2(30) null on error),',
'         json_value(res, ''$.messages[0].code'' returning varchar2(100) null on error),',
'         json_value(res, ''$.messages[0].title'' returning varchar2(4000) null on error)',
'    into l_severity, l_code, l_title',
'    from ggadmin.issue_commands',
'   where user_id = v(''APP_USER'')',
'     and session_id = v(''APP_SESSION'')',
'     and commands = l_command',
'   order by dt desc',
'   fetch first 1 row only;',
'',
'  if upper(nvl(l_severity, ''ERROR'')) not in (''INFO'', ''SUCCESS'') then',
'    raise_application_error(-20003,',
'      nvl(l_code || '': '', '''') || nvl(l_title, ''Data Stream creation failed.''));',
'  end if;',
'',
'  apex_application.g_print_success_message :=',
'    apex_escape.html(nvl(l_code || '': '', '''') ||',
'                     nvl(l_title, ''Data Stream created successfully.''));',
'exception',
