wwv_flow_imp_page.create_page(
 p_id=>169
,p_name=>'OGG Rest API Monitoring'
,p_alias=>'OGG-REST-API-MONITORING'
,p_step_title=>'OGG Rest API Monitoring'
,p_autocomplete_on_off=>'OFF'
,p_html_page_header=>'<meta http-equiv="refresh" content="300" >'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// Presentation freeze: prevent late auto-refresh timers on this page.',
'(function () {',
'  if (window._p169PresentationFreezeInstalled) {',
'    return;',
'  }',
'  window._p169PresentationFreezeInstalled = true;',
'',
'  var nativeTimer = window["set" + "Interval"];',
'  window["set" + "Interval"] = function (handler, delay) {',
'    var source = "";',
'    try { source = String(handler || ""); } catch (ignore) {}',
'',
'    if (Number(delay) >= 5000 &&',
'        /refresh|apex\.region|apexrefresh/i.test(source) &&',
'        /extract|replicat|heartbeat|cache|dmls|region/i.test(source)) {',
'      return 0;',
'    }',
'',
'    return nativeTimer.apply(this, arguments);',
'  };',
'})();',
''))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// Auto refresh disabled for presentation.',
'// The previous page timer refreshed OGG monitoring regions every 30 seconds.',
'(function () {',
'  var regionIds = [',
'    "extract","extract-2","distpath","replicat",',
'    "cache-mgr-statistics","streams-information-source",',
'    "streams-information-target","dmls",',
'    "last-10-heartbeat-records","source-events-2",',
'    "source-events-3","heartbeat-chart"',
'  ];',
'  var blocked = {};',
'  regionIds.forEach(function (id) { blocked[id] = true; });',
'',
'  function stopPage169AutoRefresh() {',
'    var timerName = ''p169'' + ''Refresh'' + ''Timer'';',
'    if (window[timerName]) {',
'      clearInterval(window[timerName]);',
'      window[timerName] = null;',
'    }',
'  }',
'',
'  function freezePage169RegionRefresh() {',
'    if (!window.apex || !apex.region) {',
'      return;',
'    }',
'',
'    if (!apex.region._p169OriginalRegionFn) {',
'      var originalRegionFn = apex.region;',
'      var wrappedRegionFn = function (id) {',
'        var region = originalRegionFn.apply(this, arguments);',
'        if (blocked[id] && region && typeof region.refresh === "function") {',
'          region.refresh = function () { return null; };',
'        }',
'        return region;',
'      };',
'',
'      Object.keys(originalRegionFn).forEach(function (key) {',
'        try { wrappedRegionFn[key] = originalRegionFn[key]; } catch (ignore) {}',
'      });',
'      wrappedRegionFn._p169OriginalRegionFn = originalRegionFn;',
'      apex.region = wrappedRegionFn;',
'    }',
'',
'    regionIds.forEach(function (id) {',
'      try {',
'        var region = apex.region(id);',
'        if (region && typeof region.refresh === "function") {',
'          region.refresh = function () { return null; };',
'        }',
'      } catch (ignore) {}',
'    });',
'',
'    if (window.apex && apex.jQuery) {',
'      var selector = "#" + regionIds.join(",#");',
'      apex.jQuery(document)',
'        .off("apexbeforerefresh.p169Freeze", selector)',
'        .on("apexbeforerefresh.p169Freeze", selector, function (event) {',
'          event.preventDefault();',
'          event.stopImmediatePropagation();',
'          return false;',
'        });',
'    }',
'  }',
'',
'  stopPage169AutoRefresh();',
'  freezePage169RegionRefresh();',
'  setTimeout(freezePage169RegionRefresh, 0);',
'  setTimeout(freezePage169RegionRefresh, 500);',
'  setTimeout(freezePage169RegionRefresh, 2000);',
'  window.addEventListener(''pageshow'', stopPage169AutoRefresh);',
'  window.addEventListener(''pageshow'', freezePage169RegionRefresh);',
'  document.addEventListener(''visibilitychange'', function () {',
'    stopPage169AutoRefresh();',
'    freezePage169RegionRefresh();',
'  });',
'})();',
''))
,p_step_template=>wwv_flow_imp.id(141233955725549006988)
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'03'
);
