 p_id=>wwv_flow_imp.id(18928123849154214)
,p_chart_id=>wwv_flow_imp.id(18925830991154212)
,p_static_id=>'new'
,p_seq=>10
,p_name=>'New'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select process_name, name, value,',
'    case when name = ''CACHESIZE'' then ''gold''',
'        when name = ''Max Memory Used'' then ''green''',
'        when name = ''Current Memory Used'' then ''red''',
'        when name = ''ANON Memory'' then ''yellow''',
'        when name = ''Free Memory'' then ''blue''',
'        when name = ''Bytes To Disk'' then ''pink'' end colors',
'from',
'(',
'    select process_name,''CACHESIZE'' name, cachesize /1024/1024 value, 1 id',
'    from ggadmin.restmon a',
'    where process_name in (select gubun1 from ggadmin.ogg_conf where keya = ''EXTRACT'' and gubun2 = ''CACHEMONITOR'')',
'    and call_time = (select call_time from ggadmin.restmon where process_name = ''DUMMY_BASE_TIMESTAMP'')',
'    union all',
'    select process_name,''Max Memory Used'', maxvmused /1024/1024 value, 2 id',
'    from ggadmin.restmon a',
'    where process_name in (select gubun1 from ggadmin.ogg_conf where keya = ''EXTRACT'' and gubun2 = ''CACHEMONITOR'')',
'    and call_time = (select call_time from ggadmin.restmon where process_name = ''DUMMY_BASE_TIMESTAMP'')',
'    union all',
'    select process_name,''Current Memory Used'', currentvmused /1024/1024 value, 3 id',
'    from ggadmin.restmon a',
'    where process_name in (select gubun1 from ggadmin.ogg_conf where keya = ''EXTRACT'' and gubun2 = ''CACHEMONITOR'')',
'    and call_time = (select call_time from ggadmin.restmon where process_name = ''DUMMY_BASE_TIMESTAMP'')',
'    union all',
'    select process_name,''ANON Memory'', currentmmapanon /1024/1024 value, 4 id',
'    from ggadmin.restmon a',
'    where process_name in (select gubun1 from ggadmin.ogg_conf where keya = ''EXTRACT'' and gubun2 = ''CACHEMONITOR'')',
'    and call_time = (select call_time from ggadmin.restmon where process_name = ''DUMMY_BASE_TIMESTAMP'')',
'    union all',
'    select process_name,''Free Memory'', currentmmaprecycles /1024/1024 value, 5 id',
'    from ggadmin.restmon a',
'    where process_name in (select gubun1 from ggadmin.ogg_conf where keya = ''EXTRACT'' and gubun2 = ''CACHEMONITOR'')',
'    and call_time = (select call_time from ggadmin.restmon where process_name = ''DUMMY_BASE_TIMESTAMP'')',
'    union all',
'    select process_name,''Bytes To Disk'',bytestodisk /1024/1024 value, 6 id',
'    from ggadmin.restmon a',
'    where process_name in (select gubun1 from ggadmin.ogg_conf where keya = ''EXTRACT'' and gubun2 = ''CACHEMONITOR'')',
'    and call_time = (select call_time from ggadmin.restmon where process_name = ''DUMMY_BASE_TIMESTAMP'')',
')',
'order by id',
';'))
,p_series_type=>'bar'
,p_items_value_column_name=>'VALUE'
,p_items_label_column_name=>'NAME'
,p_color=>'&COLORS.'
,p_assigned_to_y2=>'off'
,p_items_label_rendered=>true
