'				  from (incoming_extract_ts - incoming_heartbeat_ts))*60+ extract (second',
'				  from (incoming_extract_ts - incoming_heartbeat_ts)) Extract_Lag ,',
'		   nvl(incoming_routing_path, ''N/A'') Data_Pump ,',
'		   extract (day',
'				  from (COALESCE(incoming_routing_ts,incoming_extract_ts) - incoming_extract_ts))*24*60*60+ extract (hour',
'				  from (COALESCE(incoming_routing_ts,incoming_extract_ts) - incoming_extract_ts))*60*60+ extract (minute',
'				  from (COALESCE(incoming_routing_ts,incoming_extract_ts) - incoming_extract_ts))*60+ extract (second',
'				  from (COALESCE(incoming_routing_ts,incoming_extract_ts) - incoming_extract_ts)) Data_Pump_Read_Lag ,',
'		   incoming_replicat Replicat ,',
'		   extract (day',
'				  from (incoming_replicat_ts - COALESCE(incoming_routing_ts,incoming_extract_ts)))*24*60*60+ extract (hour',
'				  from (incoming_replicat_ts - COALESCE(incoming_routing_ts,incoming_extract_ts)))*60*60+ extract (minute',
'				  from (incoming_replicat_ts - COALESCE(incoming_routing_ts,incoming_extract_ts)))*60+ extract (second',
'				  from (incoming_replicat_ts - COALESCE(incoming_routing_ts,incoming_extract_ts))) Replicat_Read_Lag ,',
'		   extract (day',
'				  from (heartbeat_received_ts - incoming_replicat_ts))*24*60*60+ extract (hour',
'				  from (heartbeat_received_ts - incoming_replicat_ts))*60*60+ extract (minute',
'				  from (heartbeat_received_ts - incoming_replicat_ts))*60+ extract (second',
'				  from (heartbeat_received_ts - incoming_replicat_ts)) Replicat_Apply_Lag ,',
'		   extract (day',
'				  from (heartbeat_received_ts - incoming_heartbeat_ts))*24*60*60+ extract (hour',
'				  from (heartbeat_received_ts - incoming_heartbeat_ts))*60*60+ extract (minute',
'				  from (heartbeat_received_ts - incoming_heartbeat_ts))*60+ extract (second',
'				  from (heartbeat_received_ts - incoming_heartbeat_ts)) Total_Lag',
'	  from c##ogg.gg_heartbeat_history',
'	 order by heartbeat_received_ts desc',
')',
'where rownum <= 100',
'order by source_hb_ts asc',
' ;'))
