'  l_pos         varchar2(32767) := nvl(apex_application.g_x02, ''0'');',
'  l_opts        varchar2(32767) := nvl(apex_application.g_x03, '''');',
'  l_cmd         varchar2(32767) := apex_application.g_x04;',
'  l_response    clob;',
'  l_chunk       pls_integer := 32000;',
'  l_len         pls_integer;',
'  l_header_sent boolean := false;',
'',
'  procedure send_header is',
'  begin',
'    if not l_header_sent then',
'      owa_util.mime_header(''application/json'', false);',
'      owa_util.http_header_close;',
'      l_header_sent := true;',
'    end if;',
'  end;',
'',
'  procedure print_clob(p_clob in clob) is',
'  begin',
'    if p_clob is null then',
'      sys.htp.prn(''{}'');',
'      return;',
'    end if;',
'    l_len := dbms_lob.getlength(p_clob);',
'    if l_len = 0 then',
'      return;',
'    end if;',
'    for i in 1 .. ceil(l_len / l_chunk) loop',
'      sys.htp.prn(dbms_lob.substr(p_clob, l_chunk, ((i - 1) * l_chunk) + 1));',
'    end loop;',
'  end;',
'begin',
'  send_header;',
'  if l_trail is null then',
'    sys.htp.prn(''{"error":"trail parameter required"}'');',
'    return;',
'  end if;',
'  if l_cmd is null then',
'    sys.htp.prn(''{"error":"cmd parameter required"}'');',
'    return;',
'  end if;',
'',
'  l_response := apex_web_service.make_rest_request(',
'    p_url         => ''http://172.28.0.5:8765/api/exec?trail='' || apex_util.url_encode(l_trail) ||',
'                     ''&pos='' || apex_util.url_encode(l_pos) ||',
'                     ''&opts='' || apex_util.url_encode(l_opts) ||',
'                     ''&cmd='' || apex_util.url_encode(l_cmd),',
'    p_http_method => ''GET'');',
'  print_clob(l_response);',
'exception',
'  when others then',
'    send_header;',
'    sys.htp.prn(''{"error":'' || apex_json.stringify(sqlerrm) || ''}'');',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>101260101170003
);
