,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'LO_CLOB        CLOB;',
'LO_CHUNK_SIZE  NUMBER := 4000;',
'BEGIN',
'   SELECT a.res',
'      INTO LO_CLOB  ',
'      FROM reportdetail a',
'   --WHERE EMP_ID = apex_application.g_x01;',
'   --WHERE rownum = 1;',
'   WHERE report = ''&P174_PROCESS.'';',
'',
'   FOR i IN 0 .. FLOOR(LENGTH(LO_CLOB)/LO_CHUNK_SIZE )',
'   LOOP',
'       --SYS.HTP.PRN(SUBSTR(LO_CLOB, i * LO_CHUNK_SIZE + 1, LO_CHUNK_SIZE ));',
'       SYS.HTP.PRN(SUBSTR(replace(LO_CLOB,''","'',chr(13)||chr(10)), i * LO_CHUNK_SIZE + 1, LO_CHUNK_SIZE ));',
'   END LOOP;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>11617873471955201
);
