 p_id=>wwv_flow_imp.id(19046668057408311)
,p_plug_name=>'New'
,p_static_id=>'new'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(141233965818187007009)
,p_plug_display_sequence=>90
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'    l_response varchar2(4000) := '''';',
'	v_sql varchar2(4000) ;',
'',
'	v_base_url varchar2(200) := '''';',
'    v_upper_process varchar2(200) := '''';',
'',
'    v_config varchar2(4000) := '''';',
'    v_tmp varchar2(500) := '''';',
'    v_var_stat varchar2(500) := '''';',
'        	',
'BEGIN',
'',
'	select gubun1 ||'':''||gubun2||gubun3 into v_base_url',
'	from ogg_conf',
'	where keya = ''EXTRACTURL'' ',
'	and keyb = ''ADMIN''',
'	;',
'',
'    select upper(''&P175_PROCESS.'') into v_upper_process from dual;',
'',
'    --insert into tmp values ('' v_upper_process : '' ||v_upper_process,sysdate);',
'    --commit;',
'',
'	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'	l_response := apex_web_service.make_rest_request ',
'	(',
'		p_url                  => v_base_url || ''/extracts/&P175_PROCESS.'', ',
'        --p_url                  => ''http://172.28.0.5:9112/services/v2'' || ''/extracts'', ',
'		p_http_method          => ''GET'', ',
'		--p_transfer_timeout     => 10, ',
'		p_username             => ''oggadmin'', ',
'		p_password             => ''WElcome1234##'',',
'		p_scheme               => ''Basic''',
'	); ',
'',
'	--dbms_output.put_line(''Response Status : '' || apex_web_service.g_status_code);',
'	--dbms_output.put_line(''Response Payload: '' || l_response);',
'	--begin',
'        --execute immediate ''truncate table extracts'';',
'    --end;',
'',
'    delete from configs',
'    where user_id = ''&APP_USER.''',
'    and session_id =''&APP_SESSION.''',
'    and process = ''&P175_PROCESS.''',
'    ;',
'    commit;',
'',
'	begin',
'        execute immediate ''truncate table configs'';',
'    end;',
'    ',
'    insert into configs values (''&APP_USER.'',''&APP_SESSION.'',''&P175_PROCESS.'',l_response,sysdate);',
'    commit;',
'',
