 p_id=>wwv_flow_imp.id(30687934890831086)
,p_plug_name=>'New'
,p_static_id=>'new'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(141233965818187007009)
,p_plug_display_sequence=>90
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'    l_response varchar2(4000) := '''';',
'	v_sql varchar2(4000) ;',
'',
'	v_base_url varchar2(200) := '''';',
'    v_upper_process varchar2(200) := '''';',
'',
'    v_config varchar2(4000) := '''';',
'    v_tmp varchar2(500) := '''';',
'    v_var_stat varchar2(500) := '''';',
'        	',
'BEGIN',
'',
'	select gubun1 ||'':''||gubun2||gubun3 into v_base_url',
'	from ogg_conf',
'	where keya = ''REPLICATURL'' ',
'	and keyb = ''ADMIN''',
'	;',
'',
'    select upper(''&P177_PROCESS.'') into v_upper_process from dual;',
'',
'    --insert into tmp values ('' v_upper_process : '' ||v_upper_process,sysdate);',
'    --commit;',
'',
'	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'	l_response := apex_web_service.make_rest_request ',
'	(',
'		p_url                  => v_base_url || ''/replicats/&P177_PROCESS.'', ',
'        --p_url                  => ''http://172.28.0.5:9112/services/v2'' || ''/extracts'', ',
'		p_http_method          => ''GET'', ',
'		--p_transfer_timeout     => 10, ',
'		p_username             => ''oggadmin'', ',
'		p_password             => ''WElcome1234##'',',
'		p_scheme               => ''Basic''',
'	); ',
'',
'	--dbms_output.put_line(''Response Status : '' || apex_web_service.g_status_code);',
'	--dbms_output.put_line(''Response Payload: '' || l_response);',
'	--begin',
'        --execute immediate ''truncate table extracts'';',
'    --end;',
'',
'    delete from configsr',
'    where user_id = ''&APP_USER.''',
'    and session_id =''&APP_SESSION.''',
'    and process = ''&P177_PROCESS.''',
'    ;',
'    commit;',
'',
'	begin',
'        execute immediate ''truncate table configsr'';',
'    end;',
'',
'    insert into configsr values (''&APP_USER.'',''&APP_SESSION.'',''&P177_PROCESS.'',l_response,sysdate);',
'    commit;',
'',
'    --insert into tmp values ('' l_response : '' ||l_response,sysdate);',
'    --commit;',
'',
'',
'    delete from processconfig',
'    where user_id = ''&APP_USER.''',
'    and session_id = ''&APP_SESSION.''',
'    --and process = ''''''''||v_upper_process||''''''''',
'    and process = ''&P177_PROCESS.''',
'    ;',
'    commit;',
'',
'	begin',
'        execute immediate ''truncate table processconfig'';',
'    end;',
'',
'',
'    --insert into processconfig (user_id,session_id,process,res,stat) values (v(''APP_USER''),v(''APP_SESSION''),v_upper_process,l_response,apex_web_service.g_status_code);',
'    --commit;',
'',
'/*',
'    for i in 0..10 loop',
'        select ''''''$.response.config[''||i||'']'''''' into v_var_stat from dual;',
'        select a.config into v_tmp',
'        from JSON_TABLE(l_response, ',
'            ''$[*]'' COLUMNS (',
'                --config varchar2(4000) PATH ''$.response.config[i]''',
'                config varchar2(4000) PATH v_var_stat',
'                ) ',
'        ) a ;',
'        v_config := v_config || v_tmp;',
'        insert into tmp values (''v_var_stat:'' || v_var_stat,sysdate);',
'        commit;',
