wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(19073444808875925)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'execute'
,p_static_id=>'execute'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'	l_response      CLOB;',
'	v_sql varchar2(4000) := '''' ;',
'	v_base_url varchar2(200) := '''';',
'    v_body varchar2(4000) := '''';',
'    v_start_point varchar2(4000) := '''';',
'    v_upper_process varchar2(200) := '''';',
'    v_description varchar2(4000) := '''';',
'	',
'BEGIN',
'',
'	select gubun1 ||'':''||gubun2||gubun3 into v_base_url',
'	from ogg_conf',
'	where keya = ''EXTRACTURL'' ',
'	and keyb = ''ADMIN''',
'	;',
'',
'',
'    select ''&P177_PROCESS.'' into v_upper_process from dual;',
'',
'    select ''&P177_START_POINT.'' into v_start_point from dual;',
'',
'    select ''"''||replace(''&P177_DESCRIPTION.'',chr(10),''","'')||''"'' into v_description from dual;',
'',
'    insert into tmp values (''v_start_point : ''||v_start_point,sysdate);',
'    commit;',
'',
'',
'    v_body := ''',
'    {',
'        "lines": [',
'            ''||v_description||''',
'        ]',
'    }     ',
'    '';    ',
'',
'',
'    insert into tmp values (''v_description : ''||v_description,sysdate);',
'    commit;',
'    insert into tmp values (''v_body : ''||v_body,sysdate);',
'    commit;',
'',
'	apex_web_service.set_request_headers (p_name_01  => ''Content-Type'', p_value_01 => ''application/json'', p_reset    => TRUE); ',
'',
'	l_response := apex_web_service.make_rest_request ',
'	(',
'		p_url                  => v_base_url || ''/config/files/&P177_PROCESS.''||''.prm'', ',
'		p_http_method          => ''PUT'', ',
'		--p_transfer_timeout     => 10, ',
'        p_body                 => v_body,',
'		p_username             => ''oggadmin'', ',
'		p_password             => ''WElcome1234##'',',
'		p_scheme               => ''Basic''',
'	); ',
'',
'	--dbms_output.put_line(''Response Status : '' || apex_web_service.g_status_code);',
'	--dbms_output.put_line(''Response Payload: '' || l_response);',
'',
'    insert into tmp values (l_response,sysdate);',
'    commit;',
'',
'',
'END;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>11645102178422820
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(19073942231875925)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'FETCH_CLOB_DATA'
,p_static_id=>'fetch-clob-data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'LO_CLOB        CLOB;',
'LO_CHUNK_SIZE  NUMBER := 4000;',
'BEGIN',
'   SELECT a.res',
'      INTO LO_CLOB  ',
'      FROM processconfig a',
'   --WHERE EMP_ID = apex_application.g_x01;',
'   --WHERE rownum = 1;',
'   WHERE process = ''&P177_PROCESS.'';',
'',
'   FOR i IN 0 .. FLOOR(LENGTH(LO_CLOB)/LO_CHUNK_SIZE )',
'   LOOP',
'       --SYS.HTP.PRN(SUBSTR(LO_CLOB, i * LO_CHUNK_SIZE + 1, LO_CHUNK_SIZE ));',
'       SYS.HTP.PRN(SUBSTR(replace(LO_CLOB,''","'',chr(13)||chr(10)), i * LO_CHUNK_SIZE + 1, LO_CHUNK_SIZE ));',
'   END LOOP;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>11645599601422820
);
end;
