wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(10228337573830109)
,p_name=>'AWR Snapshot Coverage'
,p_static_id=>'awr_snapshot_coverage'
,p_region_name=>'AWR Snapshot Coverage'
,p_template=>wwv_flow_imp.id(141234097036331007039)
,p_display_sequence=>15
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody:is-collapsed'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--inline:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH snaps AS (',
'  SELECT ''TARGET'' db_type, snap_id, begin_interval_time, end_interval_time',
'  FROM dba_hist_snapshot',
'  UNION ALL',
'  SELECT ''SOURCE'' db_type, snap_id, begin_interval_time, end_interval_time',
'  FROM dba_hist_snapshot@osrc_23ai_link',
'), filtered AS (',
'  SELECT *',
'  FROM snaps',
'  WHERE :P181_BEGIN_TIME IS NOT NULL',
'    AND :P181_END_TIME IS NOT NULL',
'    AND (:P181_DB_TYPE IS NULL OR db_type = :P181_DB_TYPE)',
'    AND to_char(begin_interval_time,''YYYYMMDDHH24MI'') >= substr(regexp_replace(:P181_BEGIN_TIME,''[^0-9]''),1,12)',
'    AND to_char(end_interval_time,''YYYYMMDDHH24MI'') <= substr(regexp_replace(:P181_END_TIME,''[^0-9]''),1,12)',
')',
'SELECT db_type DB_TYPE,',
'       max(snap_id) SNAP_ID,',
'       count(*) SNAPSHOTS,',
'       min(snap_id) FIRST_SNAP_ID,',
'       max(snap_id) LAST_SNAP_ID,',
'       to_char(min(begin_interval_time),''YYYY-MM-DD HH24:MI'') BEGIN_TIME,',
'       to_char(max(end_interval_time),''YYYY-MM-DD HH24:MI'') END_TIME,',
'       round((cast(max(end_interval_time) as date) - cast(min(begin_interval_time) as date)) * 24, 1) HOURS,',
'       CASE WHEN count(*) >= 2 THEN ''Ready for AWR delta analysis''',
'            ELSE ''Need at least 2 snapshots in range'' END STATUS',
'FROM filtered',
'GROUP BY db_type',
'ORDER BY db_type'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(141234156560532007094)
,p_query_num_rows=>20
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'Select Begin Time and End Time, then click Analyze.'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_query_row_count_max=>500
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
