wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(10228337573829559)
,p_name=>'DB Time Model Breakdown'
,p_static_id=>'db_time_model_breakdown'
,p_region_name=>'DB Time Model Breakdown'
,p_template=>wwv_flow_imp.id(141234097036331007039)
,p_display_sequence=>70
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight:t-Report--inline:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH tm AS (',
'  SELECT ''TARGET'' db_type, t.stat_name, t.value, sn.begin_interval_time, sn.end_interval_time',
'  FROM dba_hist_sys_time_model t',
'  JOIN dba_hist_snapshot sn ON sn.dbid = t.dbid AND sn.instance_number = t.instance_number AND sn.snap_id = t.snap_id',
'  UNION ALL',
'  SELECT ''SOURCE'' db_type, t.stat_name, t.value, sn.begin_interval_time, sn.end_interval_time',
'  FROM dba_hist_sys_time_model@osrc_23ai_link t',
'  JOIN dba_hist_snapshot@osrc_23ai_link sn ON sn.dbid = t.dbid AND sn.instance_number = t.instance_number AND sn.snap_id = t.snap_id',
'), filtered AS (',
'  SELECT *',
'  FROM tm',
'  WHERE :P181_BEGIN_TIME IS NOT NULL',
'    AND :P181_END_TIME IS NOT NULL',
'    AND (:P181_DB_TYPE IS NULL OR db_type = :P181_DB_TYPE)',
'    AND to_char(begin_interval_time,''YYYYMMDDHH24MI'') >= substr(regexp_replace(:P181_BEGIN_TIME,''[^0-9]''),1,12)',
'    AND to_char(end_interval_time,''YYYYMMDDHH24MI'') <= substr(regexp_replace(:P181_END_TIME,''[^0-9]''),1,12)',
'), agg AS (',
'  SELECT db_type, stat_name, max(value) - min(value) micro_delta',
'  FROM filtered',
'  GROUP BY db_type, stat_name',
'), dbtime AS (',
'  SELECT db_type, micro_delta db_time_micro',
'  FROM agg',
'  WHERE stat_name = ''DB time''',
')',
'SELECT a.db_type DB_TYPE,',
'       a.stat_name TIME_MODEL_STAT,',
'       round(a.micro_delta/1000000,2) SECONDS,',
'       round(100 * a.micro_delta / nullif(d.db_time_micro,0), 1) DB_TIME_PCT,',
'       CASE WHEN a.stat_name = ''DB CPU'' THEN ''CPU consumed by SQL/apply work''',
'            WHEN a.stat_name = ''sql execute elapsed time'' THEN ''SQL execution dominates workload''',
'            WHEN a.stat_name = ''PL/SQL execution elapsed time'' THEN ''PL/SQL/monitoring overhead signal''',
'            WHEN a.stat_name = ''parse time elapsed'' THEN ''Parse overhead signal''',
'            WHEN a.stat_name = ''DB time'' THEN ''Total database active time baseline''',
'            ELSE ''Supporting time model stat'' END READOUT',
'FROM agg a',
'JOIN dbtime d ON d.db_type = a.db_type',
'WHERE a.micro_delta > 0',
'  AND a.stat_name IN (''DB time'',''DB CPU'',''sql execute elapsed time'',''PL/SQL execution elapsed time'',''parse time elapsed'',''hard parse elapsed time'',''connection management call elapsed time'')',
'ORDER BY a.db_type, a.micro_delta DESC'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(141234156560532007094)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'Select Begin Time and End Time, then click Analyze.'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_query_row_count_max=>500
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
