wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(10228337573829859)
,p_name=>'GoldenGate DML Mix by Operation'
,p_static_id=>'gg_dml_mix_operation'
,p_region_name=>'GoldenGate DML Mix by Operation'
,p_template=>wwv_flow_imp.id(141234097036331007039)
,p_display_sequence=>40
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight:t-Report--inline:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH awr_sql AS (',
'  SELECT ''TARGET'' db_type, st.sql_id, st.module, st.parsing_schema_name,',
'         st.executions_delta, st.rows_processed_delta, st.elapsed_time_delta,',
'         dbms_lob.substr(tx.sql_text, 1000, 1) sql_text,',
'         sn.begin_interval_time, sn.end_interval_time',
'  FROM dba_hist_sqlstat st',
'  JOIN dba_hist_snapshot sn ON sn.dbid = st.dbid AND sn.instance_number = st.instance_number AND sn.snap_id = st.snap_id',
'  JOIN dba_hist_sqltext tx ON tx.dbid = st.dbid AND tx.sql_id = st.sql_id',
'  UNION ALL',
'  SELECT ''SOURCE'' db_type, st.sql_id, st.module, st.parsing_schema_name,',
'         st.executions_delta, st.rows_processed_delta, st.elapsed_time_delta,',
'         dbms_lob.substr(tx.sql_text, 1000, 1) sql_text,',
'         sn.begin_interval_time, sn.end_interval_time',
'  FROM dba_hist_sqlstat@osrc_23ai_link st',
'  JOIN dba_hist_snapshot@osrc_23ai_link sn ON sn.dbid = st.dbid AND sn.instance_number = st.instance_number AND sn.snap_id = st.snap_id',
'  JOIN dba_hist_sqltext@osrc_23ai_link tx ON tx.dbid = st.dbid AND tx.sql_id = st.sql_id',
'), dml AS (',
'  SELECT db_type,',
'         CASE',
'           WHEN upper(ltrim(sql_text)) LIKE ''INSERT%'' THEN ''INSERT''',
'           WHEN upper(ltrim(sql_text)) LIKE ''UPDATE%'' THEN ''UPDATE''',
'           WHEN upper(ltrim(sql_text)) LIKE ''DELETE%'' THEN ''DELETE''',
'           WHEN upper(ltrim(sql_text)) LIKE ''MERGE%'' THEN ''MERGE''',
'           ELSE ''DML''',
'         END operation,',
'         executions_delta,',
'         rows_processed_delta,',
'         elapsed_time_delta',
'  FROM awr_sql',
'  WHERE :P181_BEGIN_TIME IS NOT NULL',
'    AND :P181_END_TIME IS NOT NULL',
'    AND (:P181_DB_TYPE IS NULL OR db_type = :P181_DB_TYPE)',
'    AND to_char(begin_interval_time,''YYYYMMDDHH24MI'') >= substr(regexp_replace(:P181_BEGIN_TIME,''[^0-9]''),1,12)',
'    AND to_char(end_interval_time,''YYYYMMDDHH24MI'') <= substr(regexp_replace(:P181_END_TIME,''[^0-9]''),1,12)',
'    AND executions_delta > 0',
'    AND rows_processed_delta > 0',
'    AND regexp_like(upper(ltrim(sql_text)), ''^(INSERT|UPDATE|DELETE|MERGE)'')',
'    AND (upper(nvl(module,''-'')) LIKE ''%OGG%'' OR upper(nvl(parsing_schema_name,''-'')) IN (''GGADMIN'',''C##OGG'') OR upper(sql_text) LIKE ''%"SOE"%'')',
')',
'SELECT db_type DB_TYPE,',
'       operation OPERATION,',
'       sum(executions_delta) EXECS,',
'       sum(rows_processed_delta) ROWS_PROCESSED,',
'       round(sum(rows_processed_delta) / nullif(sum(executions_delta),0), 2) ROWS_PER_EXEC,',
'       round(100 * sum(rows_processed_delta) / nullif(sum(sum(rows_processed_delta)) over (partition by db_type),0), 1) ROW_MIX_PCT,',
'       round(sum(elapsed_time_delta)/1000000, 2) ELAPSED_SEC,',
'       CASE WHEN sum(rows_processed_delta) / nullif(sum(executions_delta),0) >= 100 THEN ''Batched''',
'            WHEN sum(rows_processed_delta) / nullif(sum(executions_delta),0) >= 10 THEN ''Array DML''',
'            ELSE ''Single-row leaning'' END APPLY_PATTERN',
'FROM dml',
'GROUP BY db_type, operation',
'ORDER BY db_type, sum(rows_processed_delta) DESC'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(141234156560532007094)
,p_query_num_rows=>50
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'Select Begin Time and End Time, then click Analyze.'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_query_row_count_max=>500
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'Y'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
