wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(10228337573829659)
,p_name=>'Top Wait Events in AWR Window'
,p_static_id=>'top_wait_events_awr'
,p_region_name=>'Top Wait Events in AWR Window'
,p_template=>wwv_flow_imp.id(141234097036331007039)
,p_display_sequence=>60
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight:t-Report--inline:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH events AS (',
'  SELECT ''TARGET'' db_type, se.event_name, se.wait_class, se.total_waits, se.time_waited_micro,',
'         sn.begin_interval_time, sn.end_interval_time',
'  FROM dba_hist_system_event se',
'  JOIN dba_hist_snapshot sn ON sn.dbid = se.dbid AND sn.instance_number = se.instance_number AND sn.snap_id = se.snap_id',
'  UNION ALL',
'  SELECT ''SOURCE'' db_type, se.event_name, se.wait_class, se.total_waits, se.time_waited_micro,',
'         sn.begin_interval_time, sn.end_interval_time',
'  FROM dba_hist_system_event@osrc_23ai_link se',
'  JOIN dba_hist_snapshot@osrc_23ai_link sn ON sn.dbid = se.dbid AND sn.instance_number = se.instance_number AND sn.snap_id = se.snap_id',
'), filtered AS (',
'  SELECT *',
'  FROM events',
'  WHERE wait_class <> ''Idle''',
'    AND :P181_BEGIN_TIME IS NOT NULL',
'    AND :P181_END_TIME IS NOT NULL',
'    AND (:P181_DB_TYPE IS NULL OR db_type = :P181_DB_TYPE)',
'    AND to_char(begin_interval_time,''YYYYMMDDHH24MI'') >= substr(regexp_replace(:P181_BEGIN_TIME,''[^0-9]''),1,12)',
'    AND to_char(end_interval_time,''YYYYMMDDHH24MI'') <= substr(regexp_replace(:P181_END_TIME,''[^0-9]''),1,12)',
'), agg AS (',
'  SELECT db_type, event_name, wait_class,',
'         max(total_waits) - min(total_waits) waits,',
'         (max(time_waited_micro) - min(time_waited_micro)) / 1000000 time_waited_sec',
'  FROM filtered',
'  GROUP BY db_type, event_name, wait_class',
')',
'SELECT db_type DB_TYPE,',
'       event_name WAIT_EVENT,',
'       wait_class WAIT_CLASS,',
'       waits WAITS,',
'       round(time_waited_sec,2) TIME_WAITED_SEC,',
'       round(time_waited_sec / nullif(waits,0) * 1000, 3) AVG_WAIT_MS,',
'       CASE WHEN wait_class = ''Commit'' THEN ''Commit latency can limit Replicat throughput''',
'            WHEN wait_class = ''User I/O'' THEN ''Storage/read path can limit apply or source workload''',
'            WHEN wait_class = ''Concurrency'' THEN ''Lock/latch contention signal''',
'            WHEN wait_class = ''Network'' THEN ''Network path signal''',
'            ELSE ''Review if this dominates DB time'' END GG_RELEVANCE',
'FROM agg',
'WHERE waits > 0 OR time_waited_sec > 0',
'ORDER BY time_waited_sec DESC',
'FETCH FIRST 30 ROWS ONLY'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(141234156560532007094)
,p_query_num_rows=>20
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'Select Begin Time and End Time, then click Analyze.'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_query_row_count_max=>500
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
