 p_id=>wwv_flow_imp.id(669258873912980)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'RUN_DB_HEALTH_AJAX'
,p_static_id=>'run-db-health-ajax'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_db_type varchar2(10) := upper(trim(apex_application.g_x01));',
'  l_html clob;',
'  l_pos pls_integer := 1;',
'  l_len pls_integer;',
'begin',
'  if l_db_type not in (''SOURCE'', ''TARGET'') then',
'    raise_application_error(-20001, ''Invalid database type'');',
'  end if;',
'',
'  l_html := to_clob(''<style>',
'.ogg-db-health-md{font-size:14px;line-height:1.45;max-width:100%;overflow-x:auto;color:#202833;}',
'.ogg-db-health-md h1{font-size:24px;margin:0 0 12px 0;}',
'.ogg-db-health-md h2{font-size:18px;margin:24px 0 8px 0;border-bottom:1px solid #d7dee8;padding-bottom:4px;}',
'.ogg-db-health-md table{border-collapse:collapse;width:max-content;min-width:680px;margin:8px 0 18px 0;}',
'.ogg-db-health-md th,.ogg-db-health-md td{border:1px solid #d7dee8;padding:6px 8px;text-align:left;vertical-align:top;white-space:nowrap;}',
'.ogg-db-health-md th{background:#f5f7fb;font-weight:600;}',
'.ogg-db-health-md blockquote{border-left:4px solid #8aa4c8;margin:12px 0;padding:8px 12px;background:#f7f9fc;color:#3b4552;}',
'.ogg-db-health-md code{background:#eef2f7;padding:1px 4px;border-radius:3px;}',
'</style><div class="ogg-db-health-md" data-render-db="'' || l_db_type || ''">'');',
'  begin',
'    declare l_body clob; begin execute immediate ''begin :x := ggadmin.ogg_db_health_html(:p); end;'' using out l_body, in l_db_type; l_html := l_html || l_body || to_clob(''</div>''); end;',
'  exception',
'    when others then',
'      l_html := l_html || to_clob(''<div class="t-Alert t-Alert--warning"><div class="t-Alert-body">Install the optional DB health supporting function to render this report. Details: '') || apex_escape.html(sqlerrm) || to_clob(''</div></div></div>'');',
'  end;',
'',
'  l_len := dbms_lob.getlength(l_html);',
'  while l_pos <= l_len loop',
'    sys.htp.prn(dbms_lob.substr(l_html, 30000, l_pos));',
'    l_pos := l_pos + 30000;',
'  end loop;',
'exception',
'  when others then',
'    sys.htp.p(''<div class="t-Alert t-Alert--danger"><div class="t-Alert-body">DB Health Check failed: ''',
'      || apex_escape.html(sqlerrm) || ''</div></div>'');',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>42076
);
end;
