'.sq-dot{width:12px;height:12px;border-radius:50%;display:inline-block}.sq-dr{background:#ff5f56}.sq-dy{background:#ffbd2e}.sq-dg{background:#27c93f}',
'html #sq-title{color:#c9d1d9;font-weight:bold}.sq-chip{padding:3px 8px;border:1px solid #30363d;border-radius:4px;color:#8b949e;font-size:11px}',
'html #sq-tabs{display:flex;gap:6px;flex-wrap:wrap;align-items:center}',
'.sq-tab{padding:3px 12px;border-radius:4px;font-size:12px;font-weight:bold;cursor:pointer;border:1px solid #30363d;background:#0d1117;color:#8b949e;font-family:''Courier New'',Courier,monospace}',
'.sq-tab:hover{border-color:#58a6ff;color:#58a6ff}.sq-tab.active-target{background:#1a2d1a;border-color:#3fb950;color:#3fb950}.sq-tab.active-source{background:#0c2d6b;border-color:#58a6ff;color:#79c0ff}',
'.sq-tab.unsupported{color:#6e7681;border-color:#30363d;background:#111820}.sq-tab.active-unsupported{background:#2a2111;border-color:#d29922;color:#d29922}',
'html #sq-led{width:8px;height:8px;border-radius:50%;background:#3fb950;flex-shrink:0;box-shadow:0 0 9px rgba(63,185,80,.45)}',
'html #sq-out{flex:1;overflow-y:auto;padding:12px 16px;color:#c9d1d9;line-height:1.55;word-break:break-word}',
'html #sq-in-row{display:flex;align-items:center;padding:8px 14px;flex-shrink:0;border-top:1px solid #21262d;background:#0d1117}',
