'html #sq-cmd{flex:1;background:transparent;border:none;color:#c9d1d9;font-family:''Courier New'',Courier,monospace;font-size:13px;outline:none;caret-color:#e3a832}',
'html #sq-spinner{color:#8b949e;font-size:12px;margin-left:8px;display:none}',
'.sq-line{margin:0 0 6px 0;white-space:pre-wrap}.sq-user{color:#e3a832}.sq-server{margin:0 0 12px 0}',
'.sq-muted{color:#8b949e}.sq-null{color:#8b949e;font-style:italic}.sq-title{font-weight:bold;color:#79c0ff;margin:8px 0}',
'.sq-result{border:1px solid #30363d;border-radius:6px;background:#0b1118;margin:8px 0 14px 0;overflow:hidden}',
'.sq-result-head{display:flex;gap:8px;align-items:center;background:#161b22;border-bottom:1px solid #30363d;padding:5px 8px;color:#8b949e;font-size:12px}',
'.sq-result-body{overflow-x:auto;max-width:100%;padding:8px 10px}',
'.sq-result-body .sq-server{margin:0}.sq-result-body::-webkit-scrollbar{height:10px}.sq-result-body::-webkit-scrollbar-thumb{background:#30363d;border-radius:6px}',
'.sq-msg{border:1px solid #30363d;border-radius:5px;padding:8px 10px;margin:8px 0;background:#111820}.sq-ok{border-color:#2ea043}.sq-warn{border-color:#d29922}.sq-err{border-color:#f85149}',
'.sq-table{border-collapse:collapse;width:max-content;min-width:520px;margin:8px 0 6px 0;color:#c9d1d9}',
