'.sq-table th{background:#161b22;color:#79c0ff}.sq-table td{background:#0d1117}',
'.sq-table code{color:#ffa657}.sq-count,.sq-elapsed,.sq-note{color:#8b949e;font-size:12px;margin:6px 0}',
'.sq-badge{display:inline-block;border:1px solid #30363d;border-radius:4px;padding:1px 6px;color:#8b949e}.sq-info{border-color:#1f6feb;color:#79c0ff}',
'.sq-help table{border-collapse:collapse;margin-top:8px}.sq-help th,.sq-help td{border:1px solid #30363d;padding:5px 8px}.sq-help code{color:#ffa657} @media (max-width:720px){#sq-bar{flex-wrap:wrap}.sq-chip{display:none}.sq-table th,.sq-table td{white'
||'-space:normal}}',
'</style>',
'',
'<div id="sq-wrap">',
'  <div id="sq-bar">',
'    <span class="sq-dot sq-dr"></span><span class="sq-dot sq-dy"></span><span class="sq-dot sq-dg"></span>',
'    <span id="sq-title">Oracle SQLPlus Client</span>',
'    <span id="sq-tabs"><button type="button" class="sq-tab active-target">trg</button><button type="button" class="sq-tab">src2</button></span>',
'    <span id="sq-context" class="sq-chip">DB Connections</span>',
'    <span class="sq-chip">read-only guarded</span>',
'    <span style="flex:1"></span>',
'    <span id="sq-led"></span>',
'  </div>',
'  <div id="sq-out"></div>',
'  <div id="sq-in-row">',
'    <span id="sq-prompt">SQL&gt;&nbsp;</span>',
'    <input id="sq-cmd" type="text" autocomplete="off" spellcheck="false">',
'    <span id="sq-spinner">working...</span>',
'  </div>',
'</div>',
'',
'<script>',
'(function () {',
'  var state = { hist: [], hidx: -1, busy: false };',
'  var out = document.getElementById(''sq-out'');',
'  var cmd = document.getElementById(''sq-cmd'');',
'  var spn = document.getElementById(''sq-spinner'');',
'  var prompt = document.getElementById(''sq-prompt'');',
'  var ctx = document.getElementById(''sq-context'');',
'  var tabs = document.getElementById(''sq-tabs'');',
'  state.dbAlias = ''trg'';',
'  state.buffers = {};',
'  state.welcomed = {};',
'',
'  state.connections = [',
'    { alias: ''trg'', role: ''TARGET'', label: ''DB Connections: trg'', route: ''LOCAL'' },',
'    { alias: ''src2'', role: ''SOURCE'', label: ''DB Connections: src2'', route: ''REMOTE'' }',
'  ];',
'',
'  function esc(text) {',
'    return String(text == null ? '''' : text)',
'      .replace(/&/g, ''&amp;'')',
'      .replace(/</g, ''&lt;'')',
'      .replace(/>/g, ''&gt;'')',
'      .replace(/"/g, ''&quot;'')',
'      .replace(/''/g, ''&#39;'');',
'  }',
'',
'  function append(html, cls) {',
'    var d = document.createElement(''div'');',
'    d.className = cls || ''sq-server'';',
'    d.innerHTML = html;',
'    out.appendChild(d);',
'    out.scrollTop = out.scrollHeight;',
'    saveBuffer();',
'  }',
'',
'  function appendText(text, cls) {',
'    append(''<div class="sq-line">'' + esc(text) + ''</div>'', cls);',
'  }',
'',
'  function stamp() {',
'    var d = new Date();',
'    function pad(n) { return String(n).padStart(2, ''0''); }',
'    return d.getFullYear() + ''-'' + pad(d.getMonth() + 1) + ''-'' + pad(d.getDate()) + '' '' +',
'      pad(d.getHours()) + '':'' + pad(d.getMinutes()) + '':'' + pad(d.getSeconds());',
'  }',
'',
'  function appendResult(label, html) {',
'    var wrap = document.createElement(''div'');',
'    wrap.className = ''sq-result'';',
'    wrap.innerHTML = ''<div class="sq-result-body"></div>'';',
'    wrap.querySelector(''.sq-result-body'').innerHTML = html || ''<span class="sq-muted">No output.</span>'';',
'    out.appendChild(wrap);',
'    out.scrollTop = out.scrollHeight;',
'    saveBuffer();',
'  }',
'',
'  function saveBuffer(alias) {',
'    var key = alias || state.dbAlias;',
'    if (key) {',
'      state.buffers[key] = out.innerHTML;',
'    }',
'  }',
'',
'  function restoreBuffer(alias) {',
'    out.innerHTML = state.buffers[alias] || '''';',
'    out.scrollTop = out.scrollHeight;',
'  }',
'',
'  function currentConn() {',
'    for (var i = 0; i < state.connections.length; i += 1) {',
'      if (state.connections[i].alias === state.dbAlias) {',
'        return state.connections[i];',
'      }',
'    }',
'    return state.connections[0];',
'  }',
'',
'  function renderTabs() {',
'    tabs.innerHTML = '''';',
'    state.connections.forEach(function (conn) {',
'      var b = document.createElement(''button'');',
'      b.type = ''button'';',
'      b.className = ''sq-tab'';',
'      if (conn.route === ''UNSUPPORTED'') {',
'        b.className += conn.alias === state.dbAlias ? '' active-unsupported'' : '' unsupported'';',
'      } else if (conn.alias === state.dbAlias) {',
'        b.className += conn.route === ''REMOTE'' ? '' active-source'' : '' active-target'';',
'      }',
'      b.textContent = conn.alias;',
'      b.title = conn.label || conn.alias;',
'      b.addEventListener(''click'', function () { setDb(conn.alias); });',
'      tabs.appendChild(b);',
'    });',
'  }',
'',
'  function welcome() {',
'    var conn = currentConn();',
'    if (state.welcomed[state.dbAlias]) {',
'      return;',
'    }',
'    state.welcomed[state.dbAlias] = true;',
'    appendText(''DB connection alias selected: '' + conn.alias);',
'    appendText(''Type HELP for commands. SELECT, WITH, DESC, and SHOW are supported.'');',
'    appendText(''Alias tabs keep their own terminal output. Returning to this alias restores this screen.'', ''sq-muted'');',
'    appendText(''Wide result sets scroll inside each result block.'', ''sq-muted'');',
'    appendText(''DDL/DML/PLSQL execution and shell commands are blocked in this APEX console.'', ''sq-muted'');',
'  }',
'',
'  function refreshContext() {',
'    var conn = currentConn();',
'    ctx.textContent = conn.label || conn.alias;',
'    apex.server.process(''SQLPLUS_CONTEXT'', { x01: state.dbAlias }, {',
'      dataType: ''text'',',
'      success: function (data) {',
'        if (data && String(data).trim()) {',
'          ctx.textContent = String(data).trim();',
'        }',
'      }',
'    });',
'  }',
'',
'  function setDb(type) {',
'    saveBuffer();',
'    state.dbAlias = type || (state.connections[0] && state.connections[0].alias) || ''trg'';',
'    prompt.innerHTML = ''SQL '' + esc(state.dbAlias).toUpperCase() + ''&gt;&nbsp;'';',
'    renderTabs();',
'    refreshContext();',
'    restoreBuffer(state.dbAlias);',
'    welcome();',
'    cmd.focus();',
'  }',
'',
'  function setBusy(value) {',
'    state.busy = value;',
'    spn.style.display = value ? ''inline'' : ''none'';',
'    cmd.disabled = value;',
'    if (!value) {',
'      cmd.focus();',
'    }',
'  }',
'',
'  function run(raw) {',
'    var text = String(raw || '''').trim();',
'    if (!text || state.busy) {',
'      return;',
'    }',
'',
'    state.hist.push(text);',
'    state.hidx = state.hist.length;',
'    var runAlias = state.dbAlias;',
'    var runLabel = runAlias;',
'    append(''<span class="sq-user">SQL '' + esc(runLabel) + ''&gt;</span> '' + esc(text), ''sq-line'');',
'    cmd.value = '''';',
'',
'    if (text.toLowerCase() === ''clear'') {',
'      out.innerHTML = '''';',
'      state.buffers[state.dbAlias] = '''';',
'      state.welcomed[state.dbAlias] = false;',
'      welcome();',
'      return;',
'    }',
'',
'    setBusy(true);',
'    apex.server.process(''SQLPLUS_RUN'', { x01: text, x02: runAlias }, {',
'      dataType: ''html'',',
'      success: function (data) {',
'        appendResult(runLabel, data);',
'      },',
'      error: function (jqXHR, textStatus, errorThrown) {',
'        var msg = errorThrown || textStatus || ''Ajax request failed'';',
'        append(''<div class="sq-msg sq-err"><b>Request failed</b><div>'' + esc(msg) + ''</div></div>'');',
'      },',
'      complete: function () {',
'        setBusy(false);',
'      }',
'    });',
'  }',
'',
'  cmd.addEventListener(''keydown'', function (event) {',
'    if (event.key === ''Enter'') {',
'      event.preventDefault();',
'      run(cmd.value);',
'    } else if (event.key === ''ArrowUp'') {',
'      event.preventDefault();',
'      if (state.hist.length) {',
'        state.hidx = Math.max(0, state.hidx - 1);',
'        cmd.value = state.hist[state.hidx] || '''';',
'        setTimeout(function () { cmd.setSelectionRange(cmd.value.length, cmd.value.length); }, 0);',
'      }',
'    } else if (event.key === ''ArrowDown'') {',
'      event.preventDefault();',
'      if (state.hist.length) {',
'        state.hidx = Math.min(state.hist.length, state.hidx + 1);',
'        cmd.value = state.hist[state.hidx] || '''';',
'      }',
'    }',
'  });',
'',
'  function loadConnections() {',
'    apex.server.process(''SQLPLUS_CONNECTIONS'', {}, {',
'      dataType: ''json'',',
'      success: function (data) {',
'        var nextAlias = state.dbAlias;',
'        if (Array.isArray(data) && data.length) {',
'          state.connections = data;',
'          nextAlias = data[0].alias;',
'        }',
'        setDb(nextAlias);',
'      },',
'      error: function () {',
'        setDb(state.dbAlias);',
'      }',
'    });',
'  }',
'',
'  setDb(state.dbAlias);',
'  loadConnections();',
'})();',
'</script>',
''))
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1066583201102161)
,p_process_sequence=>15
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SQLPLUS_CONNECTIONS'
,p_static_id=>'sqlplus-connections'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'declare',
'  l_json clob;',
'  l_pos pls_integer := 1;',
'  l_len pls_integer;',
'begin',
'  begin',
'    execute immediate ''begin :x := ggadmin.sqlplus_client_pkg.connections_json; end;'' using out l_json;',
'  exception',
'    when others then',
'      l_json := ''[{"alias":"trg","label":"DB Connections: trg","route":"LOCAL"},{"alias":"src2","label":"DB Connections: src2","route":"REMOTE"}]'';',
'  end;',
'  l_len := dbms_lob.getlength(l_json);',
'  while l_pos <= l_len loop',
'    sys.htp.prn(dbms_lob.substr(l_json, 30000, l_pos));',
'    l_pos := l_pos + 30000;',
'  end loop;',
'exception',
'  when others then',
'    sys.htp.prn(''[{"alias":"trg","label":"DB Connections: trg","route":"LOCAL"},{"alias":"src2","label":"DB Connections: src2","route":"REMOTE"}]'');',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>42076
);
