,p_escape_on_http_output=>'N'
,p_plug_template=>wwv_flow_imp.id(141234097036331007039)
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_html clob := empty_clob();',
'  l_pos pls_integer := 1;',
'  l_len pls_integer;',
'  l_tables number := 0;',
'  l_columns number := 0;',
'  l_reviews number := 0;',
'  l_workers number := 8;',
'  l_chunk_method varchar2(100) := ''Primary-key range chunks'';',
'  l_chunk_size number := 100000;',
'  l_commit_size number := 5000;',
'  l_marker_type varchar2(100) := ''MySQL binlog file/position and GTID set'';',
'  l_source_type varchar2(30) := upper(nvl(:P194_SOURCE_TYPE, ''MYSQL''));',
'  l_target_type varchar2(30) := upper(nvl(:P194_TARGET_TYPE, ''HEATWAVE''));',
'  l_source_conn varchar2(128) := nvl(:P194_SOURCE_CONN, ''demo_mysql / mysql:3306'');',
'  l_target_conn varchar2(128) := nvl(:P194_TARGET_CONN, ''demo_myheat / myheat:3306'');',
'  l_source_schema varchar2(128) := nvl(:P194_SOURCE_SCHEMA, ''game'');',
'  l_target_schema varchar2(128) := nvl(:P194_TARGET_SCHEMA, ''game_hw'');',
'  l_profile_label varchar2(80);',
'  l_pair_ready varchar2(1) := ''N'';',
'  l_plan_saved varchar2(1) := case when upper(nvl(v(''REQUEST''), ''~'')) = ''SAVE_MIG_PLAN'' then ''Y'' else ''N'' end;',
'  procedure add(p_text varchar2) is',
'  begin',
'    dbms_lob.writeappend(l_html, length(p_text), p_text);',
'  end;',
'  function h(p_text varchar2) return varchar2 is',
'  begin',
'    return apex_escape.html(nvl(p_text, ''''));',
'  end;',
'  function mapping_select(p_key varchar2, p_value varchar2) return varchar2 is',
'  begin',
'    return ''<select class="mh-select mh-map" data-map-key="'' || h(p_key) || ''"><option selected>'' || h(p_value) || ''</option><option>Manual review</option><option>Keep source shape</option><option>Custom target type</option></select>'';',
'  end;',
'  function selected_attr(p_value varchar2, p_current varchar2) return varchar2 is',
'  begin',
'    if upper(p_value) = upper(nvl(p_current, p_value)) then',
'      return '' selected'';',
'    end if;',
'    return null;',
'  end;',
'  function option_tag(p_value varchar2, p_label varchar2, p_current varchar2) return varchar2 is',
'  begin',
'    return ''<option value="'' || h(p_value) || ''"'' || selected_attr(p_value, p_current) || ''>'' || h(p_label) || ''</option>'';',
'  end;',
'begin',
'  dbms_lob.createtemporary(l_html, true);',
'  if l_source_type not in (''MYSQL'', ''ORACLE'', ''POSTGRESQL'', ''DB2'') then',
'    l_source_type := ''MYSQL'';',
'  end if;',
'  if l_target_type not in (''HEATWAVE'', ''ORACLE'', ''POSTGRESQL'') then',
'    l_target_type := ''HEATWAVE'';',
'  end if;',
'  l_pair_ready := case when l_source_type = ''MYSQL'' and l_target_type = ''HEATWAVE'' then ''Y'' else ''N'' end;',
'  l_profile_label := l_source_type || ''_TO_'' || l_target_type;',
'  begin',
'    select count(distinct source_table), count(*), nvl(sum(case when upper(nvl(risk_level, ''REVIEW'')) <> ''SAFE'' then 1 else 0 end), 0)',
'      into l_tables, l_columns, l_reviews',
'      from ggadmin.mig_demo_column',
'     where profile_code = ''MYSQL_HW_LAB'';',
'    select default_workers, chunk_method, chunk_size, commit_size, marker_type',
'      into l_workers, l_chunk_method, l_chunk_size, l_commit_size, l_marker_type',
'      from ggadmin.mig_load_strategy',
'     where profile_code = ''MYSQL_HW_LAB'';',
'    if regexp_like(nvl(:P194_WORKERS, ''''), ''^[0-9]+$'') then',
'      l_workers := greatest(1, least(64, to_number(:P194_WORKERS)));',
'    end if;',
'    if :P194_CHUNK_METHOD is not null then',
'      l_chunk_method := :P194_CHUNK_METHOD;',
'    end if;',
'    if regexp_like(nvl(:P194_COMMIT_SIZE, ''''), ''^[0-9]+$'') then',
'      l_commit_size := greatest(1, to_number(:P194_COMMIT_SIZE));',
'    end if;',
'    l_marker_type := case l_source_type',
'      when ''ORACLE'' then ''Oracle SCN''',
'      when ''POSTGRESQL'' then ''PostgreSQL LSN''',
'      when ''DB2'' then ''DB2 log position marker''',
'      else l_marker_type',
'    end;',
'  exception',
'    when others then',
'      add(''<div class="t-Alert t-Alert--warning"><div class="t-Alert-body">Install Supporting Objects to seed the MySQL to HeatWave migration metadata. Details: '' || apex_escape.html(sqlerrm) || ''</div></div>'');',
'      l_len := dbms_lob.getlength(l_html);',
'      while l_pos <= l_len loop',
'        sys.htp.prn(dbms_lob.substr(l_html, 30000, l_pos));',
'        l_pos := l_pos + 30000;',
'      end loop;',
'      return;',
'  end;',
'  add(''<style>.mh-shell{color:#20242b}.mh-hero,.mh-panel{border:1px solid #d9e0e8;border-radius:8px;background:#fff;padding:16px;margin-bottom:12px}.mh-hero h1{font-size:24px;margin:0 0 6px}.mh-hero p{margin:0;color:#5c6675}.mh-stepper{display:grid;g'
||'rid-template-columns:repeat(5,minmax(0,1fr));gap:8px;margin:12px 0}.mh-step{border:1px solid #d9e0e8;background:#f7f9fb;border-radius:8px;padding:10px}.mh-step b{display:block}.mh-step span{display:block;color:#657083;font-size:12px}.mh-active{border'
