wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(10228337575598132)
,p_plug_name=>'GoldenGate AI Assistant'
,p_static_id=>'goldengate-ai-assistant'
,p_plug_template=>wwv_flow_imp.id(141234128251200007065)
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<style>',
'#gg-chat-box{min-height:350px;max-height:500px;overflow-y:auto;background:#f8f9fa;padding:15px;border-radius:8px;margin-bottom:15px;}',
'.gg-user{background:#007bff;color:white;padding:8px 12px;border-radius:12px 12px 2px 12px;display:inline-block;max-width:70%;margin-bottom:10px;float:right;clear:both;}',
'.gg-ai{background:white;border:1px solid #ddd;padding:8px 12px;border-radius:12px 12px 12px 2px;display:inline-block;max-width:80%;margin-bottom:10px;float:left;clear:both;}',
'.gg-wrap{overflow:hidden;margin-bottom:5px;}',
'.gg-err{background:#fff3cd;border:1px solid #ffc107;padding:8px 12px;border-radius:8px;margin-bottom:10px;float:left;clear:both;font-size:0.85em;}',
'',
unistr('/* \C785\B825\CC3D \B192\C774\B97C \B531 \BC18\C808(44px)\B85C \C870\C808\D588\C2B5\B2C8\B2E4 */'),
'.input-group-custom { display: flex; width: 100%; align-items: stretch; }',
'#gg-q { flex: 1; height: 44px; resize: none; padding: 10px; border: 1px solid #ccc; overflow-y: auto; }',
'#gg-btn { width: 100px; }',
'</style>',
'',
'<div id="gg-chat-box"></div>',
'',
'<div class="input-group-custom">',
unistr('  <textarea id="gg-q" class="form-control" placeholder="GoldenGate\C5D0 \B300\D574 \C9C8\BB38\D558\C138\C694..." style="border-radius:15px 0 0 15px;"></textarea>'),
unistr('  <button class="btn btn-primary" id="gg-btn" onclick="askGG()" style="border-radius:0 15px 15px 0;">\C9C8\BB38\D558\AE30</button>'),
'</div>',
'',
'<script>',
'function askGG(){',
'  var q=document.getElementById("gg-q").value.trim();',
'  if(!q)return;',
'  var box=document.getElementById("gg-chat-box");',
'  var btn=document.getElementById("gg-btn");',
'  btn.disabled=true;',
'  ',
'  var displayQ = q.replace(/\n/g, "<br>");',
'  box.innerHTML+=''<div class="gg-wrap"><div class="gg-user">''+displayQ+''</div></div>'';',
'  ',
'  document.getElementById("gg-q").value="";',
'  var tid="gg-t-"+(new Date().getTime());',
unistr('  box.innerHTML+=''<div class="gg-wrap" id="''+tid+''"><div class="gg-ai"><em>\C751\B2F5 \C911...</em></div></div>'';'),
'  box.scrollTop=box.scrollHeight;',
'  ',
'  apex.server.process("GENAI_CHAT_101",{x01:q},{',
'    dataType:"text",',
'    success:function(d){',
'      if(document.getElementById(tid)) document.getElementById(tid).remove();',
'      box.innerHTML+=''<div class="gg-wrap"><div class="gg-ai">''+',
unistr('        (d||"(\BE48 \C751\B2F5)").replace(/\005Cn/g,"<br>")+''</div></div>'';'),
'      box.scrollTop=box.scrollHeight;',
'      btn.disabled=false;',
'    },',
'    error:function(xhr,stat,err){',
'      var msg=(xhr.responseText||err||stat||"unknown");',
'      var targetNode = document.getElementById(tid);',
'      if(targetNode) {',
unistr('        targetNode.innerHTML=''<div class="gg-err">\C624\B958 (HTTP ''+xhr.status+''): ''+msg+''</div>'';'),
'      }',
'      btn.disabled=false;',
'    }',
'  });',
'}',
'',
unistr('// Enter\B294 \C804\C1A1, Shift+Enter\B294 \C904\BC14\AFC8'),
'document.getElementById("gg-q").addEventListener("keydown", function(e){',
'  if(e.key === "Enter" && !e.shiftKey){',
'    e.preventDefault();',
'    askGG();',
'  }',
'});',
'</script>'))
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(10228337575599124)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GENAI_CHAT_101'
,p_static_id=>'genai-chat-101'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_question VARCHAR2(4000) := apex_application.g_x01;',
'  l_context  VARCHAR2(32767);',
'  l_log_ctx  VARCHAR2(8000);',
'  l_cmd_ctx  VARCHAR2(4000);',
'  l_ext_json CLOB;',
'  l_rep_json CLOB;',
'  l_bd_json  CLOB;',
'  l_prompt   CLOB;',
'  l_resp     CLOB;',
'  l_system   CLOB;',
'  l_proc_nm  VARCHAR2(10);',
'  l_cmd_type VARCHAR2(20);',
'  l_res_type VARCHAR2(20);',
'  l_ogg_host VARCHAR2(100);',
'  l_auth     VARCHAR2(100) := ''b2dnYWRtaW46V0VsY29tZTEyMzQjIw=='';',
'',
'  FUNCTION http_get(p_url VARCHAR2, p_auth VARCHAR2 DEFAULT NULL) RETURN CLOB IS',
'    l_req  UTL_HTTP.REQ;',
'    l_resp UTL_HTTP.RESP;',
'    l_buf  VARCHAR2(32767);',
'    l_body CLOB;',
'  BEGIN',
'    DBMS_LOB.CREATETEMPORARY(l_body, TRUE);',
'    l_req := UTL_HTTP.BEGIN_REQUEST(url => p_url, method => ''GET'');',
'    IF p_auth IS NOT NULL THEN',
'      UTL_HTTP.SET_HEADER(l_req, ''Authorization'', ''Basic '' || p_auth);',
'    END IF;',
'    UTL_HTTP.SET_HEADER(l_req, ''Accept'', ''*/*'');',
'    l_resp := UTL_HTTP.GET_RESPONSE(l_req);',
'    BEGIN',
'      LOOP UTL_HTTP.READ_TEXT(l_resp, l_buf, 32767);',
'        DBMS_LOB.WRITEAPPEND(l_body, LENGTH(l_buf), l_buf);',
'      END LOOP;',
'    EXCEPTION WHEN UTL_HTTP.END_OF_BODY THEN UTL_HTTP.END_RESPONSE(l_resp);',
'    END;',
'    RETURN l_body;',
'  EXCEPTION WHEN OTHERS THEN RETURN TO_CLOB(''[HTTP_ERR]'' || SQLERRM);',
'  END http_get;',
'',
'  FUNCTION http_patch(p_url VARCHAR2, p_body VARCHAR2, p_auth VARCHAR2) RETURN CLOB IS',
'    l_req  UTL_HTTP.REQ;',
'    l_resp UTL_HTTP.RESP;',
'    l_buf  VARCHAR2(32767);',
'    l_body CLOB;',
'  BEGIN',
'    DBMS_LOB.CREATETEMPORARY(l_body, TRUE);',
'    l_req := UTL_HTTP.BEGIN_REQUEST(url => p_url, method => ''PATCH'');',
'    UTL_HTTP.SET_HEADER(l_req, ''Authorization'', ''Basic '' || p_auth);',
'    UTL_HTTP.SET_HEADER(l_req, ''Content-Type'', ''application/json'');',
'    UTL_HTTP.SET_HEADER(l_req, ''Content-Length'', LENGTH(p_body));',
'    UTL_HTTP.WRITE_TEXT(l_req, p_body);',
'    l_resp := UTL_HTTP.GET_RESPONSE(l_req);',
'    BEGIN',
'      LOOP UTL_HTTP.READ_TEXT(l_resp, l_buf, 32767);',
'        DBMS_LOB.WRITEAPPEND(l_body, LENGTH(l_buf), l_buf);',
'      END LOOP;',
'    EXCEPTION WHEN UTL_HTTP.END_OF_BODY THEN UTL_HTTP.END_RESPONSE(l_resp);',
'    END;',
'    RETURN l_body;',
'  EXCEPTION WHEN OTHERS THEN RETURN TO_CLOB(''[PATCH_ERR]'' || SQLERRM);',
'  END http_patch;',
'',
'  FUNCTION parse_procs(p_json CLOB) RETURN VARCHAR2 IS',
'    l_cnt NUMBER; l_out VARCHAR2(4000) := '''';',
'  BEGIN',
'    APEX_JSON.PARSE(p_json);',
'    l_cnt := NVL(APEX_JSON.GET_COUNT(''response.items''), 0);',
'    FOR i IN 1..l_cnt LOOP',
'      l_out := l_out || ''  - '' ||',
'        UPPER(NVL(APEX_JSON.GET_VARCHAR2(''response.items[%d].name'',i),''?'')) || '': '' ||',
'        UPPER(NVL(APEX_JSON.GET_VARCHAR2(''response.items[%d].status'',i),''UNKNOWN'')) || CHR(10);',
'    END LOOP;',
unistr('    IF l_cnt=0 THEN l_out := ''  (\C5C6\C74C)'' || CHR(10); END IF;'),
'    RETURN l_out;',
unistr('  EXCEPTION WHEN OTHERS THEN RETURN ''  (\D30C\C2F1\C624\B958:'' || SQLERRM || '')'' || CHR(10);'),
'  END parse_procs;',
'',
'  FUNCTION parse_msg(p_json CLOB) RETURN VARCHAR2 IS',
'  BEGIN',
'    APEX_JSON.PARSE(p_json);',
'    RETURN NVL(APEX_JSON.GET_VARCHAR2(''messages[1].title''), SUBSTR(p_json,1,200));',
'  EXCEPTION WHEN OTHERS THEN RETURN SUBSTR(p_json,1,200);',
'  END parse_msg;',
'',
'BEGIN',
unistr('  -- 0. ai_chat_config \D14C\C774\BE14\C5D0\C11C System Prompt \B85C\B4DC'),
'  BEGIN',
'    SELECT config_value INTO l_system',
'    FROM ggadmin.ai_chat_config',
'    WHERE app_id = 101 AND config_key = ''SYSTEM_PROMPT'';',
'  EXCEPTION WHEN NO_DATA_FOUND THEN',
'    l_system := ''You are an Oracle GoldenGate expert AI assistant. Answer in Korean when question is in Korean.'';',
'  END;',
'',
unistr('  -- 1. \BA85\B839 \C758\B3C4 \AC10\C9C0'),
unistr('  IF REGEXP_LIKE(UPPER(l_question), ''START|\AE30\B3D9|\C2DC\C791|\C2E4\D589|\C62C\B824|\B744\C6CC'') THEN'),
'    l_cmd_type := ''running'';',
unistr('  ELSIF REGEXP_LIKE(UPPER(l_question), ''STOP|\C911\C9C0|\C815\C9C0|\BA48\CDB0|\B0B4\B824'') THEN'),
'    l_cmd_type := ''stopped'';',
'  END IF;',
'',
unistr('  -- 2. \D504\B85C\C138\C2A4 \C774\B984 \CD94\CD9C'),
'  l_proc_nm := UPPER(REGEXP_SUBSTR(UPPER(l_question), ''[A-Z][0-9]{2}'', 1, 1));',
'  IF l_proc_nm IS NULL THEN',
'    l_proc_nm := REGEXP_SUBSTR(UPPER(l_question), ''KAFKA'', 1, 1);',
'  END IF;',
'',
unistr('  -- 3. \BA85\B839 \C2E4\D589'),
'  IF l_cmd_type IS NOT NULL AND l_proc_nm IS NOT NULL THEN',
unistr('    IF REGEXP_LIKE(UPPER(l_question), ''EXTRACT|\CD94\CD9C'') OR l_proc_nm LIKE ''C%'' OR l_proc_nm LIKE ''E%'' THEN'),
'      l_res_type := ''extracts'';',
'    ELSE',
'      l_res_type := ''replicats'';',
'    END IF;',
'    l_ogg_host := ''http://172.28.0.5:9012'';',
'',
'    DECLARE',
'      l_patch_url  VARCHAR2(500) := l_ogg_host || ''/services/v2/'' || l_res_type || ''/'' || l_proc_nm;',
'      l_patch_body VARCHAR2(100) := ''{"status": "'' || l_cmd_type || ''"}'';',
'      l_patch_resp CLOB;',
unistr('      l_label      VARCHAR2(20) := CASE l_cmd_type WHEN ''running'' THEN ''\AE30\B3D9'' ELSE ''\C911\C9C0'' END;'),
'    BEGIN',
'      l_patch_resp := http_patch(l_patch_url, l_patch_body, l_auth);',
unistr('      l_cmd_ctx := ''[\BA85\B839 \C2E4\D589 \ACB0\ACFC]'' || CHR(10) ||'),
unistr('        l_proc_nm || '' '' || l_label || '' \BA85\B839 \2192 '' || parse_msg(l_patch_resp) || CHR(10);'),
'    END;',
'  END IF;',
'',
unistr('  -- 4. GoldenGate \C2E4\C2DC\AC04 \C0C1\D0DC \C870\D68C'),
'  l_ext_json := http_get(''http://172.28.0.5:80/services/v2/extracts'', l_auth);',
'  l_rep_json := http_get(''http://172.28.0.5:80/services/v2/replicats'', l_auth);',
'  l_bd_json  := http_get(''http://172.28.0.6:80/services/v2/replicats'', l_auth);',
'',
unistr('  l_context := ''[GoldenGate \C2E4\C2DC\AC04 \C0C1\D0DC]'' || CHR(10);'),
'  l_context := l_context || ''OGG Hub Extracts:''     || CHR(10) || parse_procs(l_ext_json);',
'  l_context := l_context || ''OGG Hub Replicats:''    || CHR(10) || parse_procs(l_rep_json);',
'  l_context := l_context || ''OGG BigData Replicats:''|| CHR(10) || parse_procs(l_bd_json);',
'',
unistr('  -- 5. \B85C\ADF8 \C870\D68C'),
unistr('  IF REGEXP_LIKE(UPPER(l_question), ''LOG|\B85C\ADF8|\C774\C720|\C6D0\C778|\C65C|WHY|REASON|ERROR|\D655\C778|ABEND|STOP|\C911\C9C0'') THEN'),
unistr('    l_log_ctx := ''[\B85C\ADF8 \B0B4\C6A9]'' || CHR(10);'),
'    IF l_proc_nm IS NOT NULL THEN',
unistr('      l_log_ctx := l_log_ctx || ''ggserr.log ('' || l_proc_nm || '' \AD00\B828 \CD5C\ADFC 15\C904):'' || CHR(10);'),
'      l_log_ctx := l_log_ctx || SUBSTR(http_get(',
'        ''http://172.28.0.5:8765/api/ggserr?proc='' || l_proc_nm || ''&lines=15''), 1, 3000) || CHR(10);',
unistr('      l_log_ctx := l_log_ctx || ''Report ('' || l_proc_nm || ''.rpt \CD5C\ADFC 20\C904):'' || CHR(10);'),
'      l_log_ctx := l_log_ctx || SUBSTR(http_get(',
'        ''http://172.28.0.5:8765/api/report?proc='' || l_proc_nm || ''&lines=20''), 1, 2000) || CHR(10);',
'    ELSE',
unistr('      l_log_ctx := l_log_ctx || ''ggserr.log \CD5C\ADFC 20\C904:'' || CHR(10);'),
'      l_log_ctx := l_log_ctx || SUBSTR(http_get(''http://172.28.0.5:8765/api/ggserr?lines=20''), 1, 3000) || CHR(10);',
'    END IF;',
'  END IF;',
'',
unistr('  -- 6. AI \D638\CD9C'),
'  l_prompt := TO_CLOB(l_context);',
'  IF l_cmd_ctx IS NOT NULL THEN',
'    l_prompt := l_prompt || CHR(10) || l_cmd_ctx;',
'  END IF;',
'  IF l_log_ctx IS NOT NULL THEN',
'    l_prompt := l_prompt || CHR(10) || l_log_ctx;',
'  END IF;',
unistr('  l_prompt := l_prompt || CHR(10) || ''[\C9C8\BB38]: '' || l_question;'),
'',
'  l_resp := APEX_AI.GENERATE(',
'    p_prompt            => l_prompt,',
'    p_system_prompt     => l_system,',
'    p_service_static_id => ''OCI_GENAI_SVC'');',
'  HTP.P(l_resp);',
'EXCEPTION WHEN OTHERS THEN',
unistr('  HTP.P(''[\C624\B958] '' || SQLERRM);'),
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>41035
);
end;
