unistr('  APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE := ''\C800\C7A5\B418\C5C8\C2B5\B2C8\B2E4. AI Chat\C5D0 \C989\C2DC \BC18\C601\B429\B2C8\B2E4.'';'),
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>4613935062738234
);
