'        for(i=0;i<ex.length;i++){p=ex[i];h+=''<span style="margin:0 6px">''+p.name+'' ''+stBadge(p.status)+''</span>'';}',
'        var re=o.replicats||[];',
'        for(i=0;i<re.length;i++){p=re[i];h+=''<span style="margin:0 6px">''+p.name+'' ''+stBadge(p.status)+''</span>'';}',
