wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(10228337575585180)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'RAG_CHAT'
,p_static_id=>'rag-chat'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_auth    VARCHAR2(200) := ''Basic b2dnYWRtaW46V0VsY29tZTEyMzQjIw=='';',
'  l_ext_url VARCHAR2(500);',
'  l_rep_url VARCHAR2(500);',
'  l_q       VARCHAR2(4000) := apex_application.g_x01;',
'  l_ctx     CLOB;',
'  l_resp    CLOB;',
'',
'  FUNCTION hget(p_url VARCHAR2) RETURN CLOB IS',
'    l_req  UTL_HTTP.REQ;',
'    l_res  UTL_HTTP.RESP;',
'    l_buf  VARCHAR2(32767);',
'    l_out  CLOB;',
'  BEGIN',
'    DBMS_LOB.CREATETEMPORARY(l_out, TRUE);',
'    l_req := UTL_HTTP.BEGIN_REQUEST(p_url, ''GET'');',
'    UTL_HTTP.SET_HEADER(l_req, ''Authorization'', l_auth);',
'    UTL_HTTP.SET_HEADER(l_req, ''Accept'', ''application/json'');',
'    l_res := UTL_HTTP.GET_RESPONSE(l_req);',
'    BEGIN',
'      LOOP',
'        UTL_HTTP.READ_TEXT(l_res, l_buf, 32766);',
'        DBMS_LOB.APPEND(l_out, l_buf);',
'      END LOOP;',
'    EXCEPTION WHEN UTL_HTTP.END_OF_BODY THEN NULL;',
'    END;',
'    UTL_HTTP.END_RESPONSE(l_res);',
'    RETURN l_out;',
'  EXCEPTION WHEN OTHERS THEN',
'    RETURN ''{"error":"'' || REPLACE(SQLERRM, ''"'', '''') || ''"}'';',
'  END;',
'',
'BEGIN',
'  SELECT gubun1||'':''||gubun2||gubun3 INTO l_ext_url',
'  FROM ggadmin.ogg_conf WHERE keya=''EXTRACTURL'' AND keyb=''ADMIN'';',
'  SELECT gubun1||'':''||gubun2||gubun3 INTO l_rep_url',
'  FROM ggadmin.ogg_conf WHERE keya=''REPLICATURL'' AND keyb=''ADMIN'';',
'',
'  DBMS_LOB.CREATETEMPORARY(l_ctx, TRUE);',
'  DBMS_LOB.APPEND(l_ctx, TO_CLOB(''=== GoldenGate Live Status ==='' || CHR(10)));',
'  DBMS_LOB.APPEND(l_ctx, TO_CLOB(''Extracts: ''));',
'  DBMS_LOB.APPEND(l_ctx, hget(l_ext_url || ''/extracts''));',
'  DBMS_LOB.APPEND(l_ctx, TO_CLOB(CHR(10) || ''Replicats: ''));',
'  DBMS_LOB.APPEND(l_ctx, hget(l_rep_url || ''/replicats''));',
'  DBMS_LOB.APPEND(l_ctx, TO_CLOB(CHR(10) || CHR(10) || ''=== Question ==='' || CHR(10)));',
'  DBMS_LOB.APPEND(l_ctx, TO_CLOB(l_q));',
'',
'  l_resp := APEX_AI.GENERATE(',
'    p_prompt            => l_ctx,',
'    p_system_prompt     => ''You are a GoldenGate expert assistant. Answer in Korean using the live status data provided. Be concise and accurate.'',',
'    p_service_static_id => ''OCI_GENAI_SVC'');',
'',
'  HTP.P(l_resp);',
'  DBMS_LOB.FREETEMPORARY(l_ctx);',
'EXCEPTION WHEN OTHERS THEN',
'  HTP.P(''ERROR: '' || SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>54979
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(10228337575585184)
,p_process_sequence=>5
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'RAG_STATUS'
,p_static_id=>'rag-status'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_auth    VARCHAR2(200) := ''Basic b2dnYWRtaW46V0VsY29tZTEyMzQjIw=='';',
'  l_ext_url VARCHAR2(500);',
'  l_rep_url VARCHAR2(500);',
'  l_ext_json CLOB;',
'  l_rep_json CLOB;',
'  l_cnt NUMBER;',
'',
'  FUNCTION hget(p_url VARCHAR2) RETURN CLOB IS',
'    lr UTL_HTTP.REQ; lp UTL_HTTP.RESP; lb VARCHAR2(32767); lo CLOB;',
'  BEGIN',
'    DBMS_LOB.CREATETEMPORARY(lo,TRUE);',
'    lr:=UTL_HTTP.BEGIN_REQUEST(p_url,''GET'');',
'    UTL_HTTP.SET_HEADER(lr,''Authorization'',l_auth);',
'    UTL_HTTP.SET_HEADER(lr,''Accept'',''application/json'');',
'    lp:=UTL_HTTP.GET_RESPONSE(lr);',
'    BEGIN LOOP UTL_HTTP.READ_TEXT(lp,lb,32767); DBMS_LOB.WRITEAPPEND(lo,LENGTH(lb),lb); END LOOP;',
'    EXCEPTION WHEN UTL_HTTP.END_OF_BODY THEN UTL_HTTP.END_RESPONSE(lp); END;',
'    RETURN lo;',
'  EXCEPTION WHEN OTHERS THEN RETURN TO_CLOB(''{"error":"''||SQLERRM||''"}'');',
'  END;',
'BEGIN',
'  SELECT gubun1||'':''||gubun2||gubun3 INTO l_ext_url FROM ggadmin.ogg_conf WHERE keya=''EXTRACTURL'' AND keyb=''ADMIN'';',
'  SELECT gubun1||'':''||gubun2||gubun3 INTO l_rep_url FROM ggadmin.ogg_conf WHERE keya=''REPLICATURL'' AND keyb=''ADMIN'';',
'  l_ext_json:=hget(l_ext_url||''/extracts'');',
'  l_rep_json:=hget(l_rep_url||''/replicats'');',
'  APEX_JSON.INITIALIZE_CLOB_OUTPUT;',
'  APEX_JSON.OPEN_OBJECT;',
'  APEX_JSON.OPEN_ARRAY(''extracts'');',
'  BEGIN',
'    APEX_JSON.PARSE(l_ext_json);',
'    l_cnt:=NVL(APEX_JSON.GET_COUNT(''response.items''),0);',
'    FOR i IN 1..l_cnt LOOP',
'      APEX_JSON.OPEN_OBJECT;',
'      APEX_JSON.WRITE(''name'',NVL(APEX_JSON.GET_VARCHAR2(''response.items[%d].name'',i),''?''));',
'      APEX_JSON.WRITE(''status'',NVL(APEX_JSON.GET_VARCHAR2(''response.items[%d].status'',i),''UNKNOWN''));',
'      APEX_JSON.CLOSE_OBJECT;',
'    END LOOP;',
'  EXCEPTION WHEN OTHERS THEN NULL; END;',
'  APEX_JSON.CLOSE_ARRAY;',
'  APEX_JSON.OPEN_ARRAY(''replicats'');',
'  BEGIN',
'    APEX_JSON.PARSE(l_rep_json);',
'    l_cnt:=NVL(APEX_JSON.GET_COUNT(''response.items''),0);',
'    FOR i IN 1..l_cnt LOOP',
'      APEX_JSON.OPEN_OBJECT;',
'      APEX_JSON.WRITE(''name'',NVL(APEX_JSON.GET_VARCHAR2(''response.items[%d].name'',i),''?''));',
'      APEX_JSON.WRITE(''status'',NVL(APEX_JSON.GET_VARCHAR2(''response.items[%d].status'',i),''UNKNOWN''));',
'      APEX_JSON.CLOSE_OBJECT;',
'    END LOOP;',
'  EXCEPTION WHEN OTHERS THEN NULL; END;',
'  APEX_JSON.CLOSE_ARRAY;',
'  APEX_JSON.CLOSE_OBJECT;',
'  HTP.P(APEX_JSON.GET_CLOB_OUTPUT);',
'  APEX_JSON.FREE_OUTPUT;',
'EXCEPTION WHEN OTHERS THEN',
'  HTP.P(''{"extracts":[],"replicats":[],"error":"''||SQLERRM||''"}'');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>54975
);
end;
/
