,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_q      VARCHAR2(4000) := apex_application.g_x01;',
'  l_q_up   VARCHAR2(4000) := UPPER(NVL(apex_application.g_x01, ''''));',
'  l_proc   VARCHAR2(128);',
'  l_msgs   APEX_AI.T_CHAT_MESSAGES := APEX_AI.T_CHAT_MESSAGES();',
'  l_tools  APEX_AI.T_TOOLS;',
'  l_tool   APEX_AI.T_TOOL;',
'  l_prms   APEX_AI.T_TOOL_PARAMETERS;',
'  l_prm    APEX_AI.T_TOOL_PARAMETER;',
'  l_ans    CLOB;',
'  l_result CLOB;',
'  l_status VARCHAR2(30);',
'  l_has_tx VARCHAR2(10);',
'  l_reply  VARCHAR2(32767);',
'  l_error  VARCHAR2(32767);',
'  l_http   NUMBER;',
'',
'  FUNCTION has_showtrans_intent RETURN BOOLEAN IS',
'  BEGIN',
'    RETURN INSTR(l_q_up, ''SHOWTRANS'') > 0',
'        OR INSTR(l_q_up, ''LONG TX'') > 0',
'        OR INSTR(l_q_up, ''LONG TRANSACTION'') > 0',
'        OR INSTR(l_q_up, ''LONG-RUNNING'') > 0',
'        OR INSTR(l_q_up, ''UNCOMMITTED'') > 0',
'        OR INSTR(l_q_up, ''OPEN TRANSACTION'') > 0',
unistr('        OR INSTR(l_q, ''\B871\D2B8\B79C\C7AD\C158'') > 0'),
unistr('        OR INSTR(l_q, ''\B871 \D2B8\B79C\C7AD\C158'') > 0'),
unistr('        OR INSTR(l_q, ''\C7A5\AE30 \D2B8\B79C\C7AD\C158'') > 0'),
unistr('        OR INSTR(l_q, ''\BBF8\CEE4\BC0B'') > 0'),
unistr('        OR INSTR(l_q, ''\CEE4\BC0B\B418\C9C0'') > 0'),
unistr('        OR (INSTR(l_q_up, ''COMMIT'') > 0 AND (INSTR(l_q_up, ''TRANSACTION'') > 0 OR INSTR(l_q, ''\D2B8\B79C\C7AD\C158'') > 0))'),
unistr('        OR (INSTR(l_q, ''\CEE4\BC0B'') > 0 AND INSTR(l_q, ''\D2B8\B79C\C7AD\C158'') > 0);'),
'  END;',
'',
'  FUNCTION detect_process_name RETURN VARCHAR2 IS',
'    l_name VARCHAR2(128);',
'  BEGIN',
'    l_name := REGEXP_SUBSTR(l_q_up, ''[A-Z_$][A-Z0-9_$]{0,7}[0-9][A-Z0-9_$]{0,7}'');',
'    IF l_name IS NOT NULL AND REGEXP_LIKE(l_name, ''^[A-Z_$][A-Z0-9_$]{0,7}$'') THEN',
'      RETURN l_name;',
'    END IF;',
'    RETURN NULL;',
'  END;',
'',
'  PROCEDURE emit_json(p_answer IN CLOB, p_tool_log IN VARCHAR2 DEFAULT ''[]'') IS',
'  BEGIN',
'    APEX_JSON.INITIALIZE_CLOB_OUTPUT;',
'    APEX_JSON.OPEN_OBJECT;',
'    APEX_JSON.WRITE(''answer'', p_answer);',
'    APEX_JSON.WRITE_RAW(''tool_log'', p_tool_log);',
'    APEX_JSON.CLOSE_OBJECT;',
'    HTP.P(APEX_JSON.GET_CLOB_OUTPUT);',
'    APEX_JSON.FREE_OUTPUT;',
'  END;',
'BEGIN',
'  IF has_showtrans_intent THEN',
'    l_proc := detect_process_name;',
'',
'    IF l_proc IS NULL THEN',
'      emit_json(',
unistr('        ''long transaction \D655\C778 \C694\CCAD\C73C\B85C \C774\D574\D588\C2B5\B2C8\B2E4.'' || CHR(10) ||'),
unistr('        ''\B2E4\B9CC Extract process \C774\B984\C744 \CC3E\C9C0 \BABB\D588\C2B5\B2C8\B2E4. \C608: C01 long tx \C788\C5B4? \B610\B294 SEND EXTRACT C01 SHOWTRANS\CC98\B7FC process \C774\B984\C744 \C9C0\C815\D574 \C8FC\C138\C694.'''),
'      );',
'      RETURN;',
'    END IF;',
'',
'    begin',
'      execute immediate ''begin :x := ggadmin.gg_show_transactions_json(:p); end;'' using out l_result, in l_proc;',
'    exception',
'      when others then',
'        l_result := ''{"error":"Install optional GoldenGate tool helper function to run SHOWTRANS."}'';',
'    end;',
'',
'    BEGIN',
'      APEX_JSON.PARSE(l_result);',
'      l_status := APEX_JSON.GET_VARCHAR2(''status'');',
'      l_has_tx := APEX_JSON.GET_VARCHAR2(''has_open_transactions'');',
'      l_reply  := APEX_JSON.GET_VARCHAR2(''reply'');',
'      l_error  := APEX_JSON.GET_VARCHAR2(''error'');',
'      l_http   := APEX_JSON.GET_NUMBER(''http_status'');',
'    EXCEPTION',
'      WHEN OTHERS THEN',
'        l_status := ''ERROR'';',
'        l_error := SQLERRM;',
'    END;',
'',
'    IF l_status = ''ERROR'' THEN',
unistr('      l_ans := ''SEND EXTRACT '' || l_proc || '' SHOWTRANS \C2E4\D589\C744 \C2DC\B3C4\D588\C9C0\B9CC \C624\B958\AC00 \BC1C\C0DD\D588\C2B5\B2C8\B2E4.'' || CHR(10) ||'),
unistr('               ''\C624\B958: '' || NVL(l_error, ''unknown error'');'),
'    ELSIF l_has_tx = ''N'' THEN',
unistr('      l_ans := ''SEND EXTRACT '' || l_proc || '' SHOWTRANS \ACB0\ACFC, \D604\C7AC open/long-running transaction\C740 \BC1C\ACAC\B418\C9C0 \C54A\C558\C2B5\B2C8\B2E4.'' || CHR(10) ||'),
unistr('               ''\ADFC\AC70: '' || NVL(l_reply, ''No transactions found.'');'),
'    ELSIF l_has_tx = ''Y'' THEN',
unistr('      l_ans := ''SEND EXTRACT '' || l_proc || '' SHOWTRANS \ACB0\ACFC, open transaction \C815\BCF4\AC00 \BC1C\ACAC\B418\C5C8\C2B5\B2C8\B2E4.'' || CHR(10) ||'),
unistr('               ''PM \C791\C5C5\C774\B098 Extract stop \C804\C5D0 XID/SCN\C744 \D655\C778\D558\ACE0 DBA \B610\B294 \C5C5\BB34 \B2F4\B2F9\C790\C640 skip/kill \C5EC\BD80\B97C \D310\B2E8\D574\C57C \D569\B2C8\B2E4.'' || CHR(10) ||'),
unistr('               ''\ACB0\ACFC: '' || NVL(l_reply, ''(no reply text)'');'),
'    ELSE',
unistr('      l_ans := ''SEND EXTRACT '' || l_proc || '' SHOWTRANS\B97C \C218\D589\D588\C2B5\B2C8\B2E4. \B2E4\B9CC \ACB0\ACFC\B97C \C790\B3D9\C73C\B85C \B2E8\C815\D558\AE30 \C5B4\B824\C6CC \C6D0\BB38 \D655\C778\C774 \D544\C694\D569\B2C8\B2E4.'' || CHR(10) ||'),
unistr('               ''\ACB0\ACFC: '' || NVL(l_reply, ''(no reply text)'');'),
'    END IF;',
'',
'    emit_json(',
'      l_ans,',
'      ''[{"name":"show_transactions","args":{"process_name":"'' || l_proc || ''","command":"SHOWTRANS","http_status":'' || NVL(TO_CHAR(l_http), ''null'') || ''}}]''',
'    );',
'    RETURN;',
'  END IF;',
'',
'  -- Tool 1: get_gg_status',
'  l_tool.name := ''get_gg_status'';',
'  l_tool.description := ''Get current status, lag, and checkpoint summary of GoldenGate Extract and Replicat processes. This tool cannot determine SHOWTRANS, open transactions, uncommitted transactions, or long-running transactions.'';',
'  l_tool.parameters := APEX_AI.T_TOOL_PARAMETERS();',
'  l_tool.callback_procedure := ''ggadmin.gg_tool_get_status'';',
'  l_tools := APEX_AI.T_TOOLS(l_tool);',
'',
'  -- Tool 2: control_process',
'  l_tool.name := ''control_process'';',
'  l_tool.description := ''Start or stop a GoldenGate process. Call get_gg_status first to confirm process type. Do not stop an Extract for PM or maintenance unless SHOWTRANS evidence has already proved that there are no long-running/open transactions.'
||''';',
'  l_prms := APEX_AI.T_TOOL_PARAMETERS();',
'',
'  l_prm.name := ''process_name'';',
'  l_prm.description := ''Process name, for example C01 or CAP01.'';',
'  l_prm.data_type := ''VARCHAR2'';',
'  l_prm.is_required := TRUE;',
'  l_prms.EXTEND; l_prms(1) := l_prm;',
'',
'  l_prm.name := ''action'';',
'  l_prm.description := ''Action to perform: START or STOP.'';',
'  l_prm.data_type := ''VARCHAR2'';',
'  l_prm.is_required := TRUE;',
'  l_prms.EXTEND; l_prms(2) := l_prm;',
'',
'  l_prm.name := ''process_type'';',
'  l_prm.description := ''Process type: EXTRACT or REPLICAT.'';',
'  l_prm.data_type := ''VARCHAR2'';',
'  l_prm.is_required := TRUE;',
'  l_prms.EXTEND; l_prms(3) := l_prm;',
'',
'  l_tool.parameters := l_prms;',
'  l_tool.callback_procedure := ''ggadmin.gg_tool_control'';',
'  l_tools.EXTEND; l_tools(2) := l_tool;',
'',
'  -- Tool 3: show_transactions',
'  l_tool.name := ''show_transactions'';',
'  l_tool.description := ''Execute SHOWTRANS for a named Extract process and return whether open or long-running transactions are visible. Use this for long tx, long transaction, uncommitted transaction, open transaction, SHOWTRANS, and PM stop safety '
||'checks.'';',
'  l_prms := APEX_AI.T_TOOL_PARAMETERS();',
'',
'  l_prm.name := ''process_name'';',
'  l_prm.description := ''Extract process name, for example C01.'';',
'  l_prm.data_type := ''VARCHAR2'';',
'  l_prm.is_required := TRUE;',
'  l_prms.EXTEND; l_prms(1) := l_prm;',
'',
'  l_tool.parameters := l_prms;',
'  l_tool.callback_procedure := ''ggadmin.gg_tool_show_transactions'';',
'  l_tools.EXTEND; l_tools(3) := l_tool;',
'',
'  l_ans := APEX_AI.CHAT(',
'    p_prompt => l_q,',
'    p_system_prompt => q''[You are GoldenGate MCP Native Tool Assistant for an Oracle GoldenGate MSA operations console.',
'',
'Answer in Korean.',
'',
'Important distinction:',
'- Process status means whether an Extract or Replicat is RUNNING, STOPPED, or ABENDED.',
'- Long-running transaction status means whether an Extract has open or uncommitted transactions. This is checked by SHOWTRANS.',
'- Lag/checkpoint/status information does not prove whether long-running transactions exist.',
'',
'Tool rules:',
'- Use get_gg_status only for process status, lag, checkpoint, and process summary.',
unistr('- Use show_transactions for long tx, long transaction, long-running transaction, SHOWTRANS, uncommitted transaction, open transaction, commit \C548 \D55C transaction, \BBF8\CEE4\BC0B \D2B8\B79C\C7AD\C158, and PM stop safety checks.'),
'- Never replace SHOWTRANS with get_gg_status.',
'- Use control_process only when the requested operation is clear and safe.',
unistr('- If the user asks to stop an Extract for PM, maintenance, shutdown, restart, or "\B0B4\B824\C918", SHOWTRANS evidence is required first.'),
'- If SHOWTRANS finds open transactions, do not stop the Extract automatically.',
'',
'Truthfulness:',
unistr('- Do not say "\D655\C778\D588\C2B5\B2C8\B2E4" unless the matching tool was actually called.'),
'- State the evidence source used.',
'- Prefer concise operational answers.]'',',
'    p_service_static_id => ''OCI_GENAI_SVC'',',
'    p_messages => l_msgs,',
'    p_tools => l_tools,',
'    p_max_tool_roundtrips => 4);',
'',
'  emit_json(l_ans);',
'EXCEPTION WHEN OTHERS THEN',
'  HTP.P(''{"answer":"ERROR: '' || REPLACE(REPLACE(SQLERRM,''"'',''''),CHR(39),'''') || ''","tool_log":[]}'');',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>54994
);
end;
