'<div class="aidx">',
' <section class="aidx-header">',
'  <div class="aidx-title"><div class="aidx-icon"><i class="fa fa-stethoscope"></i></div><div><h1>AI Diagnostic Center</h1><div class="aidx-sub">Evidence-grounded GoldenGate and Oracle Database diagnosis</div></div></div>',
'  <div class="aidx-controls">',
'   <div class="aidx-field"><label>Process</label><select id="aidxProcess"><option>C01</option><option>D01</option><option>KAFKA</option><option>STROCI</option></select></div>',
'   <div class="aidx-field"><label>Time Range</label><select id="aidxRange"><option>Last 30 minutes</option><option>Last 1 hour</option><option>Latest AWR snapshot</option></select></div>',
'   <button id="aidxRun" class="aidx-run" onclick="aidxRunDiagnosis()"><i class="fa fa-magic"></i> Run AI Diagnosis</button>',
'  </div>',
' </section>',
