wwv_flow_imp.g_varchar2_table(505) := '      ''<button type="button" class="df-tab" data-df-tab="pipelines">Pipelines</button>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(506) := '      ''<button type="button" class="df-tab" data-df-tab="products">Data Products</button>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(507) := '      ''<button type="button" class="df-tab" data-df-tab="lineage">Lineage</button>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(508) := '      ''<button type="button" class="df-tab" data-df-tab="runtime">Runtime Status</button>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(509) := '      ''<button type="button" class="df-tab" data-df-tab="governance">Governance</button></div>'';'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(510) := ''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(511) := '    l_html := l_html || ''<div class="df-panel active" data-df-panel="designer">'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(512) := '      ''<div class="df-kpis"><div class="df-kpi"><div class="df-kpi-label">Fabric Nodes</div><div class="df-kpi-value">'' || l_nodes || ''</div></div>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(513) := '      ''<div class="df-kpi"><div class="df-kpi-label">Fabric Edges</div><div class="df-kpi-value">'' || l_edges || ''</div></div>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(514) := '      ''<div class="df-kpi"><div class="df-kpi-label">Data Products</div><div class="df-kpi-value">'' || l_products || ''</div></div>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(515) := '      ''<div class="df-kpi"><div class="df-kpi-label">Column Metadata</div><div class="df-kpi-value">'' || l_columns || ''</div></div></div>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(516) := '      ''<div class="df-canvas">'';'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(517) := ''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(518) := '    for lane in ('||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(519) := '      select 1 layer_no, ''Source 업무계'' lane_name from dual union all'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(520) := '      select 2, ''Capture'' from dual union all'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(521) := '      select 3, ''Trail'' from dual union all'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(522) := '      select 4, ''Stream / Apply'' from dual union all'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(523) := '      select 5, ''Lakehouse 정제'' from dual union all'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(524) := '      select 6, ''Data Product / Console'' from dual'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(525) := '      order by layer_no'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(526) := '    ) loop'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(527) := '      l_html := l_html || ''<div class="df-lane"><h2>'' || h(lane.lane_name) || ''</h2>'';'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(528) := '      for n in (select * from ggadmin.fabric_node where layer_no = lane.layer_no order by display_order, node_name) loop'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(529) := '        l_props := node_properties(n.node_code);'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(530) := '        l_html := l_html || ''<div class="df-node"><div class="df-node-title">'' || h(n.node_name) || ''</div>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(531) := '          ''<div class="df-node-type">'' || h(n.node_type) || '' · '' || h(n.system_name) || ''</div>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(532) := '          ''<div class="df-node-ref">'' || h(n.resource_ref) || ''</div>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(533) := '          ''<div class="df-node-desc">'' || h(n.description) || ''</div>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(534) := '          case when l_props is not null then ''<div class="df-node-desc">'' || h(l_props) || ''</div>'' end ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(535) := '          status_badge(n.status) || ''</div>'';'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(536) := '      end loop;'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(537) := '      l_html := l_html || ''</div>'';'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(538) := '    end loop;'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(539) := '    l_html := l_html || ''</div></div>'';'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(540) := ''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(541) := '    l_html := l_html || ''<div class="df-panel" data-df-panel="catalog"><h2 class="df-section-title">Catalog</h2><p class="df-section-note">GoldenGate runtime/parameter에서 발견된 asset과 lab metadata seed를 한 곳에서 검색합니다. 이 Catalog는 enterprise catalog가 아니라 CDC fabric 운영을 위한 lightweight operational catalog입니다.</p>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(542) := '      ''<div class="df-catalog-tools"><input class="df-catalog-search" type="search" placeholder="Search node, type, system, table, status..." aria-label="Search catalog"><span class="df-catalog-note">Verified runtime metadata와 seed/downstream artifact를 구분해서 확인합니다.</span></div>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(543) := '      ''<table class="df-table df-catalog-table"><thead><tr><th>Asset</th><th>Type</th><th>System</th><th>Reference</th><th>Provenance</th><th>Readiness</th></tr></thead><tbody>'';'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(544) := '    for n in (select * from ggadmin.fabric_node order by layer_no, display_order, node_type, node_name) loop'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(545) := '      l_props := node_properties(n.node_code);'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(546) := '      l_provenance := case'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(547) := '        when n.status = ''ACTIVE'' and n.node_type in (''OGG_EXTRACT'',''OGG_REPLICAT'',''TRAIL'',''DATA_STREAM'',''SOURCE_TABLE'') then ''Runtime / parameter discovered'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(548) := '        when n.status = ''ACTIVE'' then ''Verified runtime metadata'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(549) := '        when n.status = ''DESIGN'' then ''Design metadata'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(550) := '        when n.status = ''OFFLINE'' then ''Catalog seed / not verified'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(551) := '        else ''Catalog metadata'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(552) := '      end;'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(553) := '      l_readiness := case'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(554) := '        when n.status = ''ACTIVE'' then ''Usable'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(555) := '        when n.status = ''DESIGN'' then ''Needs implementation'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(556) := '        when n.status = ''OFFLINE'' then ''Not verified in runtime'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(557) := '        else n.status'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(558) := '      end;'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(559) := '      l_html := l_html || ''<tr class="df-catalog-row"><td><b>'' || h(n.node_name) || ''</b><br><span class="df-card-desc">'' || h(n.description) || ''</span></td>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(560) := '        ''<td>'' || h(n.node_type) || ''</td><td>'' || h(n.system_name) || ''</td><td>'' || h(n.resource_ref) || ''<br><span class="df-card-desc">'' || h(l_props) || ''</span></td>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(561) := '        ''<td>'' || h(l_provenance) || ''</td><td>'' || status_badge(n.status) || ''<br><span class="df-card-desc">'' || h(l_readiness) || ''</span></td></tr>'';'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(562) := '    end loop;'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(563) := '    l_html := l_html || ''</tbody></table><div class="df-flow"><h2>TABLE / COLUMN Dictionary Catalog</h2><p class="df-section-note">Extract TABLE, Replicat MAP, source table node에서 발견한 table 이름을 dictionary comment cache와 연결합니다. COMMENT ON TABLE/COLUMN이 있으면 여기에서 업무 의미와 column 설명으로 보입니다.</p><table class="df-table df-catalog-table"><thead><tr><th>Table</th><th>Discovered From</th><th>Table Comment</th><th>Column Metadata</th></tr></thead><tbody>'';'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(564) := '    for t in ('||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(565) := '      with prop_table_raw as ('||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(566) := '        select n.node_name process_name,'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(567) := '               p.property_name,'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(568) := '               upper(trim(regexp_substr(p.property_value, ''[^,]+'', 1, lv.lvl))) table_ref'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(569) := '          from ggadmin.fabric_node_property p'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(570) := '          join ggadmin.fabric_node n'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(571) := '            on n.node_code = p.node_code'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(572) := '          cross join (select level lvl from dual connect by level <= 300) lv'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(573) := '         where p.property_name in (''tables'',''maps'')'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(574) := '           and regexp_substr(p.property_value, ''[^,]+'', 1, lv.lvl) is not null'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(575) := '      ),'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(576) := '      prop_tables as ('||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(577) := '        select table_ref,'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(578) := '               listagg(process_name || '' '' || upper(property_name), '', '') within group (order by process_name, property_name) discovered_by'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(579) := '          from ('||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(580) := '            select distinct table_ref, process_name, property_name'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(581) := '              from prop_table_raw'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(582) := '             where table_ref like ''%.%'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(583) := '               and table_ref not like ''%*%'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(584) := '          )'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(585) := '         group by table_ref'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(586) := '      ),'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(587) := '      node_tables as ('||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(588) := '        select upper(resource_ref) table_ref,'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(589) := '               listagg(node_name, '', '') within group (order by node_name) discovered_by'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(590) := '          from ggadmin.fabric_node'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(591) := '         where node_type = ''SOURCE_TABLE'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(592) := '           and resource_ref like ''%.%'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(593) := '         group by upper(resource_ref)'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(594) := '      ),'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(595) := '      table_refs as ('||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(596) := '        select table_ref,'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(597) := '               listagg(discovered_by, '', '') within group (order by discovered_by) discovered_by'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(598) := '          from ('||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(599) := '            select table_ref, discovered_by from prop_tables'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(600) := '            union all'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(601) := '            select table_ref, discovered_by from node_tables'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(602) := '          )'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(603) := '         group by table_ref'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(604) := '      )'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(605) := '      select r.table_ref,'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(606) := '             r.discovered_by,'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(607) := '             nvl(max(n.description), ''No table comment cached'') table_comment,'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(608) := '             count(c.column_name) column_count,'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(609) := '             count(c.column_comment) commented_count,'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(610) := '             ('||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(611) := '               select listagg(column_name || '' '' || data_type ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(612) := '                              case when column_comment is not null then '' - '' || column_comment end,'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(613) := '                              chr(10)) within group (order by column_id)'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(614) := '                 from ('||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(615) := '                   select column_name, data_type, column_comment, column_id'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(616) := '                     from ggadmin.fabric_table_column'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(617) := '                    where owner_name = substr(r.table_ref, 1, instr(r.table_ref, ''.'') - 1)'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(618) := '                      and table_name = substr(r.table_ref, instr(r.table_ref, ''.'') + 1)'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(619) := '                    order by column_id'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(620) := '                    fetch first 8 rows only'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(621) := '                 )'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(622) := '             ) column_sample'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(623) := '        from table_refs r'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(624) := '        left join ggadmin.fabric_node n'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(625) := '          on n.node_type = ''SOURCE_TABLE'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(626) := '         and upper(n.resource_ref) = r.table_ref'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(627) := '        left join ggadmin.fabric_table_column c'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(628) := '          on c.owner_name = substr(r.table_ref, 1, instr(r.table_ref, ''.'') - 1)'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(629) := '         and c.table_name = substr(r.table_ref, instr(r.table_ref, ''.'') + 1)'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(630) := '       group by r.table_ref, r.discovered_by'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(631) := '       order by r.table_ref'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(632) := '    ) loop'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(633) := '      l_html := l_html || ''<tr class="df-catalog-row"><td><b>'' || h(t.table_ref) || ''</b></td>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(634) := '        ''<td>'' || h(t.discovered_by) || ''</td>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(635) := '        ''<td>'' || h(t.table_comment) || ''</td>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(636) := '        ''<td><b>'' || to_char(t.column_count) || '' columns · '' || to_char(t.commented_count) || '' comments</b><br><span class="df-card-desc">'' || replace(h(t.column_sample), chr(10), ''<br>'') || ''</span></td></tr>'';'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(637) := '    end loop;'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(638) := '    l_html := l_html || ''</tbody></table></div></div>'';'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(639) := ''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(640) := '    l_html := l_html || ''<div class="df-panel" data-df-panel="assets"><h2 class="df-section-title">Assets</h2><p class="df-section-note">Fabric을 구성하는 source table, GoldenGate process, trail, stream, lakehouse table, dashboard asset을 유형별로 확인합니다.</p><div class="df-grid">'';'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(641) := '    for n in (select * from ggadmin.fabric_node order by node_type, layer_no, display_order, node_name) loop'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(642) := '      l_props := node_properties(n.node_code);'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(643) := '      l_html := l_html || ''<div class="df-card"><div class="df-card-title">'' || h(n.node_name) || ''</div>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(644) := '        ''<div class="df-card-meta">'' || h(n.node_type) || '' · '' || h(n.system_name) || ''</div>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(645) := '        ''<div class="df-node-ref">'' || h(n.resource_ref) || ''</div>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(646) := '        ''<div class="df-card-desc">'' || h(n.description) || ''</div>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(647) := '        case when l_props is not null then ''<div class="df-card-desc">'' || h(l_props) || ''</div>'' end ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(648) := '        status_badge(n.status) || ''</div>'';'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(649) := '    end loop;'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(650) := '    l_html := l_html || ''</div></div>'';'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(651) := ''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(652) := '    l_html := l_html || ''<div class="df-panel" data-df-panel="pipelines"><h2 class="df-section-title">Pipelines</h2><p class="df-section-note">FC01은 일반 table lane, FC02는 heavy table lane으로 분리합니다. Replicat, Kafka 후보, Data Stream, Iceberg 경로를 같은 metadata plane에서 함께 추적합니다.</p>'';'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(653) := '    for e in ('||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(654) := '      select e.edge_type, e.mapping_ref, e.description, e.status, f.node_name from_name, t.node_name to_name'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(655) := '        from ggadmin.fabric_edge e'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(656) := '        join ggadmin.fabric_node f on f.node_code = e.from_node_code'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(657) := '        join ggadmin.fabric_node t on t.node_code = e.to_node_code'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(658) := '       where e.edge_type in (''CAPTURE'',''WRITE_TRAIL'',''APPLY'',''PUBLISH_STREAM'',''APPEND_BRONZE'',''BUILD_SILVER'',''BUILD_GOLD'',''SERVE_DASHBOARD'')'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(659) := '       order by f.layer_no, f.display_order, t.layer_no, t.display_order, e.edge_code'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(660) := '    ) loop'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(661) := '      l_html := l_html || ''<div class="df-flow-row"><div><div class="df-flow-node">'' || h(e.from_name) || ''</div><div class="df-flow-type">'' || h(e.edge_type) || ''</div></div>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(662) := '        ''<div>→</div><div><div class="df-flow-node">'' || h(e.to_name) || ''</div><div class="df-flow-type">'' || h(e.mapping_ref) || ''</div></div>'' ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(663) := '        ''<div class="df-flow-desc">'' || h(e.description) || '' '' || status_badge(e.status) || ''</div></div>'';'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(664) := '    end loop;'||wwv_flow.LF;
