wwv_flow_imp.g_varchar2_table(677) := '    end;'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(678) := '    begin'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(679) := '      select status into l_stream_status from ggadmin.fabric_node where node_code = ''OGG_DATA_STREAM_DS_LAKE'';'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(680) := '    exception'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(681) := '      when no_data_found then'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(682) := '        l_stream_status := ''UNKNOWN'';'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(683) := '    end;'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(684) := ''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(685) := '    for n in ('||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(686) := '      select *'||wwv_flow.LF;
