wwv_flow_imp.g_varchar2_table(688) := '       where node_type in (''LAKEHOUSE_TABLE'',''TRANSFORM_JOB'',''DATA_PRODUCT'',''DASHBOARD'')'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(689) := '       order by layer_no, display_order'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(690) := '    ) loop'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(691) := '      l_lineage := case n.node_code'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(692) := '        when ''ICEBERG_BRONZE_CFUND'' then ''FC02 -> k2 -> DS_LAKE -> Bronze'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(693) := '        when ''ICEBERG_SILVER_ACTIVITY'' then ''FC02 -> k2 -> DS_LAKE -> Bronze -> Silver'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(694) := '        when ''ICEBERG_GOLD_ACTION'' then ''FC02 -> k2 -> DS_LAKE -> Bronze -> Silver -> Gold'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(695) := '        when ''DASHBOARD_GOLD_CHANNEL'' then ''FC02 -> k2 -> DS_LAKE -> Bronze -> Silver -> Gold -> Dashboard'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(696) := '        else ''Lineage metadata is not verified yet'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(697) := '      end;'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(698) := '      l_serving_target := case n.node_type'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(699) := '        when ''LAKEHOUSE_TABLE'' then ''Lakehouse table'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(700) := '        when ''TRANSFORM_JOB'' then ''Transform / curated table'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(701) := '        when ''DATA_PRODUCT'' then ''Business data product'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(702) := '        when ''DASHBOARD'' then ''Dashboard / report'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(703) := '        else n.node_type'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(704) := '      end;'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(705) := '      l_provenance := case'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(706) := '        when n.status = ''ACTIVE'' then ''VERIFIED'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(707) := '        when n.status = ''DESIGN'' then ''DESIGN'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(708) := '        else ''SEED / NOT VERIFIED'''||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(709) := '      end;'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(710) := '      l_readiness :='||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(711) := '        ''Source mapped: '' || case when l_source_tables is not null then ''PASS'' else ''CHECK'' end || chr(10) ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(712) := '        ''Stream node: '' || nvl(l_stream_status, ''UNKNOWN'') || chr(10) ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(713) := '        ''Target asset: '' || n.status || chr(10) ||'||wwv_flow.LF;
wwv_flow_imp.g_varchar2_table(714) := '        ''Owner: not assigned'';'||wwv_flow.LF;
